with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('conversaciones-empresariales-mas-alla-del-credito', 'Conversaciones empresariales más allá del crédito', 100, true, 5, 'relaciones', 'micro',
          16, 'Principiante', array['financiero']::text[], 'free', false, false, true, false,
          null, 'Pasa de ofrecer productos a entender la agenda del gerente.', 't-diag', 160, '2026-01-01')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Pasar de ofrecer productos a entender la agenda del gerente","Las preguntas que abren conversaciones estratégicas","Cómo aportar perspectiva y no solo información","Cómo convertir la conversación en una relación de largo plazo"],"contexto":"Un gerente recibe decenas de ofertas de productos financieros cada mes. Lo que escasea no son los productos, sino los interlocutores que entienden su negocio y le ayudan a pensar. El ejecutivo que pasa de “¿necesita un crédito?” a “¿qué está priorizando este año?” cambia su lugar en la relación.\n\nInvestigaciones de Gartner sobre el comportamiento de compradores B2B indican que estos dedican solo una pequeña parte de su proceso de compra —alrededor del 17% del tiempo— a reunirse con potenciales proveedores, repartida entre todos los que evalúan. Cada minuto de conversación cuenta. Los compradores valoran a quien les aporta una perspectiva nueva sobre su negocio, no a quien repite lo que ya encontraron por su cuenta.","lecciones":[{"titulo":"La agenda del gerente","texto":"Crecimiento, márgenes, caja, talento y riesgo: los cinco temas que ocupan la cabeza de un gerente.\n\nAntes de cualquier reunión, pregúntate cuál de estos temas es más urgente para tu cliente. Una empresa en expansión piensa en capacidad y financiación; una con márgenes presionados, en costos y eficiencia; una con problemas de caja, en capital de trabajo. Si la conversación arranca desde su prioridad, el producto financiero aparece como parte de la solución, no como el tema central."},{"titulo":"Preguntas que abren","texto":"“¿Cuáles son sus tres prioridades este año?”, “¿qué le preocupa de los próximos 12 meses?”, “¿qué decisión importante tiene pendiente?”.\n\nEstas preguntas invitan al gerente a hablar de lo que le importa. Escucha el lenguaje exacto que usa: si dice “la energía nos está matando”, ese es el tema. Haz una pregunta de seguimiento antes de proponer nada: “¿Cuánto representa hoy dentro de sus costos?”. La profundidad de la conversación depende de tu disposición a escuchar sin saltar a la oferta."},{"titulo":"Aportar perspectiva","texto":"Un dato del sector, una comparación con pares o una idea que el cliente no había considerado.\n\nLa venta basada en perspectiva (insight selling) parte de que el cliente valora a quien le enseña algo sobre su propio negocio. Puede ser un dato (“las empresas de su sector que autogeneran energía han reducido ese costo de forma importante”), una comparación (“sus días de cartera están por encima del promedio del sector”) o una pregunta que reencuadra (“¿ha calculado cuánto le cuesta la volatilidad de la tarifa?”). Prepara una perspectiva antes de cada reunión."},{"titulo":"De conversación a relación","texto":"Cierra con un siguiente paso útil para el cliente y cumple lo que prometes.\n\nUna relación de largo plazo se construye con consistencia: enviar el dato que prometiste, presentar al experto que mencionaste, volver con una respuesta. Propón siempre un siguiente paso que tenga valor para el cliente: una introducción, un análisis, una visita técnica. Con el tiempo, el cliente te buscará antes de tomar decisiones, y ahí es donde están las mejores oportunidades."}],"ejercicio":"Transforma tu próxima visita comercial en una conversación estratégica.","pasos":["Elige un cliente que visitarás pronto.","Identifica cuál de los cinco temas de la agenda del gerente es más probable para él.","Prepara tres preguntas abiertas y una perspectiva (dato, comparación o reencuadre).","En la reunión, habla menos del 30% del tiempo y anota las frases textuales del cliente.","Cierra con un siguiente paso útil para él y cúmplelo en la fecha acordada."],"quiz":[{"pregunta":"¿Qué escasea para un gerente?","opciones":["Ofertas de productos","Interlocutores que entienden su negocio","Correos"],"correcta":1},{"pregunta":"¿Qué porcentaje aproximado de su proceso dedican los compradores B2B a reunirse con proveedores, según Gartner?","opciones":["Alrededor del 17%","Alrededor del 80%","100%"],"correcta":0},{"pregunta":"¿Qué es aportar perspectiva?","opciones":["Repetir el portafolio","Enseñar al cliente algo nuevo sobre su negocio","Hablar del clima"],"correcta":1},{"pregunta":"¿Qué construye una relación de largo plazo?","opciones":["Cumplir lo que prometes con consistencia","Llamar todos los días","Ofrecer descuentos"],"correcta":0}],"accion":"Pregunta a un cliente cuáles son sus tres prioridades este año y escucha antes de proponer."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('finanzas-corporativas-aplicadas-al-cliente-empresarial', 'Finanzas corporativas aplicadas al cliente empresarial', 101, true, 5, 'finanzas', 'curso',
          40, 'Intermedio', array['financiero']::text[], 'aliado', false, false, false, false,
          null, 'Lee estados financieros para anticipar necesidades, no solo riesgos.', 't-roi', 98, '2026-02-08')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Leer estado de resultados, balance y flujo de caja con ojos de asesor","Indicadores que anticipan necesidades de inversión","Capital de trabajo y ciclo de conversión de caja","Cómo llevar el análisis a una conversación de valor","Errores frecuentes de lectura"],"contexto":"Los estados financieros cuentan la historia de una empresa: cómo gana dinero, dónde lo invierte, cómo se financia y qué presiones enfrenta. La mayoría de ejecutivos los leen para medir riesgo; los mejores los leen para anticipar necesidades.\n\nEsta diferencia cambia la relación con el cliente. Un ejecutivo que llega diciendo “noté que sus costos operativos crecieron más que sus ventas en los últimos dos años; ¿qué está pasando?” deja de ser un vendedor de productos y se convierte en un interlocutor que entiende el negocio. Este curso te da un método para hacer esa lectura en menos de media hora.","lecciones":[{"titulo":"Estado de resultados","texto":"Ingresos, costo de ventas, gastos operativos, EBITDA y utilidad neta. Lee la tendencia de tres años, no un solo periodo.\n\nLa pregunta clave es qué crece más rápido: los ingresos o los costos. Si el margen bruto cae, puede haber presión en materias primas, energía o precios. Si el margen EBITDA cae mientras las ventas crecen, la empresa está creciendo con ineficiencia. Calcula los márgenes como porcentaje de ventas y compáralos año a año: los cambios de dos o más puntos merecen una pregunta."},{"titulo":"Balance general","texto":"Activos, pasivos y patrimonio. Activos fijos envejecidos o alta deuda de corto plazo son señales de necesidad.\n\nCompara el activo fijo bruto con la depreciación acumulada: si la depreciación es alta en proporción, los equipos están envejeciendo y pronto habrá que reemplazarlos. Revisa la estructura de la deuda: mucha deuda de corto plazo financiando activos de largo plazo sugiere una oportunidad de reestructuración. Un patrimonio creciente con poca deuda indica capacidad para nuevas inversiones."},{"titulo":"Capital de trabajo y ciclo de caja","texto":"Días de cartera + días de inventario − días de proveedores = días que la empresa financia su operación.\n\nEl ciclo de conversión de caja muestra cuánto tiempo pasa entre que la empresa paga a sus proveedores y cobra a sus clientes. Un ciclo que se alarga indica que la empresa necesita más capital de trabajo para crecer. Es una de las fuentes más claras de necesidades de financiación y una buena razón para conversar sobre productos de factoring, confirming o líneas rotativas."},{"titulo":"Indicadores que anticipan inversiones","texto":"Capacidad instalada al límite, costos operativos crecientes, activos envejecidos y flujo operativo sano.\n\nCuando una empresa tiene ventas crecientes, márgenes presionados por costos operativos y flujo de caja operativo positivo, suele estar lista para invertir en eficiencia. La energía es uno de esos costos operativos: si el rubro de servicios públicos crece más rápido que la producción, hay una conversación pendiente sobre autogeneración. El indicador de cobertura del servicio de la deuda (EBITDA ÷ servicio de deuda) muestra cuánto margen tiene para asumir nueva financiación."},{"titulo":"De los números a la conversación","texto":"Lleva una observación concreta y una pregunta abierta, no un diagnóstico cerrado.\n\nEl error más común es llegar con conclusiones. Es más efectivo plantear una observación y preguntar: “Vi que el margen bruto bajó tres puntos en dos años. ¿Qué lo explica?”. El cliente aporta el contexto que los estados financieros no muestran y, al hacerlo, revela sus prioridades. Lleva máximo tres observaciones a una reunión; más de eso se convierte en auditoría."}],"ejercicio":"Toma los estados financieros de un cliente y prepara tres observaciones con su pregunta para tu próxima reunión.","pasos":["Consigue estados financieros de tres años de un cliente empresarial.","Calcula margen bruto, margen EBITDA y ciclo de conversión de caja para cada año.","Identifica los tres cambios más relevantes.","Para cada cambio, escribe una observación y una pregunta abierta.","Identifica qué producto o solución podría conectarse con cada necesidad."],"quiz":[{"pregunta":"¿Qué revela un margen EBITDA que cae mientras las ventas crecen?","opciones":["Crecimiento con ineficiencia o presión de costos","Que la empresa no tiene deuda","Nada relevante"],"correcta":0},{"pregunta":"¿Cómo se calcula el ciclo de conversión de caja?","opciones":["Días de cartera + días de inventario − días de proveedores","Ventas ÷ activos","Utilidad ÷ patrimonio"],"correcta":0},{"pregunta":"¿Qué sugiere una depreciación acumulada alta frente al activo fijo?","opciones":["Equipos envejecidos que pronto deberán reemplazarse","Exceso de caja","Bajo endeudamiento"],"correcta":0},{"pregunta":"¿Cómo llevar el análisis a la reunión?","opciones":["Con conclusiones cerradas","Con observaciones y preguntas abiertas","Con todos los indicadores posibles"],"correcta":1}],"accion":"Lleva a tu próxima reunión tres observaciones financieras con su pregunta abierta."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-detectar-oportunidades-de-financiacion', 'Cómo detectar oportunidades de financiación', 102, true, 5, 'finanzas', 'micro',
          18, 'Intermedio', array['financiero']::text[], 'aliado', false, false, true, false,
          null, 'Señales en la operación del cliente que anticipan una inversión.', 't-diag', 156, '2026-03-15')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Señales operativas que anticipan una inversión","Dónde buscar esas señales","Cómo convertir una señal en una conversación","Cómo priorizar oportunidades en tu cartera"],"contexto":"Las mejores oportunidades de financiación aparecen antes de que el cliente pida un crédito. Cuando lo pide, ya está comparando ofertas. El ejecutivo que detecta las señales a tiempo llega primero, con una propuesta pensada para el problema real.\n\nEstas señales están en la operación del cliente, en sus estados financieros, en las noticias de su sector y en lo que dice en cada conversación. Aprender a leerlas convierte la cartera existente en la principal fuente de nuevo negocio.","lecciones":[{"titulo":"Señales operativas","texto":"Capacidad al límite, nuevos contratos, equipos antiguos, expansión de sede o cambios en la cadena de suministro.\n\nUna planta que trabaja turnos adicionales está cerca de su capacidad máxima. Un cliente que ganó un contrato grande necesitará capital de trabajo y, quizás, maquinaria. Equipos con más de diez años suelen ser menos eficientes y más costosos de mantener. Una empresa que compra el lote vecino está pensando en crecer. Cada una de estas señales anticipa una necesidad de financiación."},{"titulo":"Dónde buscarlas","texto":"En las visitas, en los estados financieros, en las noticias del sector y en las redes del cliente.\n\nLas visitas a planta revelan más que cualquier informe: inventarios acumulados, equipos antiguos, espacios subutilizados. Los estados financieros muestran tendencias de costos y activos. Las noticias del sector anticipan cambios regulatorios o de demanda. LinkedIn y las redes del cliente comunican contrataciones, premios y nuevos proyectos. Revisa estas fuentes de forma sistemática para tus 20 clientes principales."},{"titulo":"De la señal a la conversación","texto":"Comparte lo que observaste y pregunta por sus planes: “Vi que están contratando operarios; ¿están ampliando producción?”.\n\nLa señal es una hipótesis, no una certeza. Plantéala como observación y deja que el cliente la confirme o la corrija. Si la confirma, profundiza: “¿Cómo planean financiar esa expansión?”, “¿qué les preocupa del proceso?”. Una conversación así posiciona al banco como socio de la decisión, no como proveedor de la última etapa."},{"titulo":"Priorizar la cartera","texto":"Ordena tus clientes por tamaño de la oportunidad, urgencia de la señal y calidad de la relación.\n\nNo todas las señales tienen la misma urgencia: un contrato ya firmado exige recursos en semanas; una intención de expansión puede tardar un año. Combina urgencia con tamaño y con qué tan fácil es para ti tener la conversación. Trabaja primero las oportunidades urgentes con buena relación y programa seguimiento para las demás."}],"ejercicio":"Revisa tus 10 principales clientes y anota una señal de inversión para cada uno.","pasos":["Lista tus 10 principales clientes empresariales.","Para cada uno, revisa noticias recientes, LinkedIn y su último estado financiero.","Anota la señal más relevante que encuentres (o “sin señal”).","Califica cada señal por urgencia (alta, media, baja).","Prepara la pregunta de apertura para los dos clientes con mayor urgencia."],"quiz":[{"pregunta":"¿Cuándo aparecen las mejores oportunidades de financiación?","opciones":["Cuando el cliente pide crédito","Antes de que el cliente pida, en sus señales operativas","Al final del año"],"correcta":1},{"pregunta":"¿Qué indica una planta trabajando turnos adicionales?","opciones":["Capacidad cerca del límite","Baja demanda","Exceso de personal"],"correcta":0},{"pregunta":"¿Cómo plantear una señal al cliente?","opciones":["Como certeza","Como observación con una pregunta","No mencionarla"],"correcta":1},{"pregunta":"¿Con qué criterios se prioriza la cartera?","opciones":["Tamaño, urgencia y calidad de la relación","Orden alfabético","Antigüedad"],"correcta":0}],"accion":"Plantea una señal de inversión a uno de tus clientes esta semana con una pregunta abierta."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-convertir-datos-en-conversaciones-ejecutivas', 'Cómo convertir datos en conversaciones ejecutivas', 103, true, 5, 'negocios', 'micro',
          15, 'Intermedio', array['financiero']::text[], 'aliado', false, false, false, false,
          null, 'Tres cifras bien elegidas valen más que un informe de 20 páginas.', 't-reunion', 94, '2026-04-22')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Elegir las tres cifras que importan","Convertir datos en mensajes, no en informes","Visualizar para decidir","Llevar los datos a una conversación con un gerente"],"contexto":"Los gerentes no tienen tiempo para leer informes de 20 páginas, pero sí para escuchar tres cifras bien elegidas que cambien su forma de ver un problema. La habilidad de seleccionar, sintetizar y comunicar datos es una de las más valoradas en cualquier conversación ejecutiva.\n\nLa investigación sobre toma de decisiones muestra que el exceso de información no mejora las decisiones: las retrasa. Un ejecutivo, consultor o aliado que llega con una síntesis clara —qué pasa, por qué importa y qué hacer— se vuelve el interlocutor preferido del gerente.","lecciones":[{"titulo":"Elige tres cifras","texto":"La que muestra el problema, la que lo dimensiona y la que muestra la oportunidad.\n\nPara una conversación sobre energía: “Su factura creció 28% en 18 meses” (problema), “hoy representa el 9% de sus costos operativos” (dimensión) y “con autogeneración podría cubrir cerca del 40% de ese consumo con una inversión que se paga en cinco años” (oportunidad). Tres cifras, una historia completa. Todo lo demás va en anexos."},{"titulo":"Datos en mensajes","texto":"Cada cifra debe llevar una interpretación: “esto significa que…”.\n\nUn dato sin interpretación obliga al gerente a hacer el trabajo de análisis. “El costo unitario pasó de $680 a $870” es un dato; “cada kWh le cuesta hoy 28% más que hace año y medio, sin que haya consumido más” es un mensaje. Practica escribir cada cifra con su “esto significa que” antes de cualquier reunión."},{"titulo":"Visualizar para decidir","texto":"Un gráfico por idea, con un titular que diga la conclusión.\n\nEl titular del gráfico debe ser la conclusión, no la descripción: “La energía creció más rápido que las ventas” en lugar de “Evolución de costos 2023–2025”. Usa barras para comparar, líneas para tendencias y evita gráficos de torta con muchas categorías. Elimina todo lo que no ayude a entender el mensaje."},{"titulo":"Llévalo a la conversación","texto":"Abre con la cifra más relevante, pregunta y deja que el gerente complete la historia.\n\n“Revisando su sector, vi que el costo de energía creció más rápido que las ventas. ¿Es algo que están viendo en su empresa?”. La cifra abre la conversación; la pregunta la vuelve suya. Si el gerente confirma, profundiza con las otras dos cifras. Si no, escucha: quizá su problema principal es otro."}],"ejercicio":"Prepara tres cifras con su interpretación para una conversación con un gerente.","pasos":["Elige un cliente o empresa con quien conversarás pronto.","Identifica la cifra del problema, la de la dimensión y la de la oportunidad.","Escribe cada cifra con su “esto significa que”.","Diseña un gráfico simple con un titular que diga la conclusión.","Escribe la pregunta con la que abrirás la conversación."],"quiz":[{"pregunta":"¿Cuántas cifras conviene llevar a una conversación ejecutiva?","opciones":["Veinte","Tres bien elegidas","Ninguna"],"correcta":1},{"pregunta":"¿Qué convierte un dato en mensaje?","opciones":["Su interpretación: “esto significa que…”","Ponerlo en color","Repetirlo"],"correcta":0},{"pregunta":"¿Qué debe decir el titular de un gráfico?","opciones":["La conclusión","Solo las fechas","El nombre del archivo"],"correcta":0},{"pregunta":"¿Cómo abrir la conversación?","opciones":["Con una cifra relevante y una pregunta","Con un informe de 20 páginas","Con el portafolio"],"correcta":0}],"accion":"Lleva a tu próxima reunión tres cifras con su interpretación y una pregunta de apertura."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-para-ejecutivos-financieros', 'IA para ejecutivos financieros', 104, true, 5, 'ia', 'curso',
          35, 'Principiante', array['financiero']::text[], 'aliado', false, true, false, false,
          null, 'Casos de uso reales para análisis, preparación y seguimiento.', 't-prompts', 92, '2026-05-02')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Casos de uso de IA en banca empresarial","Preparar visitas y comités con IA","Analizar estados financieros y sectores","Redactar propuestas y seguimientos","Reglas de privacidad en el sector financiero"],"contexto":"El trabajo de un ejecutivo de banca empresarial combina análisis, preparación, relación y seguimiento. La IA puede acelerar los tres primeros y hacer más consistente el cuarto, liberando tiempo para lo que ninguna herramienta reemplaza: la conversación con el cliente.\n\nLas entidades financieras están entre las organizaciones que más rápido adoptan la IA, tanto en procesos internos como en herramientas para sus equipos comerciales. Pero también son de las más reguladas: la Superintendencia Financiera, la Ley 1581 de protección de datos y las políticas internas de cada entidad definen qué información puede usarse y dónde. Este curso combina casos de uso concretos con esas reglas.","lecciones":[{"titulo":"Preparar una visita","texto":"Investigación del cliente, del sector y de las preguntas clave en 15 minutos.\n\nCon información pública, pide a la IA un perfil de la empresa (modelo de negocio, clientes, noticias recientes), las tendencias de su sector en Colombia y tres hipótesis de necesidad financiera. Luego pide cinco preguntas de diagnóstico que no suenen a venta. Verifica las cifras y noticias antes de usarlas. Con la preparación hecha, tu visita empieza en el negocio del cliente, no en tu portafolio."},{"titulo":"Analizar estados financieros","texto":"Pide cálculo de indicadores, tendencias y preguntas, siempre con datos anonimizados o en herramientas autorizadas.\n\nSi tu entidad dispone de una herramienta corporativa, puedes subir estados financieros y pedir: “Calcula márgenes, ciclo de conversión de caja, endeudamiento y cobertura de deuda para los tres años. Señala los tres cambios más relevantes y formula una pregunta para cada uno”. Si no está autorizada, reemplaza nombres y NIT, o trabaja solo con los indicadores ya calculados."},{"titulo":"Análisis sectorial","texto":"Resume informes del DANE, gremios y Superintendencia de Sociedades en implicaciones para tu cartera.\n\nLos informes sectoriales son extensos y pocas veces se leen completos. Sube el documento y pide: “Resume las cinco tendencias principales de este informe, las cifras clave con su página y qué implicaciones tienen para empresas medianas de [sector] en [región] que buscan financiación”. Usa el resultado para preparar tu planeación comercial trimestral."},{"titulo":"Propuestas y seguimientos","texto":"Primeros borradores de propuestas, correos y resúmenes para comité.\n\nLa IA puede redactar el resumen ejecutivo de una propuesta, el correo que acompaña una oferta o la nota para un comité de crédito a partir de tus notas. Dale estructura: “Resumen de cinco líneas: necesidad del cliente, solución propuesta, monto y plazo, mitigantes de riesgo y siguiente paso”. Revisa cada cifra: en este contexto, un error tiene consecuencias."},{"titulo":"Reglas del sector","texto":"Usa solo herramientas autorizadas, nunca pegues información de clientes en versiones públicas y documenta lo que usas.\n\nTres reglas básicas: 1) La información de clientes solo se procesa en herramientas aprobadas por tu entidad. 2) Las decisiones de crédito no se delegan a una IA genérica. 3) Toda cifra que llegue a un cliente o a un comité se verifica en la fuente. Si tu entidad no tiene política definida, pregunta a cumplimiento antes de empezar."}],"ejercicio":"Prepara con IA tu próxima visita empresarial respetando las reglas de privacidad de tu entidad.","pasos":["Confirma qué herramientas de IA están autorizadas en tu entidad.","Elige un cliente que visitarás pronto y reúne información pública.","Pide a la IA perfil, tendencias del sector, hipótesis y preguntas.","Verifica las cifras y noticias en fuentes originales.","Usa la preparación en la visita y anota qué cambió en la conversación."],"quiz":[{"pregunta":"¿Qué información puede procesarse en herramientas de IA públicas?","opciones":["Estados financieros con NIT","Solo información pública o anonimizada","Cualquier dato del cliente"],"correcta":1},{"pregunta":"¿Qué no debe delegarse a una IA genérica?","opciones":["Redactar un primer borrador","Decisiones de crédito","Resumir un informe público"],"correcta":1},{"pregunta":"¿Para qué sirve la IA en análisis sectorial?","opciones":["Para resumir informes extensos en implicaciones para la cartera","Para inventar tendencias","No sirve"],"correcta":0},{"pregunta":"¿A quién preguntar si la entidad no tiene política de IA?","opciones":["Al cliente","Al área de cumplimiento","A nadie"],"correcta":1}],"accion":"Prepara con IA tu próxima visita y verifica cada dato antes de usarlo."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-preparar-una-reunion-empresarial-con-ia', 'Cómo preparar una reunión empresarial con IA', 105, true, 5, 'ia', 'micro',
          14, 'Principiante', array['financiero', 'referidor']::text[], 'aliado', false, false, true, false,
          null, 'Investiga la empresa, arma hipótesis y prepara preguntas en 15 minutos.', 't-reunion', 150, '2026-06-09')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Investigar una empresa en minutos con IA","Formular hipótesis de necesidad","Preparar preguntas y agenda","Verificar la información antes de usarla"],"contexto":"Quince minutos de preparación cambian el resultado de una reunión de una hora. El problema es que esos quince minutos casi nunca existen en una agenda llena. La IA permite condensar la investigación y la preparación en ese tiempo, siempre que sepas qué pedir y qué verificar.\n\nUna reunión bien preparada se nota desde el primer minuto: el cliente percibe que conoces su negocio, las preguntas son relevantes y la conversación avanza hacia un siguiente paso concreto. Este es el método que puedes repetir antes de cada reunión importante.","lecciones":[{"titulo":"Investigar la empresa","texto":"Sitio web, noticias, LinkedIn y sector, resumidos en una tabla.\n\nInstrucción base: “Actúa como analista de negocios. Voy a reunirme con [cargo] de [empresa], del sector [sector] en [ciudad]. Con base en información pública, resume en una tabla: qué vende y a quién, tamaño aproximado, noticias de los últimos 12 meses, retos probables del sector y quién es la persona con quien me reuniré. Marca lo que sea suposición.” Si la herramienta tiene búsqueda web, pide las fuentes."},{"titulo":"Formular hipótesis","texto":"Dos o tres hipótesis sobre problemas u oportunidades que probablemente tiene la empresa.\n\n“Con esta información, formula tres hipótesis sobre retos que probablemente enfrenta la empresa en costos, crecimiento o financiación. Para cada una, dame una pregunta que me permita validarla sin sonar a venta.” Las hipótesis te dan dirección; las preguntas te permiten confirmarlas o descartarlas con el cliente."},{"titulo":"Preparar la agenda","texto":"Apertura, diagnóstico, perspectiva y cierre en 30 minutos.\n\nPide una agenda con tiempos y una propuesta de siguiente paso. Una estructura que funciona: 3 minutos de apertura y acuerdo de agenda, 15 de diagnóstico con preguntas, 7 de perspectiva (un dato, un caso o una idea relevante) y 5 de cierre con siguiente paso. Comparte la agenda con el cliente antes de la reunión si es formal."},{"titulo":"Verificar","texto":"Contrasta cifras, nombres y noticias antes de usarlos; una suposición presentada como hecho daña la credibilidad.\n\nLa IA puede confundir empresas con nombres similares, atribuir noticias antiguas como recientes o inventar cifras de ventas. Antes de la reunión, revisa en el sitio de la empresa, en su perfil de LinkedIn o en fuentes como la Superintendencia de Sociedades o el RUES los datos que piensas mencionar. Si algo no se puede verificar, conviértelo en pregunta."}],"ejercicio":"Prepara con este método tu próxima reunión empresarial en 15 minutos.","pasos":["Elige una reunión de los próximos días.","Usa la instrucción base para investigar la empresa.","Pide tres hipótesis y una pregunta para cada una.","Pide una agenda de 30 minutos con siguiente paso.","Verifica los datos que mencionarás y usa la preparación en la reunión."],"quiz":[{"pregunta":"¿Qué debe pedir la instrucción de investigación?","opciones":["Que marque lo que es suposición","Que invente datos faltantes","Solo el logo"],"correcta":0},{"pregunta":"¿Para qué sirven las hipótesis?","opciones":["Para dar dirección a la conversación y validarlas con preguntas","Para presentarlas como hechos","No sirven"],"correcta":0},{"pregunta":"¿Qué hacer con un dato que no se puede verificar?","opciones":["Mencionarlo igual","Convertirlo en pregunta","Inventar la fuente"],"correcta":1},{"pregunta":"¿Con qué debe terminar la agenda?","opciones":["Con un siguiente paso","Con un chiste","Sin cierre"],"correcta":0}],"accion":"Prepara con IA tu próxima reunión y termina con un siguiente paso acordado."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('sostenibilidad-en-lenguaje-financiero', 'Sostenibilidad en lenguaje financiero', 106, true, 5, 'energia', 'micro',
          16, 'Intermedio', array['financiero']::text[], 'aliado', false, false, false, false,
          null, 'ESG, bonos verdes y líneas sostenibles explicados con números.', 't-roi', 88, '2026-07-16')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué significa ESG para un cliente empresarial y para su banco","Taxonomía Verde de Colombia y Protocolo Verde","Bonos, créditos y líneas sostenibles explicados con números","Cómo convertir una meta de sostenibilidad en un caso de inversión"],"contexto":"Para muchos gerentes, “sostenibilidad” suena a costo o a reputación. Para un banco, es cada vez más una variable de riesgo, de acceso a recursos y de rentabilidad. El ejecutivo que traduce la sostenibilidad a flujo de caja, riesgo y retorno se vuelve un interlocutor estratégico.\n\nColombia ha avanzado rápido en este frente: en 2012 el sector financiero firmó el Protocolo Verde con el Gobierno; en 2016 se emitió el primer bono verde del país en el mercado local; y en 2022 el país lanzó la Taxonomía Verde, la primera de América Latina, que define qué actividades pueden considerarse ambientalmente sostenibles. Además, las grandes empresas que venden a cadenas multinacionales o exportan reciben cada vez más exigencias de reporte de emisiones de sus clientes. Todo esto crea conversaciones de negocio donde antes solo había discursos.","lecciones":[{"titulo":"ESG sin jerga","texto":"Ambiental, social y gobierno corporativo: tres grupos de riesgos y oportunidades que afectan el valor de una empresa.\n\nPara un ejecutivo financiero, ESG no es un tema de imagen: es información sobre riesgos que pueden afectar la capacidad de pago y el valor de un cliente. Una empresa con alta exposición a costos de energía volátiles, a regulación ambiental o a exigencias de sus compradores tiene un riesgo que puede gestionarse. Una inversión en eficiencia o en autogeneración reduce costos, mejora la previsibilidad del flujo y responde a esas exigencias al mismo tiempo."},{"titulo":"Taxonomía Verde y Protocolo Verde","texto":"Reglas de juego compartidas para clasificar qué es verde y para que la banca integre criterios ambientales.\n\nLa Taxonomía Verde de Colombia clasifica actividades como la generación solar fotovoltaica como sostenibles bajo ciertos criterios. Esto facilita que bancos y emisores identifiquen y reporten su cartera verde, y que los proyectos accedan a recursos etiquetados. El Protocolo Verde, liderado por Asobancaria, compromete a las entidades a desarrollar productos que financien proyectos con beneficios ambientales y a gestionar los riesgos ambientales de su cartera."},{"titulo":"Instrumentos sostenibles con números","texto":"Créditos verdes, bonos verdes, líneas de redescuento y créditos vinculados a metas de sostenibilidad.\n\nUn crédito verde financia un activo con beneficio ambiental (como un sistema solar). Un bono verde permite a una entidad captar recursos en el mercado de capitales para financiar ese tipo de activos. Las líneas de redescuento de entidades como Bancóldex o Findeter canalizan recursos para proyectos específicos. Los créditos vinculados a sostenibilidad ajustan condiciones según el cumplimiento de metas. En todos los casos, las condiciones las define cada entidad."},{"titulo":"Emisiones en pesos","texto":"Un sistema solar evita emisiones y costos al mismo tiempo; ambos pueden cuantificarse.\n\nCada kWh generado con sol reemplaza energía de la red, cuyo factor de emisión publica la UPME (del orden de 0,1 a 0,2 kg de CO₂ por kWh en años recientes, variable según la hidrología). Un sistema de 100 kWp que produce cerca de 145.000 kWh al año evita, en ese rango, entre 15 y 30 toneladas de CO₂ anuales. Para una empresa que reporta a sus clientes, esa cifra tiene valor comercial; para su banco, es un dato de impacto de cartera."},{"titulo":"Del discurso al caso de inversión","texto":"Conecta la meta de sostenibilidad del cliente con ahorro, payback y financiación.\n\nLa pregunta clave es: “¿Qué metas de sostenibilidad o de reporte tienen este año y cómo planean cumplirlas?”. Si la empresa tiene una meta y además paga una factura alta, la autogeneración solar responde a ambas cosas. Presentarla como una inversión con retorno —no como un gasto ambiental— es lo que la lleva al comité de inversiones y no solo al área de comunicaciones."}],"ejercicio":"Traduce la meta de sostenibilidad de un cliente a un caso de inversión de una página.","pasos":["Identifica un cliente con metas de sostenibilidad o exigencias de reporte de sus compradores.","Anota su factura mensual de energía aproximada.","Estima un sistema que cubra el 40% de su consumo y calcula el ahorro anual.","Calcula las toneladas de CO₂ evitadas con un factor de 0,15 kg/kWh.","Escribe una página con: meta del cliente, solución, ahorro, emisiones evitadas y opción de financiación."],"quiz":[{"pregunta":"Para un banco, ESG es principalmente…","opciones":["Un tema de imagen","Información sobre riesgos y oportunidades que afectan el valor","Un requisito legal único"],"correcta":1},{"pregunta":"¿Qué hizo Colombia en 2022?","opciones":["Lanzó la Taxonomía Verde","Prohibió la energía térmica","Eliminó la contribución"],"correcta":0},{"pregunta":"¿Cómo se calculan las emisiones evitadas por un sistema solar?","opciones":["kWh generados × factor de emisión de la red","kWp × 1.000","No se pueden calcular"],"correcta":0},{"pregunta":"¿Cómo conviene presentar una inversión solar al comité?","opciones":["Como gasto ambiental","Como inversión con retorno que además cumple metas","Como donación"],"correcta":1}],"accion":"Pregunta a un cliente qué metas de sostenibilidad tiene este año y conéctalas con su factura de energía."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-analizar-una-inversion-solar', 'Cómo analizar una inversión solar', 107, true, 5, 'finanzas', 'curso',
          38, 'Intermedio', array['financiero']::text[], 'aliado', false, false, false, false,
          null, 'CAPEX, ahorro, payback y TIR de un proyecto real.', 't-roi', 86, '2026-08-23')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Estructurar el análisis completo de un proyecto solar","Pasar de factura a dimensionamiento y ahorro","Calcular payback, VPN y TIR con incentivos","Evaluar la financiación y el riesgo","Presentar la conclusión a un comité"],"contexto":"Un proyecto solar empresarial es, ante todo, una decisión de inversión. Analizarlo bien exige el mismo rigor que cualquier otro proyecto de capital: inversión, flujos, horizonte, costo de capital, riesgos y alternativas de financiación.\n\nEste curso recorre el análisis completo con un caso de referencia: una empresa de alimentos en Bucaramanga con una factura de $45 millones mensuales, operación de 6 a. m. a 8 p. m. y 3.500 m² de cubierta metálica propia. Al terminar, podrás revisar una propuesta técnica y financiera con criterio, hacer las preguntas correctas y explicar la decisión a un comité. Las cifras son ilustrativas; las de cada proyecto las define el diseño técnico.","lecciones":[{"titulo":"Del consumo al tamaño del sistema","texto":"Factura → kWh mensuales → porcentaje a cubrir → kWp necesarios → área requerida.\n\nCon un costo unitario de $820/kWh, la factura de $45 millones equivale a unos 55.000 kWh al mes. Si el 70% del consumo ocurre en horas de sol y se busca cubrir buena parte de esa franja sin generar excedentes grandes, un objetivo razonable es 25.000 kWh mensuales. Con 125 kWh por kWp al mes en Bucaramanga, el sistema sería de unos 200 kWp, que ocupan cerca de 1.200 m²: la cubierta alcanza con holgura."},{"titulo":"Inversión y ahorro","texto":"CAPEX de referencia, ahorro del primer año y su evolución.\n\nCon un costo de referencia de $3,2 millones por kWp, el CAPEX rondaría $640 millones. El sistema produciría unos 300.000 kWh al año; si se autoconsume casi todo, el ahorro del primer año sería cercano a $246 millones. Con costos de operación de 1,5% del CAPEX ($9,6 millones), el flujo neto del primer año sería de unos $236 millones."},{"titulo":"Indicadores","texto":"Payback, VPN y TIR, con y sin los incentivos de la Ley 1715.\n\nSin incentivos, el payback simple sería de unos 2,7 años. Con un incremento de tarifa del 4% anual, degradación de 0,5% y reemplazo de inversores en el año 12, la TIR del proyecto superaría ampliamente el costo de capital de una empresa típica. La deducción en renta del 50% (hasta $320 millones deducibles, equivalentes a cerca de $112 millones menos de impuesto con tarifa del 35%) mejora aún más los indicadores. Este caso tiene condiciones muy favorables; en proyectos con tarifas menores o menos autoconsumo, el payback suele estar entre 4 y 7 años."},{"titulo":"Financiación y riesgo","texto":"Compara compra con recursos propios, crédito y PPA, y prueba un escenario pesimista.\n\nCon un crédito a 7 años que financie el 80%, la cuota anual estaría muy por debajo del ahorro, de modo que el proyecto generaría caja positiva desde el inicio. Un escenario pesimista —producción 15% menor, tarifa sin crecimiento y CAPEX 10% mayor— alarga el payback, pero mantiene un retorno superior al costo de capital. Esta prueba es la que da tranquilidad al comité."},{"titulo":"Presentar la decisión","texto":"Una página: la decisión, los tres números, el riesgo y el costo de no hacer nada.\n\nLa recomendación se resume así: “Proponemos un sistema de 200 kWp con una inversión de referencia de $640 millones. Recupera la inversión en menos de tres años, con más de veinte años de ahorro posterior, y puede financiarse con una cuota menor al ahorro. Aun en un escenario conservador, el retorno supera el costo de capital. No hacerlo significa seguir expuestos a la volatilidad de la tarifa sobre el 45% del consumo”."}],"ejercicio":"Analiza un proyecto solar completo con los datos de un cliente real o del caso de referencia.","pasos":["Toma la factura de un cliente (o usa el caso de referencia del curso).","Calcula kWh mensuales, porcentaje a cubrir y kWp necesarios.","Estima CAPEX, ahorro del primer año y flujo neto.","Calcula payback simple y con incentivos, y prueba un escenario pesimista.","Escribe la recomendación en una página con el formato decisión, números, riesgo y costo de no hacer nada."],"quiz":[{"pregunta":"¿Cuál es el primer paso del análisis?","opciones":["Calcular la TIR","Pasar de la factura a kWh y al tamaño del sistema","Elegir el banco"],"correcta":1},{"pregunta":"¿Qué se suma al ahorro en el análisis con incentivos?","opciones":["El beneficio tributario de la deducción en renta","El valor de la cubierta","Nada"],"correcta":0},{"pregunta":"¿Qué prueba da tranquilidad al comité?","opciones":["Solo el escenario optimista","Un escenario pesimista que sigue superando el costo de capital","Un video del sistema"],"correcta":1},{"pregunta":"¿Qué debe incluir la página de recomendación?","opciones":["Decisión, tres números, riesgo y costo de no hacer nada","Todas las fórmulas","Solo el CAPEX"],"correcta":0}],"accion":"Revisa con este método la propuesta solar de uno de tus clientes y comparte tus preguntas con la consultora."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('energia-como-conversacion-de-banca-empresarial', 'Energía como conversación de banca empresarial', 108, true, 5, 'energia', 'micro',
          12, 'Principiante', array['financiero']::text[], 'aliado', false, false, false, false,
          null, 'La factura de energía como puerta de entrada a una relación de largo plazo.', 't-solar', 84, '2026-09-03')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Por qué la energía es una puerta de entrada a la relación","Cómo abrir la conversación desde la factura","Qué productos financieros se conectan con un proyecto solar","Cómo involucrar a GEENERA sin perder el control de la relación"],"contexto":"La factura de energía es uno de los pocos costos que todo gerente conoce de memoria y que casi nadie siente que controla. Para un ejecutivo de banca empresarial, eso la convierte en una excelente puerta de entrada a conversaciones que van más allá del crédito de capital de trabajo.\n\nUna conversación sobre energía toca los temas que más importan al gerente: márgenes, competitividad, previsibilidad del flujo y metas de sostenibilidad. Y abre una oportunidad de financiación de largo plazo, con un activo productivo que genera su propio repago. El ejecutivo que la inicia no necesita ser experto en energía: necesita saber hacer las preguntas correctas y conectar al cliente con un aliado técnico confiable.","lecciones":[{"titulo":"Por qué la energía abre puertas","texto":"Es un costo grande, visible y volátil que afecta directamente el margen del cliente.\n\nEntre 2021 y 2024, muchas empresas colombianas vieron incrementos de dos dígitos en el costo por kWh. Para una empresa manufacturera o de cadena de frío, la energía puede estar entre sus tres principales costos operativos. Hablar de eso muestra que entiendes su negocio, no solo su calificación crediticia."},{"titulo":"La pregunta de apertura","texto":"“¿Cómo se ha comportado su costo de energía en el último año?” abre la conversación sin vender nada.\n\nEsta pregunta funciona porque casi siempre genera una respuesta con emoción: sorpresa, frustración o resignación. A partir de ahí puedes profundizar: “¿Cuánto representa dentro de sus costos?”, “¿han evaluado alternativas?”. Si el cliente muestra interés, la siguiente pregunta es si le gustaría que un especialista revise su factura sin compromiso."},{"titulo":"Productos que se conectan","texto":"Crédito verde, leasing, líneas de redescuento y, a veces, cobertura de flujo y cuentas de recaudo.\n\nUn proyecto solar es un activo productivo de largo plazo cuyo ahorro puede cubrir la cuota. Eso lo hace atractivo para productos como el crédito de inversión o el leasing, y abre conversaciones complementarias: manejo de la caja liberada, seguros del activo y, en grupos empresariales, proyectos en otras sedes. El proyecto energético fortalece la relación integral con el cliente."},{"titulo":"Cómo trabajar con GEENERA","texto":"Tú mantienes la relación financiera; GEENERA aporta el diagnóstico técnico, la propuesta y la ejecución.\n\nAl referir a través del Hub, la oportunidad queda asociada a tu código y puedes seguir cada etapa. El equipo de GEENERA contacta al cliente, hace el análisis energético y presenta la propuesta técnica y financiera. Tú puedes participar en las reuniones clave, especialmente cuando se discute la financiación. Esta división de roles protege tu relación y da al cliente un interlocutor técnico especializado."}],"ejercicio":"Identifica tres clientes de tu cartera para iniciar una conversación sobre energía y prepara la pregunta de apertura para cada uno.","pasos":["Revisa tu cartera y elige tres clientes de sectores intensivos en energía.","Para cada uno, anota qué sabes de su operación (horario, sede, planes de inversión).","Escribe una pregunta de apertura adaptada a cada cliente.","Define qué producto financiero podría conectarse con un proyecto solar en cada caso.","Agenda la primera conversación con el cliente más prometedor."],"quiz":[{"pregunta":"¿Por qué la energía es una buena puerta de entrada?","opciones":["Porque es un costo grande, visible y volátil","Porque todos los clientes son expertos","Porque no afecta el margen"],"correcta":0},{"pregunta":"¿Cuál es una buena pregunta de apertura?","opciones":["¿Quiere un crédito?","¿Cómo se ha comportado su costo de energía en el último año?","¿Conoce los paneles solares?"],"correcta":1},{"pregunta":"¿Qué rol asume GEENERA tras el referido?","opciones":["Reemplaza al banco","Hace el diagnóstico técnico, la propuesta y la ejecución","Ninguno"],"correcta":1},{"pregunta":"Un proyecto solar es atractivo para financiar porque…","opciones":["Su ahorro puede cubrir la cuota","No tiene valor","Es de corto plazo"],"correcta":0}],"accion":"Haz la pregunta de apertura sobre energía a un cliente esta semana."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('radar-de-oportunidades', 'Radar de oportunidades', 109, true, 5, 'ads', 'flash',
          6, 'Principiante', array['financiero']::text[], 'aliado', false, false, false, false,
          null, 'Qué mirar en tu cartera para encontrar la próxima oportunidad.', 't-solar', 82, '2026-01-10')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Leer tu cartera con ojos de energía","Priorizar clientes por consumo y momento","Abrir la conversación sin desviar la relación financiera"],"contexto":"Tu cartera ya contiene las mejores oportunidades solares: empresas con consumo alto, sede propia y planes de inversión. El radar te ayuda a encontrarlas en minutos, con datos que ya tienes.\n\nLa investigación sobre ventas B2B coincide en algo: las oportunidades con mayor probabilidad de cierre aparecen donde ya existe confianza. Un ejecutivo financiero conoce la facturación, el sector, la estructura de propiedad y los planes de inversión de sus clientes; esa información, leída con criterio energético, permite anticipar quién necesita reducir costos operativos antes de que el cliente lo pida. El objetivo del radar no es convertirte en asesor de energía, sino en el primero que le muestra al cliente una palanca de ahorro que no estaba mirando.","lecciones":[{"titulo":"Tres filtros rápidos","texto":"Sector intensivo en energía (manufactura, alimentos, frío, hoteles, clínicas), sede propia y facturación estable. Con esos tres filtros reduces tu cartera a una lista corta.\n\nEn Colombia, los sectores donde la energía pesa más dentro de la estructura de costos son la manufactura con procesos térmicos o de motores, la cadena de frío, el procesamiento de alimentos, el comercio con refrigeración y climatización, y los servicios con operación continua como clínicas y hoteles. Para la mayoría de PyMEs comerciales e industriales, la energía representa entre el 3% y el 15% de los costos operativos; en sectores intensivos puede superar ese rango. La sede propia es determinante porque la inversión se instala sobre la cubierta y se recupera en varios años: un arrendatario sin contrato de largo plazo rara vez decide."},{"titulo":"Señales de momento","texto":"Ampliaciones de planta, renovación de equipos, metas ESG o quejas por costo de energía. El momento importa tanto como el perfil.\n\nLos momentos de cambio concentran decisiones. Una empresa que amplía planta está revisando su conexión eléctrica y su presupuesto de inversión; una que renueva equipos está evaluando eficiencia; una que reporta a clientes multinacionales o exporta suele tener metas de emisiones exigidas por su cadena de valor. Las noticias de la empresa, las solicitudes de crédito para CAPEX y los comentarios del gerente sobre la factura son las fuentes más confiables de estas señales."},{"titulo":"Cómo priorizar","texto":"Ordena por consumo estimado y cercanía de la relación. Empieza por quien te contesta el teléfono, no por el más grande.\n\nLa priorización combina dos ejes: tamaño de la oportunidad y facilidad de acceso. Un cliente mediano que confía en ti y responde en el día suele avanzar más rápido que un gran grupo empresarial con varios niveles de aprobación. Empieza con tres a cinco cuentas, aprende de esas conversaciones y luego escala. Registra cada contacto: con el tiempo, tu radar se convierte en una base propia de inteligencia comercial."}],"ejercicio":"Aplica los tres filtros a tu cartera y escribe los cinco clientes con más señales.","pasos":["Exporta o lista tu cartera de clientes empresariales con sector, ciudad y si la sede es propia.","Marca los que pertenecen a sectores intensivos en energía y tienen sede propia.","Para cada uno, anota una señal de momento (expansión, nuevos equipos, metas ESG, queja por costos).","Ordena por consumo estimado y cercanía de la relación, y elige los cinco primeros.","Prepara una pregunta de apertura distinta para cada uno, usando la Guía de Preguntas de Diagnóstico."],"quiz":[{"pregunta":"¿Qué filtro reduce más rápido una cartera?","opciones":["Antigüedad del cliente","Sector intensivo en energía","Ciudad"],"correcta":1},{"pregunta":"¿Por quién conviene empezar?","opciones":["El cliente más grande","El que tiene mejor relación contigo","El más nuevo"],"correcta":1},{"pregunta":"¿Qué combinación hace más probable un proyecto solar?","opciones":["Sector intensivo + sede propia + señal de momento","Empresa nueva + sede arrendada","Cualquier cliente con buena calificación crediticia"],"correcta":0}],"accion":"Contacta esta semana a los dos primeros clientes de tu radar."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('convierte-tu-red-en-oportunidades', 'Convierte tu red en oportunidades', 110, true, 5, 'relaciones', 'micro',
          18, 'Principiante', array['referidor']::text[], 'free', true, false, true, false,
          null, 'Mapea tu red y descubre dónde hay conversaciones pendientes.', 't-red', 140, '2026-02-17')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Mapear tu red con un método","Por qué los lazos débiles traen más oportunidades","Clasificar contactos por confianza, acceso y potencial","Activar conversaciones sin sonar a venta"],"contexto":"La mayoría de las oportunidades no están en contactos nuevos, sino en relaciones existentes que no has activado. Tu red —clientes, excolegas, compañeros de estudio, contactos gremiales, vecinos— ya contiene empresas que podrían beneficiarse de un proyecto solar o personas que las conocen.\n\nEn 1973, el sociólogo Mark Granovetter publicó un estudio clásico sobre “la fuerza de los lazos débiles”: encontró que las personas conseguían empleo más a menudo a través de conocidos que de amigos cercanos, porque los conocidos se mueven en círculos distintos y traen información nueva. Un estudio con millones de usuarios de LinkedIn publicado en la revista Science en 2022 confirmó el principio: los lazos moderadamente débiles son los más útiles para encontrar oportunidades.","lecciones":[{"titulo":"Haz tu lista","texto":"Escribe 30 a 50 nombres sin filtrar, recorriendo cada ámbito de tu vida.\n\nRecorre trabajo actual y anterior, gremios y asociaciones, universidad y cursos, comunidad (club, colegio de los hijos, deporte) y contactos digitales con quienes has interactuado. No pienses todavía si son “buenos contactos”: el objetivo es ver tu red completa. La mayoría de las personas descubre que conoce más empresarios y gerentes de lo que pensaba."},{"titulo":"Lazos fuertes y débiles","texto":"Tu círculo cercano te da confianza; tus conocidos te dan acceso a información y personas nuevas.\n\nLos lazos fuertes (familia, amigos cercanos, colegas diarios) comparten tu misma información. Los lazos débiles (excolegas, contactos de eventos, conocidos de conocidos) conectan con mundos distintos. Para encontrar oportunidades, necesitas ambos: los fuertes para pedir introducciones con confianza y los débiles para descubrir empresas que no conocías."},{"titulo":"Clasifica","texto":"Califica cada contacto de 1 a 3 en confianza, acceso a decisores y potencial de oportunidad.\n\nConfianza: ¿te atendería el teléfono hoy? Acceso: ¿decide o conoce a quien decide? Potencial: ¿su empresa o su entorno tiene señales de oportunidad (consumo alto, sede propia, expansión)? Suma los puntajes. Los contactos con mayor total son tus primeras conversaciones; los de alta confianza y bajo potencial pueden presentarte a otros."},{"titulo":"Activa sin vender","texto":"Empieza con una pregunta útil o un aporte, no con una oferta.\n\n“Hola, [nombre]. Estoy trabajando con empresas que están reduciendo su costo de energía con autogeneración. ¿En tu empresa cómo lo están manejando?” O mejor aún: “Vi que están ampliando la planta. ¿Cómo va?”. La conversación natural revela si hay oportunidad. Si la hay, ofrece una introducción con GEENERA; si no, pregunta a quién conoce que enfrente costos altos de energía."}],"ejercicio":"Mapea tu red con el método de los tres criterios y elige tus primeras tres conversaciones.","pasos":["Escribe 30 nombres recorriendo trabajo, gremios, formación, comunidad y digital.","Califica cada uno de 1 a 3 en confianza, acceso y potencial.","Suma los puntajes y ordena la lista.","Elige los tres contactos con mayor puntaje.","Escribe el mensaje de apertura para cada uno, con una pregunta o un aporte."],"quiz":[{"pregunta":"¿Dónde están la mayoría de las oportunidades?","opciones":["En contactos nuevos","En relaciones existentes no activadas","En redes sociales anónimas"],"correcta":1},{"pregunta":"¿Qué demostró Granovetter?","opciones":["Que los lazos débiles traen información y oportunidades nuevas","Que solo sirven los amigos cercanos","Que las redes no importan"],"correcta":0},{"pregunta":"¿Cuáles son los tres criterios de clasificación?","opciones":["Confianza, acceso y potencial","Edad, ciudad y profesión","Seguidores, likes y comentarios"],"correcta":0},{"pregunta":"¿Cómo conviene activar un contacto?","opciones":["Con una oferta directa","Con una pregunta útil o un aporte","Con un catálogo"],"correcta":1}],"accion":"Escribe esta semana a los tres contactos con mayor puntaje en tu mapa."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-identificar-oportunidades-sin-vender', 'Cómo identificar oportunidades sin vender', 111, true, 5, 'relaciones', 'micro',
          14, 'Principiante', array['referidor']::text[], 'aliado', false, false, true, false,
          null, 'Escucha activa y preguntas que revelan necesidades reales.', 't-diag', 138, '2026-03-24')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Escucha activa: qué es y cómo practicarla","Preguntas que revelan necesidades reales","Señales verbales de una oportunidad","Cómo pasar de la conversación al referido"],"contexto":"Muchas personas evitan referir porque no quieren sentirse vendedoras. La buena noticia es que identificar oportunidades no requiere vender: requiere escuchar con atención y hacer buenas preguntas. Las oportunidades aparecen solas cuando la otra persona habla de sus problemas.\n\nEl psicólogo Carl Rogers popularizó en los años cincuenta el concepto de escucha activa: escuchar para comprender, no para responder. En una conversación comercial, esto significa resistir la tentación de proponer una solución en cuanto aparece un problema, y en cambio profundizar hasta entender su magnitud, sus causas y su impacto.","lecciones":[{"titulo":"Escucha activa","texto":"Escucha para entender, parafrasea lo que oíste y pregunta antes de proponer.\n\nTres prácticas concretas: 1) Deja que la otra persona termine sus frases, aunque creas saber qué dirá. 2) Parafrasea: “Si te entiendo bien, lo que más te preocupa es que la factura sube cada mes sin que puedas hacer nada”. 3) Haz una pregunta de profundización antes de cualquier propuesta. La persona se siente comprendida y comparte más información."},{"titulo":"Preguntas que revelan","texto":"Preguntas abiertas sobre retos, cambios, costos y planes.\n\n“¿Qué ha cambiado en tu operación este año?”, “¿cuál es el costo que más te preocupa?”, “¿qué proyectos tienen para el próximo año?”, “¿qué han intentado para resolverlo?”. Son preguntas sobre el negocio del otro, que cualquier persona interesada haría. No mencionan tu solución, pero revelan si existe una necesidad que puedas conectar."},{"titulo":"Señales verbales","texto":"Quejas sobre costos, menciones a expansión, metas de sostenibilidad o frustración con un proveedor.\n\nFrases como “la energía está carísima”, “vamos a ampliar la planta”, “nuestro cliente nos pide reducir emisiones” o “estamos buscando cómo bajar costos” son señales claras. Cuando las escuches, no saltes a la solución: pregunta más. “¿Cuánto están pagando?”, “¿cuándo sería la ampliación?”. La profundidad de la respuesta te dice qué tan real es la oportunidad."},{"titulo":"De la conversación al referido","texto":"Ofrece la conexión como un favor, no como una venta.\n\nCuando la necesidad está clara, la propuesta es natural: “Conozco un equipo que hace exactamente eso. ¿Te parecería útil que revisen tu caso, sin compromiso?”. Si acepta, pide los datos del Referido Perfecto y su autorización para ser contactado. Si duda, ofrece enviarle información y retomar en unos días. Nunca registres a alguien que no sabe que será contactado."}],"ejercicio":"Practica escucha activa en tres conversaciones esta semana y anota las señales que detectes.","pasos":["Elige tres conversaciones de la semana (reuniones, almuerzos, llamadas).","En cada una, haz al menos dos preguntas abiertas sobre retos o planes.","Parafrasea una vez lo que te dicen antes de responder.","Anota las señales verbales que escuchaste.","Si detectas una oportunidad, ofrece la conexión con GEENERA como un favor."],"quiz":[{"pregunta":"¿Qué es la escucha activa?","opciones":["Escuchar para responder rápido","Escuchar para comprender, parafrasear y preguntar","Hablar más que el otro"],"correcta":1},{"pregunta":"¿Qué hacer cuando escuchas una señal de oportunidad?","opciones":["Proponer de inmediato","Profundizar con preguntas","Cambiar de tema"],"correcta":1},{"pregunta":"¿Cuál es una señal verbal de oportunidad?","opciones":["“Vamos a ampliar la planta”","“Qué buen clima”","“Me gusta el fútbol”"],"correcta":0},{"pregunta":"¿Cómo ofrecer la conexión?","opciones":["Como un favor sin compromiso","Como una venta urgente","Sin preguntar"],"correcta":0}],"accion":"Haz dos preguntas abiertas sobre retos en cada conversación de negocios esta semana."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('venta-consultiva-para-personas-que-no-son-vendedores', 'Venta consultiva para personas que no son vendedores', 112, true, 5, 'relaciones', 'curso',
          36, 'Principiante', array['referidor']::text[], 'aliado', true, false, false, false,
          null, 'Un método simple para ayudar sin sentirte vendedor.', 't-diag', 76, '2026-04-04')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es la venta consultiva y por qué funciona","El método SPIN en lenguaje sencillo","Cómo diagnosticar antes de recomendar","Cómo manejar la conversación sin presión","Cómo cerrar con un siguiente paso"],"contexto":"La venta consultiva parte de una idea simple: ayudar al cliente a tomar una buena decisión, aunque esa decisión no sea comprar. En lugar de presentar un producto, el consultor diagnostica la situación, ayuda a dimensionar el problema y solo entonces recomienda una solución.\n\nEl método más estudiado es SPIN Selling, desarrollado por Neil Rackham a partir del análisis de más de 35.000 llamadas comerciales en la década de 1980. Su hallazgo central: en ventas complejas, los vendedores exitosos hacen más preguntas y de mejor calidad, especialmente preguntas que ayudan al cliente a ver las consecuencias de su problema. Es un método ideal para personas que no se sienten vendedoras, porque se basa en curiosidad y no en persuasión.","lecciones":[{"titulo":"La mentalidad consultiva","texto":"Tu objetivo es entender y ayudar, no convencer. Si no hay fit, lo dices.\n\nUn consultor gana credibilidad cuando es capaz de decir “creo que esto no es para ustedes ahora”. Esa honestidad hace que el cliente confíe en tus recomendaciones cuando sí hay una oportunidad. Para un aliado de Aliados del Sol, esto significa referir solo cuando hay señales reales y explicar con transparencia qué pasará después."},{"titulo":"S de Situación","texto":"Preguntas sobre el contexto: operación, costos, estructura. Pocas y bien elegidas.\n\n“¿En qué horario opera la planta?”, “¿cuánto pagan de energía al mes?”, “¿la sede es propia?”. Son necesarias, pero aburren si son demasiadas. Investiga antes lo que puedas averiguar por tu cuenta y usa estas preguntas solo para lo que no está disponible."},{"titulo":"P de Problema","texto":"Preguntas que exploran dificultades e insatisfacciones.\n\n“¿Qué tan predecible es su costo de energía?”, “¿qué les preocupa de la factura?”, “¿han tenido problemas con cortes o calidad de la energía?”. Aquí el cliente empieza a hablar de lo que no funciona. Escucha el lenguaje exacto que usa: lo usarás después."},{"titulo":"I de Implicación y N de Necesidad","texto":"Implicación: las consecuencias del problema. Necesidad: el valor de resolverlo, dicho por el cliente.\n\nImplicación: “Si la tarifa sigue subiendo al ritmo del último año, ¿qué efecto tendría en sus márgenes?”, “¿cómo afecta eso su competitividad frente a importados?”. Necesidad: “Si pudiera fijar parte de ese costo durante 20 años, ¿qué haría con el ahorro?”. Cuando el cliente describe el valor con sus palabras, la recomendación deja de ser una venta y se convierte en la respuesta a algo que él mismo identificó."},{"titulo":"Recomendar y cerrar","texto":"Resume lo que entendiste, recomienda un siguiente paso concreto y acuerda una fecha.\n\n“Por lo que me cuentas, pagan cerca de $25 millones al mes, operan de día y la sede es propia. Creo que vale la pena que el equipo de GEENERA revise su factura y les muestre una cifra real. ¿Te parece si les presento esta semana?”. Un cierre consultivo no presiona: propone el siguiente paso lógico."}],"ejercicio":"Prepara y aplica una conversación SPIN con un contacto de tu red.","pasos":["Elige un contacto con posible necesidad de reducir costos de energía.","Escribe dos preguntas de situación, dos de problema, dos de implicación y una de necesidad.","Ten la conversación y anota las frases textuales del contacto.","Resume lo que entendiste y propone un siguiente paso concreto.","Si hay fit, registra el referido con los datos completos."],"quiz":[{"pregunta":"¿Qué hallazgo central tuvo Rackham?","opciones":["Los vendedores exitosos hablan más","En ventas complejas, los exitosos hacen más y mejores preguntas","El precio decide todo"],"correcta":1},{"pregunta":"¿Qué exploran las preguntas de implicación?","opciones":["El contexto","Las consecuencias del problema","El nombre del cliente"],"correcta":1},{"pregunta":"¿Por qué funcionan las preguntas de necesidad?","opciones":["Porque el cliente describe el valor con sus palabras","Porque presionan","Porque son cortas"],"correcta":0},{"pregunta":"¿Qué hace un consultor si no hay fit?","opciones":["Lo dice con honestidad","Insiste igual","Desaparece"],"correcta":0}],"accion":"Usa una pregunta de implicación en tu próxima conversación de negocios."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-hacer-una-introduccion-de-alto-valor', 'Cómo hacer una introducción de alto valor', 113, true, 5, 'relaciones', 'flash',
          6, 'Principiante', array['referidor']::text[], 'aliado', false, false, false, false,
          null, 'La estructura de un correo o WhatsApp que abre puertas.', 't-diag', 74, '2026-05-11')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["La estructura de una introducción que abre puertas","Introducción con doble consentimiento","Errores que restan credibilidad"],"contexto":"Una buena introducción es uno de los favores más valiosos que puedes hacer: conecta a dos personas que se benefician de conocerse y transfiere parte de tu confianza a esa nueva relación. Una mala introducción, en cambio, incomoda a ambas partes y desgasta tu reputación.\n\nEn Aliados del Sol, la introducción es el momento en que tu relación con el empresario se conecta con el equipo de GEENERA. Hacerla bien multiplica la probabilidad de que la primera conversación ocurra y avance.","lecciones":[{"titulo":"Doble consentimiento","texto":"Pregunta a ambas partes antes de conectarlas.\n\nLa práctica conocida como double opt-in consiste en confirmar con el empresario que quiere ser contactado y con el equipo de GEENERA que el perfil encaja. Así nadie recibe una introducción que no esperaba. En la práctica: “¿Te parece si te presento a una consultora de GEENERA para que revise tu factura?” y, en paralelo, registras el referido en el Hub con los datos completos."},{"titulo":"La estructura","texto":"Por qué los conectas, quién es cada uno en una línea, qué gana cada uno y cuál es el siguiente paso.\n\n“[Empresario], te presento a [consultora], de GEENERA. Hablamos la semana pasada de cómo bajar el costo de energía de la planta y ella lidera proyectos solares para empresas como la tuya. [Consultora], [empresario] es gerente de [empresa]; operan de día, tienen cubierta propia y pagan cerca de $20 millones al mes. Les dejo para que coordinen una llamada esta semana.” Breve, específica y con un siguiente paso."},{"titulo":"Errores frecuentes","texto":"Introducir sin permiso, ser vago, no dar contexto o desaparecer después.\n\n“Les presento, creo que deberían hablar” no ayuda a nadie. Tampoco presentar a alguien que no sabe que será contactado. Después de la introducción, haz seguimiento a los pocos días: “¿Pudieron hablar?”. Ese gesto muestra compromiso y te permite saber si la conexión funcionó."}],"ejercicio":"Redacta una introducción de alto valor para un referido real o de práctica.","pasos":["Elige un contacto con quien ya confirmaste interés.","Escribe la introducción con la estructura de cuatro partes.","Revisa que sea breve, específica y con siguiente paso.","Programa un recordatorio para hacer seguimiento a los tres días."],"quiz":[{"pregunta":"¿Qué es el doble consentimiento?","opciones":["Confirmar con ambas partes antes de conectarlas","Enviar dos correos iguales","Pedir dos firmas"],"correcta":0},{"pregunta":"¿Qué debe incluir una buena introducción?","opciones":["Motivo, quién es cada uno, beneficio y siguiente paso","Solo los nombres","Un catálogo"],"correcta":0},{"pregunta":"¿Qué hacer después de la introducción?","opciones":["Desaparecer","Hacer seguimiento a los pocos días","Llamar todos los días"],"correcta":1}],"accion":"Haz tu próxima introducción con la estructura de cuatro partes y doble consentimiento."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-proteger-tu-reputacion-al-referir', 'Cómo proteger tu reputación al referir', 114, true, 5, 'relaciones', 'flash',
          7, 'Principiante', array['referidor']::text[], 'aliado', false, false, false, false,
          null, 'Refiere con criterio para que cada introducción sume confianza.', 't-perfecto', 72, '2026-06-18')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Por qué cada referido compromete tu reputación","Las reglas de un referido responsable","Cómo manejar un referido que no avanzó"],"contexto":"Cuando refieres a alguien, prestas tu reputación. Si la experiencia es buena, tu red confía más en ti; si es mala, confía menos, aunque la responsabilidad no haya sido tuya. Por eso, referir con criterio no es solo una cuestión de puntos: es una forma de cuidar tu capital más valioso.\n\nEl programa Aliados del Sol está diseñado para proteger esa reputación: GEENERA contacta solo a quien autorizó el contacto, informa cada etapa y nunca penaliza al aliado por resultados comerciales que no dependen de él. Pero hay prácticas que dependen solo de ti.","lecciones":[{"titulo":"Refiere con permiso","texto":"Nunca registres a alguien que no sabe que será contactado.\n\nUna llamada inesperada de un tercero que dice “nos dieron su número” genera desconfianza hacia ti y hacia la empresa que llama. Pide siempre autorización explícita: “¿Te parece si les paso tus datos para que te llamen esta semana?”. Esa frase protege tu relación y aumenta la probabilidad de que la llamada sea bien recibida."},{"titulo":"Refiere con criterio","texto":"Envía empresas con señales reales y datos verificados.\n\nUn referido con datos falsos, una empresa que claramente no encaja o un contacto sin poder de decisión hacen perder tiempo a todos. Aplica el Opportunity Checker o las cuatro condiciones antes de registrar, y verifica teléfono y correo. Tu calidad de referidos se refleja en tu nivel y en la confianza del equipo comercial."},{"titulo":"Gestiona expectativas","texto":"Explica qué pasará después y acompaña si algo no avanza.\n\nDile al empresario cuándo lo contactarán, qué información le pedirán y que no hay compromiso. Si la oportunidad no avanza —porque no es viable o porque el cliente decide no seguir—, eso no es un fracaso: es un resultado normal del proceso. Agradece su tiempo, mantén la relación y, si algo salió mal en la atención, infórmalo a tu consultora para que se corrija."}],"ejercicio":"Revisa tus últimos referidos con las tres reglas y define qué harás distinto.","pasos":["Lista tus últimos tres a cinco referidos.","Para cada uno, verifica si tenía permiso, criterio y expectativas claras.","Identifica un aprendizaje concreto.","Escribe la frase que usarás para pedir permiso en tu próximo referido."],"quiz":[{"pregunta":"¿Qué compromete cada referido?","opciones":["Nada","Tu reputación","Solo tus puntos"],"correcta":1},{"pregunta":"¿Qué hacer antes de registrar un referido?","opciones":["Pedir autorización explícita","Nada","Enviar los datos sin avisar"],"correcta":0},{"pregunta":"Si una oportunidad no avanza porque no es viable…","opciones":["Es un fracaso del aliado","Es un resultado normal; mantén la relación","Debes insistir"],"correcta":1}],"accion":"Pide autorización explícita antes de registrar tu próximo referido."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('networking-estrategico', 'Networking estratégico', 115, true, 5, 'relaciones', 'curso',
          32, 'Intermedio', array['referidor', 'gremio']::text[], 'aliado', false, false, true, false,
          null, 'Menos tarjetas, más relaciones que generan oportunidades.', 't-red', 130, '2026-07-25')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Diferencia entre networking social y estratégico","Cómo elegir a qué eventos y comunidades ir","Qué hacer antes, durante y después de un encuentro","Cómo mantener viva una red sin dedicarle horas","Cómo medir si tu networking funciona"],"contexto":"El networking tiene mala fama porque muchas personas lo practican mal: reparten tarjetas, hablan de sí mismas y nunca hacen seguimiento. El networking estratégico es distinto: es la construcción intencional de relaciones de confianza con personas con quienes puedes crear valor mutuo.\n\nEl antropólogo Robin Dunbar propuso que las personas podemos mantener relaciones estables con alrededor de 150 personas, con círculos más pequeños de mayor cercanía. Eso significa que no necesitas conocer a todo el mundo: necesitas cultivar bien un número limitado de relaciones relevantes. Este curso te da un método para hacerlo.","lecciones":[{"titulo":"Define tu objetivo","texto":"¿A quién necesitas conocer y para qué? Sin objetivo, el networking es solo vida social.\n\nUn objetivo concreto: “conocer a diez gerentes de empresas manufactureras en Santander este semestre” o “construir relación con tres líderes gremiales que conecten con empresas de alimentos”. El objetivo define a qué eventos ir, a quién buscar y qué conversaciones priorizar. Revísalo cada trimestre."},{"titulo":"Elige dónde estar","texto":"Pocos espacios, bien elegidos y con continuidad.\n\nEs mejor asistir con regularidad a dos o tres espacios donde está tu audiencia (un gremio, una cámara de comercio, un comité sectorial) que ir a veinte eventos distintos una sola vez. La confianza se construye con encuentros repetidos. Participar activamente —en un comité, como panelista o como organizador— multiplica tu visibilidad."},{"titulo":"Antes y durante","texto":"Revisa quién asistirá, prepara tres preguntas y escucha más de lo que hablas.\n\nAntes del evento, revisa la lista de asistentes o los perfiles de LinkedIn de los organizadores y elige tres personas a quienes te gustaría conocer. Durante el evento, presenta lo que haces en una frase y pregunta por el negocio del otro: “¿Qué está siendo lo más retador para ustedes este año?”. Busca conversaciones de calidad, no cantidad de tarjetas."},{"titulo":"Después: el seguimiento","texto":"El valor del networking está en las 48 horas siguientes al encuentro.\n\nEnvía un mensaje breve a cada persona relevante: “Gracias por la conversación sobre [tema]. Como te comenté, te comparto [recurso]”. Agrégala a tu mapa de red con una nota de lo que hablaron. Propón un siguiente encuentro solo si hay un motivo claro. Sin seguimiento, el 90% de los contactos de un evento se olvida en pocas semanas."},{"titulo":"Mantener y medir","texto":"Una rutina semanal breve y tres indicadores simples.\n\nDedica 30 minutos semanales a tu red: felicitar un logro, compartir un dato útil, hacer una introducción. Mide tres cosas cada trimestre: nuevas relaciones relevantes, conversaciones de negocio generadas y oportunidades o referidos derivados. Si los números no se mueven, revisa dónde estás invirtiendo tu tiempo."}],"ejercicio":"Diseña tu plan de networking estratégico para el próximo trimestre.","pasos":["Escribe tu objetivo de networking en una frase concreta.","Elige dos o tres espacios donde está tu audiencia y comprométete a asistir con regularidad.","Identifica diez personas que te gustaría conocer este trimestre.","Define tu rutina semanal de 30 minutos para mantener la red.","Anota los tres indicadores que medirás al final del trimestre."],"quiz":[{"pregunta":"¿Qué diferencia el networking estratégico del social?","opciones":["Tiene un objetivo e intención","Hay más comida","Se hace solo en línea"],"correcta":0},{"pregunta":"¿Qué propuso Robin Dunbar?","opciones":["Que podemos mantener relaciones estables con alrededor de 150 personas","Que debemos conocer a miles","Que el networking no sirve"],"correcta":0},{"pregunta":"¿Dónde está el valor del networking?","opciones":["En las tarjetas","En el seguimiento de las 48 horas siguientes","En el número de eventos"],"correcta":1},{"pregunta":"¿Qué es mejor?","opciones":["Ir a veinte eventos distintos una vez","Asistir con regularidad a pocos espacios relevantes","No ir a ninguno"],"correcta":1}],"accion":"Envía en las próximas 48 horas un mensaje de seguimiento a las personas que conociste en tu último evento."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('linkedin-para-generar-oportunidades', 'LinkedIn para generar oportunidades', 116, true, 5, 'marca', 'micro',
          18, 'Principiante', array['referidor', 'financiero']::text[], 'aliado', false, false, true, false,
          null, 'Perfil, red y conversaciones que atraen al cliente correcto.', 't-linkedin', 128, '2026-08-05')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Un perfil que comunica qué resuelves","Cómo construir una red con intención","Cómo convertir interacciones en conversaciones","Cómo medir tu actividad sin obsesionarte"],"contexto":"LinkedIn tiene más de mil millones de miembros en el mundo y es la red profesional de referencia para conversaciones B2B en Colombia y América Latina. Para un aliado, es una vitrina donde gerentes y empresarios te encuentran, te evalúan y deciden si vale la pena conversar contigo.\n\nLa mayoría de los perfiles funcionan como hojas de vida: listan cargos y funciones. Los perfiles que generan oportunidades funcionan como una propuesta de valor: dicen a quién ayudas, en qué y cómo contactarte. La diferencia no está en publicar todos los días, sino en un perfil claro, una red bien elegida y conversaciones con intención.","lecciones":[{"titulo":"El perfil como propuesta","texto":"Foto profesional, titular con el problema que resuelves, sección “Acerca de” orientada al cliente y destacados con criterio.\n\nEl titular es lo más visto: aparece en búsquedas, comentarios y mensajes. “Ejecutivo comercial” dice poco; “Conecto empresas industriales con soluciones para reducir su costo de energía” dice a quién ayudas y en qué. La sección “Acerca de” debe tener tres párrafos: qué problema resuelves, para quién y cómo contactarte. En Destacados, incluye uno o dos contenidos que muestren tu criterio."},{"titulo":"Una red con intención","texto":"Conecta con tu audiencia objetivo, personaliza las invitaciones y prioriza calidad.\n\nDefine tu audiencia: gerentes de plantas en Santander, directivos financieros de empresas medianas, líderes gremiales. Busca perfiles con esos criterios y envía invitaciones con una nota breve que explique por qué quieres conectar. Una red de 500 personas relevantes vale más que una de 5.000 aleatorias."},{"titulo":"De interacción a conversación","texto":"Comenta con criterio, responde con preguntas y propone conversaciones cuando hay un motivo.\n\nCuando alguien de tu audiencia comenta tu publicación o publica algo relevante, es una oportunidad para iniciar una conversación. Comenta aportando un punto de vista, no solo “excelente”. Si la interacción continúa, escribe un mensaje: “Gracias por tu comentario sobre [tema]. ¿Cómo lo están viviendo en [empresa]?”. La conversación privada es donde aparecen las oportunidades."},{"titulo":"Medir sin obsesionarte","texto":"Mira visitas al perfil, invitaciones aceptadas y conversaciones iniciadas, no solo likes.\n\nLinkedIn ofrece el Social Selling Index (SSI), que mide cuatro dimensiones: marca profesional, búsqueda de personas adecuadas, interacción con información y construcción de relaciones. Es una guía útil, pero el indicador que importa es otro: cuántas conversaciones de negocio se originaron en LinkedIn cada mes."}],"ejercicio":"Optimiza tu perfil de LinkedIn y envía diez invitaciones personalizadas a tu audiencia objetivo.","pasos":["Reescribe tu titular con la fórmula “a quién ayudo + en qué”.","Reescribe la sección “Acerca de” en tres párrafos orientados al cliente.","Define tu audiencia objetivo con tres criterios.","Busca diez perfiles que cumplan esos criterios.","Envía las diez invitaciones con una nota personalizada."],"quiz":[{"pregunta":"¿Qué debe comunicar el titular?","opciones":["Solo tu cargo","A quién ayudas y en qué","Tu fecha de nacimiento"],"correcta":1},{"pregunta":"¿Qué red vale más?","opciones":["5.000 contactos aleatorios","500 contactos relevantes","Ninguna"],"correcta":1},{"pregunta":"¿Dónde aparecen las oportunidades?","opciones":["En los likes","En las conversaciones privadas","En la foto de portada"],"correcta":1},{"pregunta":"¿Qué mide el SSI?","opciones":["Marca, búsqueda, interacción y relaciones","Solo seguidores","El salario"],"correcta":0}],"accion":"Reescribe hoy tu titular de LinkedIn con la fórmula “a quién ayudo + en qué”."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('marca-personal-para-consultores', 'Marca personal para consultores', 117, true, 5, 'marca', 'micro',
          16, 'Intermedio', array['referidor']::text[], 'aliado', false, false, false, false,
          null, 'Cómo ser recordado por lo que resuelves.', 't-linkedin', 66, '2026-09-12')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es marca personal y por qué importa en servicios","Cómo definir tu posicionamiento","Cómo demostrar criterio con contenido y casos","Cómo hacer que te recomienden"],"contexto":"En servicios profesionales, los clientes no compran un producto: compran la confianza en una persona. La marca personal es la reputación que tienes sobre qué resuelves y qué tan bien lo haces. Existe aunque no la gestiones; la pregunta es si la defines tú o la definen otros.\n\nPara un consultor o referidor, una marca clara reduce el esfuerzo comercial: las personas saben para qué buscarte y a quién recomendarte. Una marca difusa obliga a explicar una y otra vez qué haces. Este curso te ayuda a construir una marca que te haga recordable por lo que resuelves.","lecciones":[{"titulo":"Posicionamiento","texto":"La intersección entre lo que haces muy bien, lo que tu audiencia necesita y lo que te diferencia.\n\nResponde tres preguntas: ¿en qué problema eres especialmente bueno?, ¿quién tiene ese problema y está dispuesto a resolverlo?, ¿qué haces distinto a otros que resuelven lo mismo? La respuesta se resume en una frase: “Ayudo a [audiencia] a [resultado] mediante [enfoque]”. Cuanto más específica, más fácil de recordar."},{"titulo":"Demostrar criterio","texto":"Contenido útil, casos concretos y opiniones fundamentadas.\n\nLa marca se construye mostrando cómo piensas: publicaciones con datos y opinión, casos (con permiso o anonimizados) que muestran el problema, la decisión y el resultado, y respuestas a las preguntas frecuentes de tus clientes. El objetivo no es la viralidad, sino que tu audiencia te asocie con un tema. Un consultor reconocido por “costos de energía en la industria santandereana” tiene una marca más útil que uno que habla de todo."},{"titulo":"Consistencia","texto":"Mismo mensaje en perfil, conversaciones, presentaciones y contenido.\n\nTu frase de posicionamiento debe aparecer en tu titular de LinkedIn, en tu presentación en eventos, en tu firma de correo y en la forma como te presentan otros. La consistencia hace que las personas te recuerden y repitan tu mensaje cuando te recomiendan."},{"titulo":"Que te recomienden","texto":"Entrega resultados, facilita la recomendación y pide testimonios.\n\nLa recomendación es el resultado más valioso de una marca personal. Facilítala: dile a tus clientes satisfechos qué tipo de cliente buscas y pide un testimonio breve que puedas compartir. Mantén el contacto con quienes ya trabajaron contigo: son tu principal fuente de nuevas oportunidades."}],"ejercicio":"Escribe tu frase de posicionamiento y úsala en tres lugares esta semana.","pasos":["Responde las tres preguntas de posicionamiento.","Escribe tu frase con la fórmula “Ayudo a [audiencia] a [resultado] mediante [enfoque]”.","Actualiza tu titular de LinkedIn con la frase.","Agrégala a tu firma de correo.","Úsala para presentarte en tu próxima reunión o evento."],"quiz":[{"pregunta":"¿Qué compran los clientes en servicios profesionales?","opciones":["Un producto","Confianza en una persona","Solo precio"],"correcta":1},{"pregunta":"¿Qué hace más recordable un posicionamiento?","opciones":["Que sea general","Que sea específico","Que sea largo"],"correcta":1},{"pregunta":"¿Cómo se demuestra criterio?","opciones":["Con contenido útil, casos y opiniones fundamentadas","Con muchos seguidores","Con un logo"],"correcta":0},{"pregunta":"¿Qué facilita las recomendaciones?","opciones":["Decir qué tipo de cliente buscas y pedir testimonios","No pedir nada","Bajar precios"],"correcta":0}],"accion":"Pide un testimonio breve a un cliente o contacto satisfecho."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-para-profesionales-independientes', 'IA para profesionales independientes', 118, true, 5, 'ia', 'curso',
          34, 'Principiante', array['referidor']::text[], 'aliado', false, true, false, false,
          null, 'Tu asistente para propuestas, correos, investigación y seguimiento.', 't-prompts', 64, '2026-01-19')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["La IA como asistente de un profesional que trabaja solo","Propuestas comerciales más rápidas y mejores","Investigación de clientes y mercados","Contenido y marca personal con tu voz","Organización, seguimiento y administración"],"contexto":"Un consultor, asesor o referidor independiente es, al mismo tiempo, su área comercial, su equipo de investigación, su departamento de marketing y su asistente administrativo. La IA no reemplaza ninguna de esas funciones, pero puede hacer que cada una tome una fracción del tiempo.\n\nPara un profesional independiente, el tiempo es literalmente ingreso: cada hora dedicada a tareas administrativas es una hora que no se dedica a clientes o a generar nuevas oportunidades. Este curso organiza los usos de la IA según las funciones de tu negocio, para que montes un sistema de trabajo y no solo pruebes herramientas.","lecciones":[{"titulo":"Propuestas comerciales","texto":"De notas de una reunión a una propuesta estructurada en minutos.\n\nPega tus notas de la reunión y pide: “Con estas notas, redacta una propuesta de servicios con: entendimiento de la necesidad, enfoque, entregables, cronograma, inversión y siguientes pasos. Tono profesional y cercano. Máximo dos páginas”. Luego ajusta el precio, los detalles y el tono. Guarda tus mejores propuestas como ejemplos para que la IA imite su estructura."},{"titulo":"Investigación","texto":"Clientes potenciales, sectores, competidores y tendencias.\n\nAntes de contactar a un cliente potencial, pide un perfil con información pública. Para planear tu trimestre, pide un análisis de las tendencias de los sectores donde trabajas. Para posicionarte, pide un mapa de cómo comunican otros profesionales de tu área. Recuerda verificar las cifras y fuentes."},{"titulo":"Contenido y marca","texto":"Ideas, borradores y edición de publicaciones en tu propia voz.\n\nLa IA puede generar ideas a partir de las preguntas de tus clientes, redactar borradores con base en tus experiencias y editar textos para que suenen más directos. La clave es darle ejemplos de tu estilo y tus opiniones: el contenido genérico no construye marca. Tú aportas la experiencia y el criterio; la IA, la velocidad."},{"titulo":"Seguimiento","texto":"Recordatorios, mensajes y resúmenes que no dependen de tu memoria.\n\nCombina una hoja de seguimiento o un CRM sencillo con plantillas de mensajes personalizadas por la IA. Cada viernes, pide a la IA que revise tu lista de contactos pendientes y redacte un mensaje de seguimiento para cada uno según su contexto. Envía los que tengan sentido. Ninguna oportunidad debería perderse por olvido."},{"titulo":"Administración","texto":"Cotizaciones, contratos base, cobros y organización de documentos.\n\nLa IA puede ayudarte a preparar plantillas de cotización, revisar que un contrato tenga las cláusulas básicas (sin reemplazar a un abogado), redactar recordatorios de pago cordiales y organizar tu información. Son tareas pequeñas que, sumadas, consumen horas cada mes."}],"ejercicio":"Mapea las funciones de tu negocio independiente y monta un uso de IA para cada una.","pasos":["Lista las cinco funciones de tu negocio: comercial, investigación, marketing, seguimiento y administración.","Para cada una, identifica la tarea que más tiempo te toma.","Escribe una instrucción de IA para cada tarea.","Prueba las cinco instrucciones durante una semana.","Guarda las que funcionaron en tu librería de prompts."],"quiz":[{"pregunta":"¿Por qué la IA es especialmente valiosa para un independiente?","opciones":["Porque cumple varias funciones y su tiempo es ingreso","Porque reemplaza a los clientes","No lo es"],"correcta":0},{"pregunta":"¿Qué mejora la calidad de una propuesta generada con IA?","opciones":["Darle ejemplos de tus mejores propuestas","Pedirla sin contexto","Usar solo mayúsculas"],"correcta":0},{"pregunta":"¿Qué aporta el profesional en el contenido de marca?","opciones":["Experiencia y criterio","Nada","Solo la foto"],"correcta":0},{"pregunta":"¿La IA reemplaza a un abogado al revisar un contrato?","opciones":["Sí","No, solo ayuda con una revisión básica","Depende del día"],"correcta":1}],"accion":"Usa la IA para preparar tu próxima propuesta comercial a partir de tus notas."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('automatiza-tus-seguimientos', 'Automatiza tus seguimientos', 119, true, 5, 'ia', 'micro',
          15, 'Intermedio', array['referidor']::text[], 'aliado', false, false, false, false,
          null, 'Recordatorios y mensajes que no dependen de tu memoria.', 't-automatiza', 62, '2026-02-26')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Por qué se pierden las oportunidades en el seguimiento","Diseñar una cadencia de seguimiento","Herramientas para recordatorios automáticos","Mensajes de seguimiento que no presionan"],"contexto":"La mayoría de las oportunidades no se pierden por un “no”, sino por silencio: un correo que no se respondió, una llamada que no se hizo, un contacto que se enfrió. En ventas B2B, es común que una oportunidad necesite varios contactos antes de avanzar, y muchos profesionales abandonan después del primero o el segundo.\n\nUn sistema de seguimiento que no depende de tu memoria es una de las inversiones más rentables para un aliado: cada oportunidad recibe la atención que necesita, en el momento justo, sin que tengas que recordarla.","lecciones":[{"titulo":"Por qué falla el seguimiento","texto":"Dependemos de la memoria, tememos incomodar y no tenemos un registro único.\n\nEl seguimiento falla por tres razones: no hay un lugar único donde estén todos los contactos pendientes, no hay recordatorios y existe el temor de parecer insistente. La solución combina un registro (hoja o CRM), recordatorios automáticos y mensajes que aportan valor en lugar de solo “recordar”."},{"titulo":"Diseña una cadencia","texto":"Define cuántos contactos, por qué canal y con qué intervalo, según la etapa.\n\nUna cadencia simple para un contacto nuevo: día 1, mensaje inicial; día 4, seguimiento con un dato o recurso útil; día 10, pregunta breve; día 20, mensaje de cierre amable (“entiendo que no es el momento; quedo atento”). Para un referido en curso, revisa cada dos semanas su etapa en el Hub y, si se estanca, conversa con tu consultora."},{"titulo":"Herramientas","texto":"Recordatorios en el calendario, tareas en el correo, CRM o automatizaciones simples.\n\nLa opción más sencilla: al terminar cada conversación, crea una tarea con fecha en Outlook, Google Tasks o tu calendario. Un paso más: una hoja de seguimiento con la fecha del próximo contacto y formato condicional que resalte las vencidas. La opción más completa: un CRM o una automatización que cree recordatorios cuando un contacto no responde en cierto número de días."},{"titulo":"Mensajes que no presionan","texto":"Aporta algo nuevo en cada seguimiento: un dato, una pregunta o un recurso.\n\nEn lugar de “¿pudiste revisar mi correo?”, escribe: “Vi este dato sobre el aumento de la tarifa en [región] y me acordé de nuestra conversación. ¿Siguen evaluando opciones?”. Cada mensaje debe poder leerse solo y ser fácil de responder. Usa la IA para personalizar la plantilla según el contexto de cada contacto."}],"ejercicio":"Diseña tu cadencia de seguimiento y configura los recordatorios para tus contactos pendientes.","pasos":["Lista todos los contactos u oportunidades que tienes pendientes.","Define la cadencia que usarás (número de contactos, canal e intervalo).","Crea un recordatorio con fecha para el próximo contacto de cada uno.","Escribe tres plantillas de seguimiento que aporten valor.","Revisa cada viernes los seguimientos de la semana siguiente."],"quiz":[{"pregunta":"¿Cuál es la causa más común de oportunidades perdidas?","opciones":["Un “no” rotundo","El silencio por falta de seguimiento","El precio"],"correcta":1},{"pregunta":"¿Qué debe aportar un buen mensaje de seguimiento?","opciones":["Algo nuevo: un dato, pregunta o recurso","Solo “¿viste mi correo?”","Presión"],"correcta":0},{"pregunta":"¿Qué es una cadencia?","opciones":["El número, canal e intervalo de los contactos","Un tipo de música","Un CRM específico"],"correcta":0},{"pregunta":"¿Cada cuánto revisar la etapa de un referido en curso?","opciones":["Cada dos semanas","Una vez al año","Nunca"],"correcta":0}],"accion":"Crea hoy un recordatorio con fecha para cada oportunidad pendiente."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('negociacion-y-manejo-de-objeciones', 'Negociación y manejo de objeciones', 120, true, 5, 'relaciones', 'curso',
          40, 'Intermedio', array['referidor', 'financiero']::text[], 'aliado', false, false, false, false,
          null, 'Responde con preguntas, no con argumentos.', 't-objeciones', 60, '2026-03-06')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Principios de la negociación basada en intereses","Qué hay detrás de una objeción","Un método de cuatro pasos para responder","Las objeciones más comunes en proyectos solares","Cómo cerrar acuerdos que ambas partes cumplan"],"contexto":"Una objeción no es un rechazo: es una señal de interés acompañada de una duda. Quien objeta está evaluando; quien no tiene interés simplemente no responde. Entender esto cambia la forma de manejar las conversaciones difíciles.\n\nEl método de negociación de Harvard, presentado por Roger Fisher y William Ury en el libro Getting to Yes (1981), propone separar a las personas del problema, enfocarse en intereses y no en posiciones, generar opciones de beneficio mutuo y usar criterios objetivos. Décadas después sigue siendo una de las bases de la negociación profesional. Combinado con técnicas de escucha, permite responder objeciones con preguntas en lugar de argumentos.","lecciones":[{"titulo":"Intereses, no posiciones","texto":"La posición es lo que el otro dice que quiere; el interés es por qué lo quiere.\n\n“Está muy caro” es una posición. Detrás puede haber distintos intereses: no tener caja, no confiar en el ahorro, tener otra prioridad o necesitar justificar la decisión ante una junta. Cada interés requiere una respuesta distinta. Por eso, antes de responder, hay que descubrir qué hay detrás."},{"titulo":"El método de cuatro pasos","texto":"Escucha completa, reconoce, pregunta para entender y responde con un dato o una opción.\n\n1) Escucha la objeción completa sin interrumpir. 2) Reconócela: “Entiendo, es una inversión importante”. 3) Pregunta: “¿Qué le preocupa más: el monto, la recuperación o el momento?”. 4) Responde al interés real con un dato, un caso o una opción. Este orden evita la discusión y convierte la objeción en una conversación."},{"titulo":"Objeciones frecuentes en solar","texto":"Precio, desconfianza en el ahorro, cubierta, mantenimiento y “no es el momento”.\n\n“Es muy caro”: explorar financiación con cuota menor al ahorro. “No creo que ahorre tanto”: mostrar el cálculo con su factura y el monitoreo. “¿Y la cubierta?”: estudio estructural e instalación que preserva la impermeabilidad. “¿Quién lo mantiene?”: plan de mantenimiento y garantías. “No es el momento”: preguntar qué tendría que pasar para que lo fuera, y acordar cuándo retomar."},{"titulo":"MAAN y criterios objetivos","texto":"Conoce tu mejor alternativa y apóyate en estándares que ambas partes acepten.\n\nLa MAAN (mejor alternativa a un acuerdo negociado, o BATNA) es lo que harás si no hay acuerdo. Conocer la tuya y la del cliente te da claridad: la alternativa del cliente a un proyecto solar suele ser seguir pagando una tarifa creciente. Los criterios objetivos —datos de irradiación, precios de referencia, garantías de fabricantes— evitan que la negociación se convierta en una pulseada de voluntades."},{"titulo":"Cerrar acuerdos","texto":"Resume lo acordado, define responsables y fechas, y confírmalo por escrito.\n\nUn acuerdo que no se escribe se interpreta distinto. Al cerrar cualquier conversación de negociación, resume: “Entonces acordamos que ustedes envían las facturas el lunes y GEENERA presenta la propuesta en dos semanas”. Envía ese resumen por escrito. Los acuerdos que ambas partes sienten justos son los que se cumplen."}],"ejercicio":"Prepara respuestas con el método de cuatro pasos para las tres objeciones que más escuchas.","pasos":["Escribe las tres objeciones que más escuchas.","Para cada una, identifica dos posibles intereses detrás.","Escribe la frase de reconocimiento y la pregunta para descubrir el interés.","Prepara un dato, caso u opción para cada interés.","Practica en voz alta con un colega o frente al espejo."],"quiz":[{"pregunta":"¿Qué es una objeción?","opciones":["Un rechazo definitivo","Una señal de interés con una duda","Una ofensa"],"correcta":1},{"pregunta":"¿Qué diferencia una posición de un interés?","opciones":["La posición es lo que se pide; el interés, por qué se pide","Son lo mismo","El interés es el precio"],"correcta":0},{"pregunta":"¿Cuál es el tercer paso del método?","opciones":["Responder con argumentos","Preguntar para entender","Cambiar de tema"],"correcta":1},{"pregunta":"¿Qué es la MAAN?","opciones":["La mejor alternativa si no hay acuerdo","Un tipo de contrato","Un descuento"],"correcta":0}],"accion":"En tu próxima objeción, pregunta qué hay detrás antes de responder."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-identificar-una-oportunidad-solar-en-5-minutos', 'Cómo identificar una oportunidad solar en 5 minutos', 121, true, 5, 'ads', 'flash',
          5, 'Principiante', array['referidor', 'financiero', 'gremio']::text[], 'free', true, false, true, false,
          null, 'Cinco señales que indican que una empresa vale la pena.', 't-solar', 118, '2026-04-13')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Reconocer las cinco señales de una buena oportunidad","Hacer las preguntas justas sin sonar técnico","Saber cuándo una empresa no es candidata","Pasar de la conversación al Referido Perfecto"],"contexto":"No necesitas ser ingeniero para detectar una oportunidad solar. Con cinco señales puedes saber, en una conversación corta, si vale la pena conectar a una empresa con GEENERA.\n\nEl equipo técnico confirma después cada señal con un diagnóstico, pero tu filtro inicial es lo que hace que un referido avance rápido o se quede esperando. Las empresas que cumplen cuatro o cinco señales suelen pasar a evaluación técnica en pocos días; las que cumplen una o dos rara vez se convierten en proyecto. Este flash te da la lista y la forma de verificarla sin que la conversación suene a venta.","lecciones":[{"titulo":"Consumo","texto":"Facturas de varios millones de pesos al mes son la primera señal: sin consumo relevante no hay ahorro relevante.\n\nComo referencia, facturas desde $3 a $5 millones mensuales empiezan a justificar un proyecto empresarial, y las superiores a $15 millones suelen ser prioritarias. Los equipos que más consumen —refrigeración, motores, compresores, hornos eléctricos, aire acondicionado central— son pistas visibles. La pregunta natural es: “¿Más o menos cuánto pagan de energía al mes?”."},{"titulo":"Horario de operación","texto":"El sol produce entre las 6 a. m. y las 6 p. m.; cuanto más coincida la operación con esa franja, mayor el ahorro.\n\nLa energía que se consume en el momento en que se genera evita el costo unitario completo de la factura, mientras que los excedentes se reconocen a un valor menor según la regulación. Fábricas de un turno, comercio, colegios y bodegas aprovechan casi toda la producción; clínicas, hoteles y frío 24/7 aprovechan la parte diurna. Los negocios exclusivamente nocturnos son candidatos débiles."},{"titulo":"Cubierta y espacio","texto":"Se necesitan del orden de 5 a 7 m² de cubierta útil por cada kWp instalado.\n\nTechos amplios en teja metálica o losa, bodegas, parqueaderos o terrenos aledaños permiten instalar sin afectar la operación. Puedes estimar el área en dos minutos con Google Earth: traza el contorno, descuenta 30% por obstáculos y divide entre 6 para obtener los kWp máximos. Si la cubierta está deteriorada, conviene saberlo antes: puede requerir reparación previa."},{"titulo":"Propiedad y decisión","texto":"Sede propia (o arriendo de largo plazo con autorización) y acceso a quien aprueba inversiones.\n\nUn sistema solar se instala sobre la cubierta y se recupera en varios años, así que quien no controla la sede rara vez decide. Pregunta: “Si apareciera una inversión que se paga sola, ¿quién la aprobaría?”. Si tu contacto no decide, pídele que te presente a quien sí lo hace."},{"titulo":"Momento de la empresa","texto":"Expansiones, renovación de equipos, metas de sostenibilidad o presión de costos abren la conversación.\n\nLos momentos de cambio concentran decisiones: una ampliación obliga a revisar la conexión eléctrica; una exigencia de un cliente multinacional obliga a medir emisiones; un alza de la factura genera urgencia. Con cuatro o cinco señales, refiere esta semana con los datos del Referido Perfecto; con tres, completa la información; con menos, deja la empresa en seguimiento."}],"ejercicio":"Evalúa tres empresas de tu red con las cinco señales y elige la que más cumple.","pasos":["Escribe tres empresas de tu red que creas candidatas.","Marca cuántas de las cinco señales cumple cada una.","Para la mejor, identifica qué dato te falta confirmar.","Haz la pregunta que falta en tu próxima conversación.","Si cumple cuatro o cinco señales, regístrala en el Hub con los datos del Referido Perfecto."],"quiz":[{"pregunta":"¿Qué operación favorece más el ahorro solar?","opciones":["Nocturna","Diurna","Solo fines de semana"],"correcta":1},{"pregunta":"¿Qué hace más lenta una oportunidad?","opciones":["Sede arrendada sin autorización","Factura alta","Cubierta amplia"],"correcta":0},{"pregunta":"¿Cuánta cubierta ocupa aproximadamente 1 kWp?","opciones":["0,5 m²","5 a 7 m²","50 m²"],"correcta":1},{"pregunta":"Con cuatro o cinco señales, ¿qué haces?","opciones":["Esperar un año","Referir esta semana con datos completos","Descartar"],"correcta":1}],"accion":"Refiere esta semana la empresa que más señales cumplió, con los datos del Referido Perfecto."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('de-contacto-a-referido-perfecto', 'De contacto a Referido Perfecto', 122, true, 5, 'ads', 'micro',
          12, 'Principiante', array['referidor']::text[], 'aliado', false, false, true, false,
          null, 'Qué datos reunir para que tu referido avance rápido.', 't-perfecto', 116, '2026-05-20')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué datos necesita GEENERA para avanzar","Cómo pedirlos sin incomodar","Por qué la factura acelera todo","Cómo suma a tus Puntos Sol"],"contexto":"Un referido con datos completos avanza en días; uno incompleto puede quedarse semanas esperando. El Referido Perfecto reúne la información mínima para que el equipo comercial actúe de inmediato.\n\nEn los procesos comerciales B2B, el tiempo entre el primer contacto y la primera conversación útil es uno de los principales predictores de cierre: cada día de espera reduce el interés y aumenta la probabilidad de que el cliente reciba otra propuesta. Por eso GEENERA prioriza los referidos que llegan con decisor identificado, autorización de contacto y factura. Tu papel como aliado es reducir la fricción del primer paso; el equipo comercial y técnico se encarga del resto.","lecciones":[{"titulo":"Los datos clave","texto":"Empresa, contacto, cargo, teléfono, correo, sector, subsector, ciudad y valor aproximado de la factura. Si además adjuntas la factura, el diagnóstico empieza el mismo día.\n\nCada dato tiene una función. El sector y el subsector permiten estimar el perfil de consumo horario; la ciudad define la irradiación esperada y el operador de red; el horario de operación indica qué parte del consumo coincide con las horas de sol; y la propiedad de la sede determina quién debe aprobar la obra. Cuando falta uno de estos datos, el equipo debe hacer una llamada adicional antes de poder avanzar."},{"titulo":"Hablar con quien decide","texto":"Gerente general, financiero o de planta. Si tu contacto no decide, pídele que te presente a quien sí lo hace.\n\nEn empresas medianas, la decisión de una inversión de este tamaño suele involucrar al gerente general y al financiero; en empresas más grandes, también a operaciones, mantenimiento y, a veces, a la junta directiva. Identificar al decisor no significa saltarse a tu contacto: significa pedirle que te ayude a llegar a quien aprueba, idealmente con una introducción conjunta."},{"titulo":"Cómo pedir la factura","texto":"“Para que te den una cifra real de ahorro necesitan una factura reciente. ¿Me la compartes y se la hago llegar?” Así la factura es un beneficio para el cliente, no un trámite.\n\nLa factura permite calcular el consumo real, el costo unitario, la contribución y la estacionalidad. Con ella, el equipo técnico puede dimensionar un sistema preliminar y estimar el ahorro desde la primera llamada. Explicarle al cliente que la factura le da una cifra real —y no una promesa genérica— cambia la conversación: ya no es un trámite, es el inicio de su análisis."},{"titulo":"Verifica antes de enviar","texto":"Revisa que el teléfono y el correo sean correctos. Un dato falso o una empresa inexistente resta puntos y afecta tu calidad.\n\nLa calidad de tus referidos construye tu reputación dentro del programa y frente a tu red. Verificar antes de enviar —teléfono, correo, nombre exacto de la empresa, autorización del contacto— evita duplicados, llamadas incómodas y pérdida de puntos. Un buen hábito es enviar al contacto un mensaje confirmando que GEENERA lo llamará y en qué plazo."}],"ejercicio":"Toma un referido en curso o una empresa de tu red y completa los diez campos del Referido Perfecto.","pasos":["Elige una empresa de tu red que consideres candidata.","Descarga el Checklist Referido Perfecto y completa los cuatro bloques.","Ubica tu referido en el semáforo de calidad (verde, amarillo o rojo).","Si no es verde, identifica el dato que falta y cómo lo vas a conseguir esta semana.","Escribe el mensaje que enviarás a tu contacto para pedir la factura, usando uno de los guiones."],"quiz":[{"pregunta":"¿Qué dato acelera más el diagnóstico?","opciones":["El sitio web","La factura de energía","El número de empleados"],"correcta":1},{"pregunta":"Si tu contacto no decide, ¿qué haces?","opciones":["Lo envías igual","Pides que te presente al decisor","Esperas"],"correcta":1},{"pregunta":"Un dato falso…","opciones":["No pasa nada","Resta puntos y afecta tu calidad","Se corrige solo"],"correcta":1},{"pregunta":"¿Qué color del semáforo tiene un referido con decisor y datos, pero sin factura?","opciones":["Verde","Amarillo","Rojo"],"correcta":1}],"accion":"Completa los datos faltantes de tus referidos en curso."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('que-ocurre-despues-de-referir', 'Qué ocurre después de referir', 123, true, 5, 'ads', 'flash',
          5, 'Principiante', array['referidor', 'financiero', 'gremio']::text[], 'free', false, false, false, false,
          null, 'Las siete etapas del proceso comercial explicadas.', 't-perfecto', 54, '2026-06-27')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las siete etapas del proceso comercial","Qué hace GEENERA en cada una","Cuándo intervenir tú"],"contexto":"Referir es el primer paso. Entender qué pasa después te permite acompañar al cliente, responder sus dudas y saber cuándo tu oportunidad suma Puntos Sol.\n\nUn proyecto solar empresarial es una decisión de inversión de varios años, por lo que su ciclo comercial suele tomar entre uno y seis meses, según el tamaño del proyecto, la estructura de decisión del cliente y la forma de financiación. Conocer las etapas te permite gestionar expectativas —las tuyas y las del cliente— y saber en qué momento tu intervención aporta más valor.","lecciones":[{"titulo":"De registro a diagnóstico","texto":"Registro, contacto inicial e información energética. GEENERA llama al cliente, valida el perfil y pide la factura si aún no la tiene.\n\nEn la etapa de contacto, la consultora valida que la empresa cumpla el perfil: consumo, horario, sede y decisor. Luego solicita la factura y, si es necesario, información adicional como planos de cubierta o datos del medidor. En proyectos medianos y grandes, se programa una visita técnica para revisar estructura, sombras, tablero eléctrico y punto de conexión."},{"titulo":"Evaluación y propuesta","texto":"Con la factura y la ubicación se dimensiona el sistema, se calcula el ahorro y se presenta una propuesta técnica y financiera.\n\nLa propuesta incluye el tamaño del sistema en kWp, la generación estimada, el porcentaje del consumo cubierto, la inversión, el ahorro anual y los indicadores financieros: payback, TIR y flujo de caja. También describe los beneficios tributarios aplicables bajo la Ley 1715 de 2014 y sus modificaciones, y las alternativas de financiación disponibles. Cuanto más completa la información inicial, más precisa la propuesta."},{"titulo":"Negociación y cierre","texto":"El cliente evalúa, compara y decide. Aquí tu relación pesa: un mensaje tuyo puede destrabar una decisión.\n\nEn la negociación el cliente compara, consulta con su equipo financiero y, a veces, con su junta. Las dudas más frecuentes son sobre el respaldo de la garantía, el mantenimiento, el efecto en la cubierta y el tiempo de instalación. Aquí tu relación es un activo: puedes ayudar a entender qué le preocupa realmente al decisor y transmitirlo a la consultora para que lo resuelva de forma directa."}],"ejercicio":"Revisa en tu panel en qué etapa está cada oportunidad y anota una acción para la más avanzada.","pasos":["Abre tu panel de oportunidades en el Hub.","Para cada oportunidad, anota la etapa actual y cuántos días lleva en ella.","Identifica la que lleva más tiempo sin avanzar.","Escribe una pregunta que podrías hacerle al cliente para entender qué la detiene.","Comparte lo que aprendas con tu consultora antes de que termine la semana."],"quiz":[{"pregunta":"¿Qué se necesita para la propuesta?","opciones":["Solo el nombre","Factura y ubicación","Un contrato firmado"],"correcta":1},{"pregunta":"¿En qué etapa pesa más tu relación?","opciones":["Registro","Negociación","Ninguna"],"correcta":1},{"pregunta":"¿Cuánto suele tomar el ciclo de un proyecto solar empresarial?","opciones":["Una semana","Entre uno y seis meses","Más de dos años"],"correcta":1}],"accion":"Escribe a tu consultora sobre la oportunidad más avanzada."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('contenidos-que-los-empresarios-si-quieran-consumir', 'Contenidos que los empresarios sí quieran consumir', 124, true, 5, 'marca', 'micro',
          16, 'Principiante', array['gremio']::text[], 'free', false, false, true, false,
          null, 'Formatos y temas que tus afiliados abren, leen y comparten.', 't-contenido', 112, '2026-07-07')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué contenido valoran los empresarios","Formatos que se abren, se leen y se comparten","Cómo elegir temas con datos de tu audiencia","Cómo medir lo que funciona"],"contexto":"Los empresarios reciben una cantidad enorme de contenido cada semana: boletines, correos, publicaciones, invitaciones. La mayoría no se lee. El contenido que sobrevive es el que resuelve un problema concreto, en poco tiempo y con información que no encuentran en otro lugar.\n\nEl estudio anual de Edelman y LinkedIn sobre liderazgo de pensamiento ha encontrado de forma consistente que los tomadores de decisión valoran el contenido que les ayuda a entender su negocio, pero que buena parte de lo que reciben les parece de baja calidad. Para un gremio, esta es una oportunidad: con contenido útil, se convierte en una fuente de referencia para sus afiliados.","lecciones":[{"titulo":"Qué valoran","texto":"Datos de su sector y región, casos de pares, guías prácticas y alertas sobre cambios que los afectan.\n\nUn empresario abre un contenido cuando promete algo útil para su negocio: “Cómo cambió el costo de energía en las empresas de alimentos de Santander”, “Tres empresas del sector que redujeron costos con autogeneración”, “Qué significa la nueva resolución para su factura”. Los contenidos institucionales —actividades del gremio, fotos de eventos— tienen su lugar, pero no generan lectura."},{"titulo":"Formatos","texto":"Boletines breves, resúmenes de una página, carruseles con datos, videos cortos y desayunos temáticos.\n\nEl formato depende del canal y del momento. Un boletín semanal con tres noticias comentadas funciona por correo. Un carrusel con cinco datos funciona en LinkedIn. Un video de dos minutos de un experto funciona en WhatsApp. Un informe de diez páginas sirve como pieza principal de un trimestre y puede dividirse en piezas pequeñas para cada canal."},{"titulo":"Elegir temas con datos","texto":"Pregunta a tus afiliados qué les preocupa y revisa qué contenidos abrieron más.\n\nUna encuesta breve de tres preguntas (“¿qué tema le preocupa más este semestre?”) orienta la agenda editorial. Las estadísticas de apertura y clics de los boletines muestran qué temas interesan. Las preguntas que llegan al equipo del gremio son, en sí mismas, una lista de temas. Un calendario editorial trimestral basado en estos datos evita improvisar."},{"titulo":"Medir","texto":"Apertura, clics, respuestas y conversaciones generadas, no solo alcance.\n\nPara un boletín, una tasa de apertura saludable y, sobre todo, clics en los enlaces indican interés real. Para LinkedIn, los comentarios y los mensajes privados valen más que las impresiones. El indicador más valioso es cualitativo: cuántos afiliados mencionan un contenido en una conversación o lo reenvían a otros."}],"ejercicio":"Diseña un calendario editorial de un mes para tu audiencia empresarial.","pasos":["Lista las cinco preocupaciones principales de tu audiencia (pregunta si no las conoces).","Asigna un tema por semana basado en esas preocupaciones.","Elige el formato y el canal de cada pieza.","Identifica la fuente de datos o el experto para cada tema.","Define cómo medirás si cada pieza funcionó."],"quiz":[{"pregunta":"¿Qué contenido valoran más los empresarios?","opciones":["Fotos de eventos","Datos, casos y guías útiles para su negocio","Mensajes institucionales"],"correcta":1},{"pregunta":"¿Cómo elegir temas?","opciones":["Por intuición","Con datos de lo que preocupa y lo que leen los afiliados","Al azar"],"correcta":1},{"pregunta":"¿Qué indicador vale más en LinkedIn?","opciones":["Impresiones","Comentarios y mensajes privados","Número de hashtags"],"correcta":1},{"pregunta":"¿Para qué sirve un calendario editorial?","opciones":["Para evitar improvisar","Para publicar más sin criterio","No sirve"],"correcta":0}],"accion":"Pregunta a cinco afiliados o clientes qué tema les preocupa más este semestre."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-construir-una-agenda-empresarial-relevante', 'Cómo construir una agenda empresarial relevante', 125, true, 5, 'negocios', 'micro',
          18, 'Intermedio', array['gremio']::text[], 'aliado', false, false, false, false,
          null, 'Prioriza temas con datos de tus afiliados.', 't-event', 50, '2026-08-14')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué hace relevante una agenda gremial","Cómo priorizar temas con datos de los afiliados","Cómo equilibrar coyuntura y temas estructurales","Cómo comunicar y evaluar la agenda"],"contexto":"La agenda de un gremio —los temas que prioriza, investiga, comunica y lleva ante las autoridades— define su relevancia. Una agenda construida a partir de lo que realmente preocupa a los afiliados genera participación; una construida desde la intuición de la junta o el equipo genera distancia.\n\nLos gremios más relevantes combinan tres fuentes: datos de sus afiliados, lectura del entorno (economía, regulación, tendencias) y capacidad de acción. Una buena agenda no tiene veinte temas, sino tres a cinco prioridades donde el gremio puede hacer una diferencia visible.","lecciones":[{"titulo":"Escuchar a los afiliados","texto":"Encuestas, conversaciones y análisis de las consultas que llegan al gremio.\n\nUna encuesta anual de prioridades, complementada con conversaciones con empresas representativas de cada segmento, revela qué preocupa realmente. Las consultas que recibe el equipo —sobre regulación, costos, trámites— son otra fuente valiosa. Segmenta por tamaño, sector y región: las prioridades de una gran empresa no son las de una PyME."},{"titulo":"Leer el entorno","texto":"Economía, regulación, tecnología y tendencias que afectarán a los afiliados.\n\nAlgunos temas no aparecen en las encuestas porque los afiliados aún no los perciben: una nueva regulación, un cambio en el mercado energético, una tendencia tecnológica. El gremio tiene la responsabilidad de anticiparlos. Fuentes como el Banco de la República, el DANE, los ministerios y los reguladores sectoriales (como la CREG para energía) permiten identificarlos."},{"titulo":"Priorizar","texto":"Cruza importancia para los afiliados con capacidad de acción del gremio.\n\nUna matriz simple ayuda: en un eje, qué tan importante es el tema para los afiliados; en el otro, qué tanto puede hacer el gremio (informar, conectar con soluciones, incidir en regulación). Los temas con alta importancia y alta capacidad de acción son las prioridades. La competitividad energética, por ejemplo, suele estar en ese cuadrante: afecta a casi todos y el gremio puede convocar soluciones."},{"titulo":"Comunicar y evaluar","texto":"Publica la agenda, conecta cada actividad con una prioridad y rinde cuentas.\n\nUna agenda que solo conoce la junta no genera participación. Comunícala a los afiliados, conecta cada evento, informe o gestión con una de las prioridades y, al final del año, muestra los resultados. Esta rendición de cuentas fortalece la confianza y facilita la renovación de afiliaciones."}],"ejercicio":"Construye la matriz de priorización de la agenda de tu gremio u organización.","pasos":["Lista diez temas posibles a partir de encuestas, consultas y lectura del entorno.","Califica cada uno de 1 a 5 en importancia para los afiliados.","Califica cada uno de 1 a 5 en capacidad de acción del gremio.","Ubica los temas en la matriz y elige tres a cinco prioridades.","Define una actividad concreta para cada prioridad en el próximo trimestre."],"quiz":[{"pregunta":"¿Qué define la relevancia de un gremio?","opciones":["Su logo","Su agenda","Su sede"],"correcta":1},{"pregunta":"¿Cuántas prioridades debería tener una buena agenda?","opciones":["Veinte","Tres a cinco","Una"],"correcta":1},{"pregunta":"¿Con qué ejes se construye la matriz?","opciones":["Importancia para afiliados y capacidad de acción","Costo y color","Antigüedad y tamaño"],"correcta":0},{"pregunta":"¿Por qué rendir cuentas de la agenda?","opciones":["Fortalece la confianza de los afiliados","No es necesario","Para gastar más"],"correcta":0}],"accion":"Pregunta a cinco afiliados cuáles son sus tres prioridades para el próximo semestre."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-para-equipos-gremiales', 'IA para equipos gremiales', 126, true, 5, 'ia', 'curso',
          34, 'Principiante', array['gremio']::text[], 'aliado', false, true, false, false,
          null, 'Informes, boletines y análisis en una fracción del tiempo.', 't-prompts', 48, '2026-09-21')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Casos de uso de IA en un gremio o cámara","Boletines, informes y comunicaciones en menos tiempo","Análisis de encuestas y datos de afiliados","Atención a afiliados y preguntas frecuentes","Cómo implementar la IA en un equipo pequeño"],"contexto":"Los equipos gremiales suelen ser pequeños y atender muchas tareas: comunicaciones, eventos, estudios, relacionamiento institucional y atención a afiliados. La IA puede multiplicar la capacidad de ese equipo sin aumentar su tamaño, especialmente en las tareas de redacción, análisis y organización de información.\n\nAdemás, un gremio que usa bien la IA puede ayudar a sus afiliados a adoptarla, lo que se convierte en un servicio de valor. Este curso cubre los usos internos más rentables y cómo implementarlos con un equipo que no tiene perfil técnico.","lecciones":[{"titulo":"Comunicaciones","texto":"Boletines, notas de prensa, publicaciones y correos a afiliados.\n\nCon una buena instrucción y ejemplos de comunicaciones anteriores, la IA puede producir el primer borrador de un boletín semanal a partir de las noticias del sector, una nota de prensa a partir de un comunicado interno o publicaciones para redes a partir de un evento. El equipo revisa, ajusta el tono institucional y verifica los datos."},{"titulo":"Informes y estudios","texto":"Estructura, redacción y síntesis de informes sectoriales.\n\nLa IA puede proponer la estructura de un informe, resumir fuentes oficiales (DANE, Banco de la República, superintendencias), redactar secciones a partir de datos y generar resúmenes ejecutivos. El análisis y las conclusiones siguen siendo responsabilidad del equipo, pero el tiempo de producción se reduce de forma importante."},{"titulo":"Encuestas y datos","texto":"Análisis de respuestas abiertas, tendencias y segmentación de afiliados.\n\nUna de las tareas más lentas es leer cientos de respuestas abiertas de una encuesta. La IA puede agruparlas por tema, identificar las preocupaciones más frecuentes y extraer frases representativas. También puede analizar tablas de datos de afiliados para encontrar patrones por sector, tamaño o región."},{"titulo":"Atención a afiliados","texto":"Respuestas a preguntas frecuentes con base en los documentos del gremio.\n\nUn asistente configurado con los estatutos, los servicios, el calendario de eventos y las preguntas frecuentes puede ayudar al equipo a responder más rápido y de forma consistente. Si se ofrece directamente a los afiliados, debe estar claramente identificado como asistente automático y tener una vía para hablar con una persona."},{"titulo":"Implementación en el equipo","texto":"Empieza con dos casos de uso, define reglas y comparte lo que funciona.\n\nNo intentes transformar todo a la vez. Elige dos tareas repetitivas, define qué herramienta se usará y qué información no puede compartirse, crea una librería de prompts compartida y reserva 30 minutos mensuales para que el equipo comparta aprendizajes. La adopción depende más de la práctica que de la tecnología."}],"ejercicio":"Identifica los dos casos de uso de IA más rentables para tu equipo gremial y crea su instrucción base.","pasos":["Lista las diez tareas que más tiempo consumen en tu equipo.","Marca las que involucran redactar, resumir o analizar información.","Elige dos y escribe la instrucción base para cada una.","Prueba ambas con casos reales y ajusta.","Comparte las instrucciones con el equipo en una librería común."],"quiz":[{"pregunta":"¿Por qué la IA es valiosa para un gremio?","opciones":["Multiplica la capacidad de equipos pequeños","Reemplaza a los afiliados","No lo es"],"correcta":0},{"pregunta":"¿Qué tarea lenta puede acelerar la IA en encuestas?","opciones":["Agrupar respuestas abiertas por tema","Enviar la encuesta","Diseñar el logo"],"correcta":0},{"pregunta":"¿Qué debe tener un asistente ofrecido a afiliados?","opciones":["Identificación como automático y vía hacia una persona","Ninguna aclaración","Acceso a datos privados"],"correcta":0},{"pregunta":"¿Cómo conviene empezar la implementación?","opciones":["Con todo a la vez","Con dos casos de uso y reglas claras","Sin reglas"],"correcta":1}],"accion":"Crea una librería de prompts compartida para tu equipo con las dos primeras instrucciones."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-crear-un-evento-empresarial-de-alto-valor', 'Cómo crear un evento empresarial de alto valor', 127, true, 5, 'negocios', 'curso',
          38, 'Intermedio', array['gremio']::text[], 'aliado', true, false, false, false,
          null, 'Del objetivo a la experiencia: diseña eventos que la gente recomienda.', 't-event', 46, '2026-01-01')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Diseñar un evento desde el cambio que quieres provocar","Definir la audiencia correcta","Diseñar la experiencia completa: antes, durante y después","Elegir formato, contenido y aliados","Medir el impacto"],"contexto":"Un evento empresarial de alto valor no se mide por el número de asistentes, sino por lo que cambia en ellos: qué aprenden, a quién conocen y qué hacen al día siguiente. Los eventos que la gente recomienda tienen algo en común: fueron diseñados a partir de la audiencia, no del programa.\n\nEste curso aplica principios del diseño de experiencias al formato de eventos empresariales, siguiendo la lógica del Event Canvas, una metodología desarrollada por profesionales de la industria de eventos para diseñar a partir del cambio de comportamiento que se busca en los asistentes. Funciona igual para un desayuno de 20 gerentes que para un foro de 300 personas.","lecciones":[{"titulo":"Empieza por el cambio","texto":"¿Qué deben saber, sentir y hacer los asistentes al salir?\n\nAntes de pensar en panelistas o en el lugar, escribe en una frase el cambio que quieres lograr. Por ejemplo: “Que los gerentes de empresas manufactureras salgan entendiendo cómo reducir su costo de energía y con una cita para un diagnóstico”. Ese objetivo guía cada decisión posterior: a quién invitar, qué contenido incluir y cómo medir el éxito."},{"titulo":"La audiencia correcta","texto":"Define perfil, preocupaciones y qué los haría cancelar su agenda para venir.\n\nUn evento para “empresarios” no es para nadie. Define cargo, sector, tamaño de empresa y región. Luego pregúntate qué les preocupa hoy y qué contenido o qué personas los harían cambiar su agenda. Una audiencia homogénea genera mejores conversaciones: un gerente valora conocer a sus pares y escuchar casos de empresas parecidas a la suya."},{"titulo":"La experiencia completa","texto":"El evento empieza con la invitación y termina con el seguimiento.\n\nAntes: una invitación personalizada, una pregunta previa para preparar la conversación y la lista de asistentes. Durante: recibimiento por nombre, conexiones sugeridas, contenido que no encuentran en internet y tiempo real para conversar. Después: un resumen con datos, una herramienta práctica y una invitación al siguiente paso. Cada momento es una oportunidad de generar valor."},{"titulo":"Formato, contenido y aliados","texto":"Menos presentaciones, más conversación; contenido local y aliados que aporten soluciones.\n\nUna regla útil: máximo 40% del tiempo en presentaciones, el resto en conversación, preguntas y networking. Prioriza datos del sector y casos locales. Los paneles funcionan mejor cuando hay puntos de vista distintos y un moderador que hace preguntas difíciles. Los aliados —como GEENERA en temas de energía— pueden aportar contenido técnico, diagnósticos para los asistentes y recursos, siempre que el evento no se convierta en una venta."},{"titulo":"Medir el impacto","texto":"Asistencia efectiva, calidad de la audiencia, recomendación y acciones posteriores.\n\nDefine indicadores desde el diseño: porcentaje de confirmados que asistieron, porcentaje de asistentes con el perfil objetivo, recomendación medida con la pregunta del Net Promoter Score (de 0 a 10, ¿qué tan probable es que recomiende este evento?), reuniones o diagnósticos agendados en los 30 días siguientes y piezas de contenido derivadas. Presenta estos resultados a tu junta y a los aliados."}],"ejercicio":"Diseña un evento empresarial con el Event Canvas en una página.","pasos":["Escribe el cambio que quieres provocar en los asistentes.","Define la audiencia con cargo, sector, tamaño y región.","Diseña los momentos antes, durante y después.","Elige formato, contenido y aliados.","Define cinco indicadores de éxito con su meta."],"quiz":[{"pregunta":"¿Con qué debe empezar el diseño de un evento?","opciones":["Con el lugar","Con el cambio que se quiere provocar en los asistentes","Con el catering"],"correcta":1},{"pregunta":"¿Qué proporción máxima del tiempo conviene dedicar a presentaciones?","opciones":["Alrededor del 40%","100%","90%"],"correcta":0},{"pregunta":"¿Cuándo empieza la experiencia del evento?","opciones":["Al llegar al lugar","Con la invitación","Con el primer panel"],"correcta":1},{"pregunta":"¿Qué mide el Net Promoter Score?","opciones":["La probabilidad de recomendar","El costo","El número de sillas"],"correcta":0}],"accion":"Escribe en una frase el cambio que quieres provocar en tu próximo evento."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('eventos-que-generan-comunidad', 'Eventos que generan comunidad', 128, true, 5, 'negocios', 'micro',
          15, 'Intermedio', array['gremio']::text[], 'aliado', false, false, false, false,
          null, 'Lo que ocurre antes y después del evento importa más.', 't-event', 44, '2026-02-08')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Diferencia entre un evento y una comunidad","Lo que ocurre antes y después importa más","Rituales y continuidad","Cómo medir la comunidad"],"contexto":"Un evento reúne personas durante unas horas; una comunidad las mantiene conectadas en el tiempo. Los gremios y organizaciones que logran convertir sus eventos en comunidades obtienen afiliados más comprometidos, conversaciones más profundas y oportunidades de negocio entre sus miembros.\n\nLa clave está en lo que ocurre fuera del evento: cómo se prepara a los asistentes, cómo se facilitan las conexiones y cómo se mantiene el contacto entre una edición y la siguiente.","lecciones":[{"titulo":"Evento vs. comunidad","texto":"El evento es un momento; la comunidad es una relación continua con propósito compartido.\n\nUna comunidad tiene miembros que se reconocen entre sí, un propósito común, encuentros recurrentes y canales de conversación entre encuentros. Un ciclo de desayunos trimestrales con el mismo grupo de gerentes, con un grupo de conversación entre ediciones, puede generar más confianza y negocios que un gran foro anual."},{"titulo":"Antes y después","texto":"Prepara a los asistentes y mantén viva la conversación.\n\nAntes del evento, comparte la lista de asistentes, una pregunta para reflexionar y sugerencias de con quién conversar. Después, envía un resumen con los aprendizajes, conecta a quienes mostraron intereses comunes y propón la siguiente actividad. Estas acciones cuestan poco y multiplican el valor percibido."},{"titulo":"Rituales y continuidad","texto":"Formatos recurrentes, reconocimientos y espacios propios de la comunidad.\n\nLos rituales dan identidad: un desayuno el primer martes de cada trimestre, una sección donde un miembro comparte un caso, un reconocimiento anual. La continuidad permite que las personas construyan relaciones. Un grupo de conversación moderado entre encuentros mantiene el vínculo, siempre que tenga reglas claras y contenido útil."},{"titulo":"Medir la comunidad","texto":"Recurrencia de asistentes, conexiones entre miembros y acciones conjuntas.\n\nLos indicadores de comunidad son distintos a los de un evento: porcentaje de asistentes que repiten, número de conexiones o reuniones entre miembros, participación en el canal de conversación e iniciativas que nacen de la comunidad. Si los miembros empiezan a proponer temas y actividades, la comunidad está viva."}],"ejercicio":"Diseña el ciclo de un año para convertir un evento en comunidad.","pasos":["Elige un evento recurrente o diseña uno nuevo.","Define la audiencia y el propósito compartido de la comunidad.","Diseña cuatro encuentros en el año con un formato ritual.","Define las acciones antes y después de cada encuentro.","Elige tres indicadores de comunidad."],"quiz":[{"pregunta":"¿Qué diferencia una comunidad de un evento?","opciones":["La comunidad es una relación continua con propósito","El evento es más largo","No hay diferencia"],"correcta":0},{"pregunta":"¿Qué multiplica el valor percibido de un evento?","opciones":["Acciones antes y después","Más diapositivas","Un lugar más caro"],"correcta":0},{"pregunta":"¿Qué indicador mide comunidad?","opciones":["Asistentes que repiten","Costo del catering","Número de sillas"],"correcta":0},{"pregunta":"¿Qué indica que la comunidad está viva?","opciones":["Que los miembros proponen temas y actividades","Que nadie responde","Que solo habla el organizador"],"correcta":0}],"accion":"Envía a los asistentes de tu último evento un resumen con aprendizajes y la siguiente actividad."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-aumentar-participacion-de-afiliados', 'Cómo aumentar participación de afiliados', 129, true, 5, 'negocios', 'micro',
          16, 'Intermedio', array['gremio']::text[], 'aliado', false, false, true, false,
          null, 'Tácticas para pasar de base de datos a comunidad activa.', 't-event', 102, '2026-03-15')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Por qué los afiliados dejan de participar","Segmentar a los afiliados por necesidades","Tácticas para activar a los inactivos","Cómo medir y sostener la participación"],"contexto":"Muchos gremios tienen una base de afiliados amplia y una participación concentrada en pocos. El resto paga su cuota, recibe boletines y rara vez asiste a algo. Con el tiempo, esa baja participación se convierte en desafiliación.\n\nAumentar la participación no depende de hacer más eventos, sino de ofrecer valor percibido a cada segmento de afiliados. Una PyME busca soluciones prácticas; una gran empresa, incidencia y relaciones; un nuevo afiliado, orientación y conexiones.","lecciones":[{"titulo":"Por qué no participan","texto":"Falta de tiempo, contenidos poco relevantes, desconocimiento de los servicios o sensación de que el gremio es para otros.\n\nPregunta directamente a los afiliados inactivos: una llamada breve revela más que cualquier encuesta. Las razones más comunes son que los horarios no les sirven, que los temas no son relevantes para su tamaño o sector, que no conocen todos los servicios o que sienten que las actividades son para las grandes empresas."},{"titulo":"Segmenta","texto":"Agrupa a los afiliados por tamaño, sector, antigüedad y nivel de participación.\n\nCon cuatro o cinco segmentos puedes diseñar propuestas específicas: PyMEs que buscan soluciones prácticas, grandes empresas interesadas en incidencia, nuevos afiliados que necesitan orientación, afiliados de sectores específicos con preocupaciones comunes. Cada segmento necesita un mensaje y una oferta distinta."},{"titulo":"Activa","texto":"Bienvenida estructurada, contacto personal, servicios concretos y formatos flexibles.\n\nUn programa de bienvenida para nuevos afiliados (llamada, reunión de orientación, conexión con otros miembros) reduce la desafiliación temprana. Un contacto personal con los inactivos muestra interés genuino. Servicios concretos —diagnósticos energéticos con aliados, asesoría en trámites, información sectorial— generan valor tangible. Formatos virtuales o breves facilitan la participación de quienes tienen poco tiempo."},{"titulo":"Mide y sostén","texto":"Porcentaje de afiliados activos, uso de servicios, satisfacción y renovación.\n\nDefine qué significa “afiliado activo” (por ejemplo, haber participado en al menos una actividad o usado un servicio en el trimestre) y mide su evolución. Complementa con satisfacción y tasa de renovación. Revisa los resultados por segmento: la participación global puede ocultar segmentos completamente desconectados."}],"ejercicio":"Diseña un plan de activación para un segmento de afiliados inactivos.","pasos":["Define qué significa “afiliado activo” en tu organización.","Identifica el segmento con menor participación.","Llama a cinco afiliados de ese segmento y pregunta qué valorarían.","Diseña una oferta específica para ese segmento.","Define cómo medirás si la participación aumentó en tres meses."],"quiz":[{"pregunta":"¿De qué depende aumentar la participación?","opciones":["De hacer más eventos","De ofrecer valor percibido a cada segmento","De subir la cuota"],"correcta":1},{"pregunta":"¿Cuál es una forma efectiva de entender a los inactivos?","opciones":["Una llamada breve","Ignorarlos","Enviar más boletines"],"correcta":0},{"pregunta":"¿Qué reduce la desafiliación temprana?","opciones":["Un programa de bienvenida","Cobrar más","No contactarlos"],"correcta":0},{"pregunta":"¿Por qué medir por segmento?","opciones":["Porque el promedio puede ocultar segmentos desconectados","No es necesario","Para tener más tablas"],"correcta":0}],"accion":"Llama esta semana a cinco afiliados inactivos y pregunta qué valorarían del gremio."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-medir-el-impacto-de-un-evento', 'Cómo medir el impacto de un evento', 130, true, 5, 'negocios', 'flash',
          7, 'Intermedio', array['gremio']::text[], 'aliado', false, false, false, false,
          null, 'Indicadores simples que convencen a tu junta.', 't-event', 40, '2026-04-22')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Indicadores simples que convencen a una junta","Cómo recolectar los datos","Cómo presentar los resultados"],"contexto":"Una junta directiva o un patrocinador no se convencen con fotos ni con el número de asistentes: quieren saber qué cambió gracias al evento. Medir el impacto permite justificar la inversión, mejorar la siguiente edición y renovar aliados.\n\nCinco indicadores simples, definidos antes del evento, son suficientes para contar una historia de impacto.","lecciones":[{"titulo":"Los cinco indicadores","texto":"Asistencia efectiva, calidad de la audiencia, recomendación, acciones posteriores y contenido derivado.\n\nAsistencia efectiva: asistentes ÷ confirmados (meta sugerida: más de 70%). Calidad: porcentaje de asistentes con el perfil objetivo. Recomendación: pregunta NPS al cierre. Acciones posteriores: reuniones, diagnósticos o compromisos en los 30 días siguientes. Contenido derivado: piezas producidas a partir del evento."},{"titulo":"Recolectar los datos","texto":"Registro con perfil, encuesta breve al cierre y seguimiento a 30 días.\n\nEl formulario de inscripción debe capturar cargo, empresa y sector para medir la calidad de la audiencia. Una encuesta de tres preguntas al cierre (recomendación, aprendizaje principal, siguiente paso deseado) captura la percepción. Un seguimiento a los 30 días con los aliados permite contar las acciones generadas."},{"titulo":"Presentar los resultados","texto":"Una página con los cinco indicadores, una cita de un asistente y una recomendación para la próxima edición.\n\nLa junta necesita ver resultados frente a metas, no solo cifras. Acompaña los números con una cita representativa y con una o dos mejoras concretas para la siguiente edición. Este formato muestra profesionalismo y facilita la renovación de patrocinios."}],"ejercicio":"Define los cinco indicadores, con su meta, para tu próximo evento.","pasos":["Escribe los cinco indicadores.","Define una meta para cada uno.","Ajusta el formulario de inscripción para capturar el perfil.","Prepara la encuesta de tres preguntas para el cierre."],"quiz":[{"pregunta":"¿Qué convence a una junta?","opciones":["Fotos","Qué cambió gracias al evento","El menú"],"correcta":1},{"pregunta":"¿Cómo se calcula la asistencia efectiva?","opciones":["Asistentes ÷ confirmados","Sillas ÷ asistentes","Costo ÷ asistentes"],"correcta":0},{"pregunta":"¿Cuándo se miden las acciones posteriores?","opciones":["En los 30 días siguientes","Antes del evento","Nunca"],"correcta":0}],"accion":"Agrega una encuesta de tres preguntas al cierre de tu próximo evento."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-convertir-datos-en-contenido-gremial', 'Cómo convertir datos en contenido gremial', 131, true, 5, 'marca', 'micro',
          14, 'Intermedio', array['gremio']::text[], 'aliado', false, false, false, false,
          null, 'Encuestas y cifras que se vuelven titulares.', 't-contenido', 38, '2026-05-02')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Por qué los datos propios son el mejor contenido","Cómo diseñar una encuesta que produzca titulares","Cómo convertir cifras en historias","Cómo distribuir y reutilizar el contenido"],"contexto":"Un gremio tiene algo que ningún medio ni consultora tiene: acceso directo a sus afiliados. Con una encuesta bien diseñada, puede producir datos únicos sobre su sector y su región, que se convierten en titulares, informes, conversaciones con el Gobierno y eventos.\n\nLos datos propios posicionan al gremio como fuente de referencia: los medios lo citan, las autoridades lo consultan y los afiliados lo valoran. La clave está en diseñar la recolección pensando desde el inicio en las historias que se quieren contar.","lecciones":[{"titulo":"Por qué datos propios","texto":"Son únicos, relevantes para la audiencia y generan autoridad.\n\nUna cifra como “el 64% de las empresas manufactureras de la región vio aumentar su factura de energía más del 20% en el último año” no existe en ninguna otra parte. Es noticia para los medios regionales, insumo para la agenda gremial y punto de partida para soluciones con aliados. Las estadísticas nacionales son útiles como contexto, pero no generan la misma conversación."},{"titulo":"Diseñar la encuesta","texto":"Pocas preguntas, cerradas en su mayoría, pensadas desde el titular que quieres poder escribir.\n\nEmpieza por las preguntas que te gustaría responder y luego diseña las preguntas de la encuesta. Usa entre cinco y diez preguntas, mayoritariamente cerradas, con una o dos abiertas para citas. Incluye variables de segmentación (sector, tamaño, ciudad) para comparar. Herramientas gratuitas como Google Forms o Microsoft Forms son suficientes."},{"titulo":"De la cifra a la historia","texto":"Un hallazgo, su contexto, una comparación y una implicación.\n\nUna cifra sola no comunica. Una historia sí: “Siete de cada diez empresas de alimentos de la región consideran la energía uno de sus tres principales costos; en manufactura, la proporción es de seis de cada diez. Las empresas que ya autogeneran reportan mayor previsibilidad de costos”. Hallazgo, comparación e implicación en tres frases."},{"titulo":"Distribuir y reutilizar","texto":"Un informe principal, varias piezas derivadas y un evento de presentación.\n\nCon una sola encuesta puedes producir un informe, una nota de prensa, un carrusel de LinkedIn, un boletín, un video corto con el presidente del gremio y un desayuno de presentación de resultados con aliados que aporten soluciones. Planea las piezas desde el inicio para maximizar el valor del esfuerzo."}],"ejercicio":"Diseña una encuesta de cinco a ocho preguntas pensada desde los titulares que quieres escribir.","pasos":["Escribe tres titulares que te gustaría poder publicar.","Diseña las preguntas necesarias para obtener esos datos.","Agrega preguntas de segmentación (sector, tamaño, ciudad).","Define el canal de distribución y la fecha de cierre.","Lista las piezas de contenido que producirás con los resultados."],"quiz":[{"pregunta":"¿Por qué son valiosos los datos propios de un gremio?","opciones":["Son únicos, relevantes y generan autoridad","Son más baratos que nada","No lo son"],"correcta":0},{"pregunta":"¿Desde dónde conviene diseñar la encuesta?","opciones":["Desde los titulares que se quieren escribir","Desde el logo","Al azar"],"correcta":0},{"pregunta":"¿Qué convierte una cifra en historia?","opciones":["Hallazgo, contexto, comparación e implicación","Ponerla en negrilla","Repetirla"],"correcta":0},{"pregunta":"¿Cuántas piezas pueden salir de una encuesta?","opciones":["Solo una","Varias: informe, nota, carrusel, boletín y evento","Ninguna"],"correcta":1}],"accion":"Escribe los tres titulares que te gustaría publicar con datos de tus afiliados."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-para-construir-informes-y-benchmarks', 'IA para construir informes y benchmarks', 132, true, 5, 'ia', 'micro',
          18, 'Intermedio', array['gremio']::text[], 'aliado', false, true, false, false,
          null, 'Estructura, redacta y visualiza informes sectoriales con IA.', 't-contenido', 36, '2026-06-09')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Estructurar un informe sectorial con IA","Reunir y sintetizar fuentes confiables","Construir un benchmark comparativo","Visualizar y comunicar los resultados"],"contexto":"Los informes sectoriales y los benchmarks son de los productos más valorados por los afiliados de un gremio y por los clientes de un consultor: muestran cómo está un sector, cómo se compara una empresa con sus pares y qué tendencias vienen. También son de los más costosos de producir.\n\nLa IA puede acelerar cada etapa: definir la estructura, sintetizar fuentes, redactar secciones, sugerir visualizaciones y producir resúmenes. Lo que no puede hacer es garantizar la veracidad de los datos ni la pertinencia de las conclusiones: eso sigue siendo trabajo del equipo.","lecciones":[{"titulo":"Estructura","texto":"Define la pregunta del informe, la audiencia y las secciones antes de escribir.\n\nPide a la IA: “Propón la estructura de un informe sobre [tema] para [audiencia]. Incluye preguntas que debe responder cada sección, datos necesarios y posibles fuentes en Colombia”. Ajusta la propuesta con tu conocimiento del sector. Una buena estructura evita reescribir el informe dos veces."},{"titulo":"Fuentes","texto":"Prioriza fuentes oficiales y verifica cada cifra.\n\nEn Colombia, fuentes como el DANE, el Banco de la República, las superintendencias, XM y la UPME (para energía), los ministerios y los gremios sectoriales ofrecen datos confiables. Sube los documentos y pide síntesis con cita de página. Nunca uses una cifra generada por la IA sin fuente verificable."},{"titulo":"Benchmark","texto":"Compara indicadores clave entre empresas, sectores o regiones con criterios homogéneos.\n\nUn benchmark útil define pocos indicadores comparables (por ejemplo, costo de energía por unidad producida, margen, crecimiento) y los presenta en una tabla con promedios, rangos y la posición de cada empresa. La IA puede ayudarte a calcular indicadores a partir de tablas, detectar valores atípicos y redactar la interpretación."},{"titulo":"Visualizar y comunicar","texto":"Una idea por gráfico, un titular que diga la conclusión y un resumen ejecutivo de una página.\n\nPide a la IA sugerencias de visualización para cada hallazgo y titulares que expresen la conclusión (“El costo de energía creció más rápido que las ventas en 7 de cada 10 empresas”) en lugar de describir el gráfico. Termina con un resumen ejecutivo de cinco puntos y recomendaciones concretas para la audiencia."}],"ejercicio":"Estructura con IA un informe o benchmark breve sobre un tema relevante para tu audiencia.","pasos":["Define la pregunta del informe y su audiencia.","Pide a la IA una propuesta de estructura y ajústala.","Reúne tres fuentes oficiales y pide síntesis con cita de página.","Construye una tabla comparativa con tres indicadores.","Redacta un resumen ejecutivo de cinco puntos."],"quiz":[{"pregunta":"¿Qué debe definirse antes de escribir un informe?","opciones":["La pregunta, la audiencia y las secciones","El color de la portada","Nada"],"correcta":0},{"pregunta":"¿Qué hacer con una cifra generada por la IA sin fuente?","opciones":["Usarla","No usarla hasta verificarla","Redondearla"],"correcta":1},{"pregunta":"¿Qué caracteriza a un buen benchmark?","opciones":["Pocos indicadores comparables con criterios homogéneos","Cientos de indicadores","Opiniones sin datos"],"correcta":0},{"pregunta":"¿Qué debe decir el titular de un gráfico?","opciones":["La conclusión","Solo “Gráfico 1”","Nada"],"correcta":0}],"accion":"Define la pregunta y la estructura del próximo informe que produzcas."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('competitividad-energetica-empresarial', 'Competitividad energética empresarial', 133, true, 5, 'energia', 'micro',
          16, 'Principiante', array['gremio']::text[], 'aliado', false, false, false, false,
          null, 'Cómo el costo de energía afecta la competitividad de un sector.', 't-event', 34, '2026-07-16')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Cómo el costo de energía afecta la competitividad de un sector","Qué datos usar para dimensionar el problema en tus afiliados","Qué palancas tienen las empresas para gestionarlo","Cómo un gremio puede liderar la conversación"],"contexto":"La energía es un insumo transversal: afecta el costo de producir, almacenar, transportar y vender. Cuando su precio sube más rápido que el de los productos, los márgenes se comprimen y las empresas pierden competitividad frente a competidores de otros países o regiones con energía más barata o más estable.\n\nPara un gremio, la competitividad energética es un tema que une a los afiliados: todos pagan energía, pocos sienten que la controlan y casi ninguno tiene tiempo de analizar alternativas. Liderar esa conversación con datos y soluciones concretas posiciona al gremio como un actor que defiende la rentabilidad de sus empresas, no solo sus intereses regulatorios.","lecciones":[{"titulo":"Energía y competitividad","texto":"El peso de la energía en la estructura de costos determina cuánto afecta su precio al margen.\n\nEn sectores intensivos —metalmecánica, plásticos, alimentos procesados, cadena de frío, textiles— la energía puede superar el 10% de los costos operativos. Un aumento del 20% en la tarifa puede borrar buena parte del margen neto de una empresa que no puede trasladar ese costo a sus precios. Por eso, la energía es un tema de supervivencia en algunos sectores y de eficiencia en otros."},{"titulo":"Datos para dimensionar","texto":"Encuesta a tus afiliados: factura mensual, peso en costos, variación del último año y acciones tomadas.\n\nUna encuesta breve de cinco preguntas permite construir un indicador sectorial: costo promedio por kWh, participación de la energía en costos y porcentaje de empresas que han evaluado autogeneración. Complementa con fuentes públicas como los reportes de XM sobre precios del mercado y los informes de la Superintendencia de Servicios Públicos. Un dato propio, del sector y de la región, vale más que cualquier estadística nacional."},{"titulo":"Palancas de gestión","texto":"Eficiencia energética, autogeneración solar, gestión de la demanda y, para grandes consumidores, contratos en el mercado no regulado.\n\nLa eficiencia (iluminación LED, motores de alta eficiencia, variadores de velocidad, corrección del factor de potencia) reduce el consumo. La autogeneración solar reduce la energía comprada y fija parte del costo durante décadas. La gestión de la demanda desplaza consumos a horas más convenientes. Las empresas que superan los umbrales de usuario no regulado pueden negociar contratos de suministro. Las más competitivas combinan varias palancas."},{"titulo":"El rol del gremio","texto":"Convocar, informar y facilitar soluciones colectivas que una empresa sola no lograría.\n\nUn gremio puede organizar jornadas de diagnóstico energético, negociar condiciones para sus afiliados con aliados técnicos y financieros, publicar un informe sectorial de competitividad energética y llevar datos concretos a las conversaciones con el regulador. Este tipo de iniciativas generan valor visible para los afiliados y aumentan su participación."}],"ejercicio":"Diseña una encuesta de cinco preguntas para medir la competitividad energética de tus afiliados.","pasos":["Define el objetivo de la encuesta en una frase.","Escribe cinco preguntas: factura mensual, peso en costos, variación anual, acciones tomadas e interés en soluciones.","Elige el canal de envío y la fecha límite.","Define cómo presentarás los resultados (informe, evento o boletín).","Identifica un aliado técnico, como GEENERA, que pueda aportar soluciones en la presentación de resultados."],"quiz":[{"pregunta":"¿En qué sectores pesa más la energía?","opciones":["Metalmecánica, plásticos, alimentos y frío","Consultoría","Software"],"correcta":0},{"pregunta":"¿Qué dato tiene más valor para un gremio?","opciones":["Una estadística global","Un dato propio del sector y la región","Ninguno"],"correcta":1},{"pregunta":"¿Qué palanca fija parte del costo de energía durante décadas?","opciones":["Autogeneración solar","Cambiar de proveedor de agua","Reducir personal"],"correcta":0},{"pregunta":"¿Qué puede hacer un gremio que una empresa sola no logra?","opciones":["Soluciones colectivas y datos sectoriales","Nada","Fijar la tarifa"],"correcta":0}],"accion":"Envía a tus afiliados una encuesta breve sobre su costo de energía."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-construir-alianzas-empresa-gremio', 'Cómo construir alianzas empresa–gremio', 134, true, 5, 'relaciones', 'micro',
          15, 'Intermedio', array['gremio']::text[], 'aliado', false, false, false, false,
          null, 'Alianzas con propósito que benefician a los afiliados.', 't-event', 32, '2026-08-23')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué hace que una alianza empresa–gremio funcione","Cómo identificar aliados con propósito compartido","Cómo estructurar una alianza con beneficios claros","Cómo medir y renovar la alianza"],"contexto":"Los gremios y las empresas privadas pueden crear juntos valor que ninguno lograría solo: el gremio aporta convocatoria, confianza y conocimiento del sector; la empresa aporta soluciones, recursos y experiencia técnica. Bien estructurada, una alianza beneficia sobre todo a los afiliados.\n\nPero muchas alianzas fracasan porque se reducen a un patrocinio de logo en un evento o porque los afiliados las perciben como una venta disfrazada. Las alianzas que funcionan tienen un propósito compartido, beneficios concretos para cada parte, reglas claras de comunicación y una medición que permite renovarlas o terminarlas con criterio.","lecciones":[{"titulo":"Propósito compartido","texto":"La alianza debe resolver un problema real de los afiliados, no solo dar visibilidad a la empresa.\n\nEmpieza por la pregunta: ¿qué necesidad de los afiliados podemos atender juntos? Por ejemplo, reducir el costo de energía de las empresas del sector, acceder a financiación para modernización o cumplir exigencias de sostenibilidad. Si el propósito es claro, la alianza se comunica sola y los afiliados la valoran como un servicio del gremio."},{"titulo":"Elegir al aliado","texto":"Reputación, capacidad técnica, alineación de valores y disposición a aportar más que dinero.\n\nUn buen aliado privado tiene trayectoria verificable, capacidad de atender a muchos afiliados, respeto por la relación del gremio con sus empresas y disposición a aportar conocimiento (diagnósticos, contenidos, casos) y no solo patrocinio. Revisa referencias con otros gremios o clientes antes de formalizar."},{"titulo":"Estructurar la alianza","texto":"Objetivos, aportes de cada parte, beneficios para afiliados, reglas de comunicación y duración.\n\nUn acuerdo de una o dos páginas basta para empezar: qué se busca, qué aporta el gremio (convocatoria, espacios, comunicación), qué aporta la empresa (diagnósticos sin costo, contenidos, condiciones preferenciales), cómo se protege la información de los afiliados, quién habla en nombre de quién y por cuánto tiempo. En Aliados del Sol, por ejemplo, los gremios aliados convocan y GEENERA aporta diagnóstico técnico y acompañamiento, mientras el gremio sigue el avance desde el Hub."},{"titulo":"Medir y renovar","texto":"Participación de afiliados, satisfacción, resultados concretos y valor para cada parte.\n\nDefine desde el inicio tres a cinco indicadores: afiliados que participaron, diagnósticos realizados, proyectos implementados, satisfacción de los afiliados y visibilidad generada. Revisa resultados cada seis meses con el aliado. Las alianzas que muestran resultados se renuevan con facilidad; las que no, se ajustan o terminan sin desgaste."}],"ejercicio":"Diseña la propuesta de una alianza empresa–gremio en una página.","pasos":["Escribe el problema de los afiliados que la alianza resolvería.","Lista los aportes del gremio y de la empresa aliada.","Define tres beneficios concretos para los afiliados.","Escribe las reglas de comunicación y protección de información.","Define tres indicadores de éxito y la fecha de la primera revisión."],"quiz":[{"pregunta":"¿Qué debe resolver una alianza empresa–gremio?","opciones":["Un problema real de los afiliados","Solo la visibilidad de la empresa","Nada en particular"],"correcta":0},{"pregunta":"¿Por qué fracasan muchas alianzas?","opciones":["Porque se reducen a un patrocinio de logo","Porque son muy claras","Porque miden demasiado"],"correcta":0},{"pregunta":"¿Qué debe incluir el acuerdo?","opciones":["Objetivos, aportes, beneficios, reglas y duración","Solo el logo","Solo el precio"],"correcta":0},{"pregunta":"¿Cada cuánto conviene revisar resultados?","opciones":["Cada seis meses","Nunca","Cada diez años"],"correcta":0}],"accion":"Identifica una necesidad de tus afiliados que podría atenderse con una alianza y conversa con un posible aliado."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('tendencias-empresariales-2027', 'Tendencias empresariales 2027', 135, true, 0, 'negocios', 'masterclass',
          60, 'Principiante', array['gremio', 'financiero', 'referidor']::text[], 'aliado', false, true, false, false,
          null, 'Lo que viene para las empresas colombianas el próximo año.', 't-reunion', 30, '2026-09-03')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las tendencias que marcarán a las empresas colombianas","IA y productividad","Transición energética y costos","Exigencias de sostenibilidad en las cadenas de valor","Cómo convertir tendencias en conversaciones con clientes"],"contexto":"Anticipar tendencias no es predecir el futuro, sino identificar fuerzas que ya están en marcha y que afectarán a las empresas en los próximos años. Para un ejecutivo, consultor o líder gremial, conocerlas permite preparar a sus clientes y afiliados y abrir conversaciones relevantes.\n\nEsta masterclass reúne cinco tendencias con evidencia sólida para el contexto colombiano. No son promesas: son señales que conviene seguir y que ya están influyendo en las decisiones de muchas empresas. Al final de cada una encontrarás preguntas para llevarlas a una conversación con un gerente.","lecciones":[{"titulo":"IA en la operación","texto":"La IA generativa pasa de la experimentación individual a la integración en procesos.\n\nDespués de una fase de pruebas individuales, las empresas están integrando la IA en procesos concretos: atención al cliente, análisis de información, producción de documentos y apoyo comercial. La ventaja no estará en tener la herramienta, sino en rediseñar procesos y formar a los equipos. Pregunta para el gerente: “¿Qué procesos de su empresa podrían hacerse en la mitad del tiempo con IA, y quién lo está liderando?”."},{"titulo":"Energía como variable estratégica","texto":"La volatilidad del precio y la presión sobre la oferta hacen que la energía pase de costo fijo a decisión estratégica.\n\nLa experiencia de los últimos años —alzas de tarifas, fenómeno de El Niño, debates sobre la suficiencia de la oferta en el mediano plazo— ha llevado a muchas empresas a ver la energía como un riesgo a gestionar. La autogeneración, la eficiencia y la diversificación de suministro ganan espacio en los comités. Pregunta: “¿Qué parte de su costo de energía le gustaría tener fija durante los próximos 20 años?”."},{"titulo":"Sostenibilidad exigida por la cadena","texto":"Los compradores grandes y los mercados de exportación piden datos de emisiones a sus proveedores.\n\nLas grandes empresas con metas de reducción de emisiones necesitan que sus proveedores midan y reduzcan las suyas. Regulaciones como el mecanismo de ajuste en frontera por carbono de la Unión Europea están empezando a afectar a algunos sectores exportadores. Para una PyME proveedora, medir y reducir emisiones puede convertirse en condición para seguir vendiendo. Pregunta: “¿Alguno de sus clientes le ha pedido información sobre emisiones?”."},{"titulo":"Financiación con criterios sostenibles","texto":"La banca integra criterios ambientales en sus productos y en la gestión de riesgo.\n\nCon la Taxonomía Verde de Colombia y los compromisos del sector financiero, crecen las líneas para proyectos de eficiencia y energía renovable, y los criterios ambientales empiezan a influir en el análisis de riesgo. Las empresas que puedan demostrar impacto ambiental positivo tendrán más alternativas de financiación. Pregunta: “¿Conoce las líneas de financiación para proyectos de eficiencia energética?”."},{"titulo":"Talento y nuevas formas de trabajo","texto":"Escasez de perfiles especializados, trabajo híbrido y necesidad de formación continua.\n\nLas empresas compiten por talento con habilidades digitales, técnicas y de gestión del cambio. La formación continua —como la que ofrece ADS Academy— deja de ser un beneficio y se vuelve una necesidad estratégica. Pregunta: “¿Qué habilidades necesitará su equipo en dos años que hoy no tiene?”. Convertir estas tendencias en preguntas es la forma más efectiva de posicionarte como interlocutor estratégico."}],"ejercicio":"Elige dos tendencias y prepara cómo llevarlas a la conversación con tres clientes o afiliados.","pasos":["Elige las dos tendencias más relevantes para tu audiencia.","Para cada una, escribe un dato o una señal concreta que la respalde.","Adapta la pregunta para el gerente a cada cliente o afiliado.","Define qué solución o aliado podrías conectar en cada caso.","Usa las preguntas en tus próximas tres conversaciones."],"quiz":[{"pregunta":"¿Qué es anticipar tendencias?","opciones":["Predecir el futuro con certeza","Identificar fuerzas en marcha que afectarán a las empresas","Seguir modas"],"correcta":1},{"pregunta":"¿Por qué la energía se vuelve variable estratégica?","opciones":["Por la volatilidad del precio y la presión sobre la oferta","Porque es gratis","No lo es"],"correcta":0},{"pregunta":"¿Qué piden cada vez más los grandes compradores a sus proveedores?","opciones":["Datos de emisiones","Fotos","Nada"],"correcta":0},{"pregunta":"¿Cuál es la forma más efectiva de usar una tendencia con un cliente?","opciones":["Convertirla en una pregunta","Presentar un informe largo","No mencionarla"],"correcta":0}],"accion":"Usa una pregunta de tendencia en tu próxima conversación con un gerente."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-generativa-desde-cero', 'IA generativa desde cero', 136, true, 5, 'ia', 'micro',
          16, 'Principiante', array['todos']::text[], 'free', true, false, true, false,
          null, 'Qué es, qué no es y cómo empezar a usarla hoy.', 't-prompts', 88, '2026-01-10')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es la IA generativa y cómo funciona, sin tecnicismos","Qué hace bien, qué hace mal y por qué se equivoca","Las herramientas principales y en qué se diferencian","Cómo empezar a usarla hoy en tu trabajo"],"contexto":"La IA generativa es la tecnología detrás de herramientas como ChatGPT, Claude, Gemini o Copilot: sistemas que producen texto, imágenes, tablas o código a partir de una instrucción escrita en lenguaje natural. En pocos años pasó de ser una curiosidad a una herramienta de trabajo cotidiana.\n\nLa evidencia sobre su impacto en el trabajo profesional empieza a ser sólida. Un estudio de Harvard Business School con el Boston Consulting Group (2023) encontró que consultores que usaron IA en tareas adecuadas completaron más tareas, más rápido y con mayor calidad que quienes no la usaron; pero en tareas fuera de las capacidades de la herramienta, su desempeño empeoró. La lección es clara: la IA multiplica a quien sabe cuándo y cómo usarla.","lecciones":[{"titulo":"Qué es, en una frase","texto":"Un modelo entrenado con enormes cantidades de texto que predice la continuación más probable de una instrucción.\n\nLos modelos de lenguaje aprenden patrones del lenguaje a partir de libros, artículos, sitios web y código. Cuando les escribes, generan una respuesta palabra por palabra, eligiendo la continuación más probable según lo que aprendieron y el contexto que les diste. No “buscan” la respuesta en una base de datos ni “entienden” como una persona: producen texto plausible, que la mayoría de las veces es útil y correcto, pero no siempre."},{"titulo":"Lo que hace bien","texto":"Redactar, resumir, reorganizar, traducir, generar ideas, explicar conceptos y transformar formatos.\n\nLa IA es excelente para el primer borrador de un correo, el resumen de un documento largo, la conversión de notas desordenadas en un acta, la generación de opciones para un titular o la explicación de un concepto técnico en lenguaje sencillo. En estas tareas puede ahorrarte entre la mitad y la mayor parte del tiempo, siempre que revises el resultado."},{"titulo":"Lo que hace mal","texto":"Puede inventar datos con total seguridad, no siempre conoce información reciente y no reemplaza el criterio profesional.\n\nCuando el modelo no sabe algo, puede generar una respuesta convincente pero falsa: cifras, citas, normas o nombres que no existen. A esto se le llama “alucinación”. Por eso, cualquier dato, cifra o referencia legal debe verificarse. Tampoco debe usarse para decisiones que requieren juicio ético o responsabilidad profesional sin revisión humana."},{"titulo":"Las herramientas","texto":"ChatGPT (OpenAI), Claude (Anthropic), Gemini (Google) y Copilot (Microsoft) comparten lo básico y difieren en integraciones.\n\nTodas permiten conversar, analizar documentos y generar contenido. Copilot se integra con Word, Excel, Outlook y Teams; Gemini con Gmail, Docs y Drive. Muchas empresas tienen versiones corporativas con mayores garantías de privacidad. Lo más importante no es cuál elijas, sino que aprendas a darle buenas instrucciones; esa habilidad funciona en todas."}],"ejercicio":"Usa una herramienta de IA para tres tareas reales de esta semana y evalúa el resultado de cada una.","pasos":["Elige una herramienta de IA disponible (versión gratuita o corporativa).","Escoge tres tareas: un correo, el resumen de un documento y una lluvia de ideas.","Para cada una, escribe una instrucción con contexto y el resultado que esperas.","Revisa cada respuesta: ¿qué estuvo bien?, ¿qué tuviste que corregir?, ¿qué dato debías verificar?","Calcula cuánto tiempo ahorraste en total."],"quiz":[{"pregunta":"¿Cómo genera respuestas un modelo de lenguaje?","opciones":["Buscando en una base de datos exacta","Prediciendo la continuación más probable","Copiando de internet en tiempo real"],"correcta":1},{"pregunta":"¿Qué es una alucinación?","opciones":["Una respuesta falsa presentada con seguridad","Un error de conexión","Una imagen generada"],"correcta":0},{"pregunta":"¿En qué tarea es más fuerte la IA generativa?","opciones":["Decisiones éticas sin revisión","Primeros borradores y resúmenes","Verificar normas legales sin fuente"],"correcta":1},{"pregunta":"Según el estudio de Harvard y BCG, ¿qué pasó en tareas fuera de las capacidades de la IA?","opciones":["El desempeño mejoró","El desempeño empeoró","No hubo diferencia"],"correcta":1}],"accion":"Usa la IA esta semana para una tarea real y verifica cualquier dato que te entregue."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('prompting-para-profesionales', 'Prompting para profesionales', 137, true, 5, 'ia', 'micro',
          18, 'Principiante', array['todos']::text[], 'aliado', true, false, true, false,
          null, 'Aprende a obtener mejores respuestas de la IA usando contexto, objetivos, restricciones y ejemplos.', 't-prompts', 160, '2026-02-17')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Estructurar un prompt con contexto, objetivo, restricciones y ejemplos","Iterar una respuesta en lugar de empezar de cero","Pedir formatos útiles: tablas, correos, resúmenes","Evitar los errores que producen respuestas genéricas"],"contexto":"La diferencia entre una respuesta genérica y una útil casi nunca es la herramienta: es la instrucción. Un buen prompt ahorra idas y vueltas y convierte la IA en un colega que entiende tu trabajo.\n\nLos modelos de lenguaje generan la respuesta más probable según el contexto que reciben. Si el contexto es pobre, la respuesta será promedio; si es rico —quién eres, para quién es, qué necesitas y cómo lo quieres—, la respuesta se ajusta a tu situación. Las guías oficiales de OpenAI, Anthropic y Google coinciden en los mismos principios: ser específico, dar contexto, mostrar ejemplos, pedir un formato y dividir las tareas complejas en pasos.","lecciones":[{"titulo":"Contexto: quién eres y para quién es","texto":"Empieza con tu rol, tu audiencia y la situación.\n\n“Soy ejecutivo de banca empresarial y preparo una reunión con el gerente financiero de una planta de alimentos en Bucaramanga” cambia por completo el resultado frente a “ayúdame con una reunión”. El contexto le dice a la IA qué vocabulario usar, qué nivel de detalle dar y qué supuestos hacer. Si vas a usar el mismo contexto con frecuencia, guárdalo en las instrucciones personalizadas de tu herramienta."},{"titulo":"Objetivo: qué necesitas exactamente","texto":"Pide un resultado verificable, no una intención.\n\n“Dame ideas” produce una lista genérica; “dame tres preguntas de diagnóstico que revelen si su costo de energía es un problema, sin sonar a venta” produce algo usable. Define cantidad, extensión y propósito: “un correo de 120 palabras”, “una tabla con riesgos y mitigaciones”, “un resumen de cinco líneas para un gerente general”."},{"titulo":"Restricciones: lo que no debe pasar","texto":"Tono, extensión, idioma, nivel técnico y qué evitar.\n\nLas restricciones son las que hacen que la respuesta suene a ti: “tono cercano y profesional”, “sin tecnicismos”, “sin emojis”, “no inventes cifras; si no sabes algo, dilo”, “marca lo que sea suposición”. Esta última es especialmente importante en temas regulatorios o financieros, donde un dato inventado puede costar credibilidad."},{"titulo":"Ejemplos y formato: muestra, no expliques","texto":"Pega un ejemplo de lo que te gusta y define cómo quieres la salida.\n\nLa IA imita estructura y tono mejor de lo que sigue descripciones. Si tienes un correo que funcionó, pégalo y pide “uno similar para este otro cliente”. Indica el formato: tabla con columnas definidas, viñetas, pasos numerados. Un ejemplo vale más que tres párrafos de instrucciones."},{"titulo":"Itera en lugar de empezar de cero","texto":"Corrige sobre la misma conversación: “más corto”, “menos formal”, “agrega un dato del sector”.\n\nLa primera respuesta es un borrador. El modelo conserva el contexto de la conversación, así que cada ajuste mejora el resultado. Si una respuesta es muy mala, pregunta qué información le faltó o pídele que te haga preguntas antes de responder. Tres iteraciones suelen dar mejor resultado que un prompt perfecto."}],"ejercicio":"Toma una tarea real de esta semana y reescribe tu prompt con los cuatro bloques.","pasos":["Elige una tarea que harás esta semana con IA (correo, resumen, preparación de reunión).","Escribe el prompt como lo harías normalmente y guarda la respuesta.","Reescríbelo con contexto, objetivo, restricciones y un ejemplo o formato.","Compara ambas respuestas e itera dos veces sobre la mejor.","Guarda el prompt final en tu Librería de Prompts."],"quiz":[{"pregunta":"¿Qué bloque del prompt hace que la respuesta suene a ti?","opciones":["El objetivo","Las restricciones","La longitud"],"correcta":1},{"pregunta":"¿Qué hacer si la primera respuesta no sirve?","opciones":["Empezar un chat nuevo","Iterar indicando qué ajustar","Cambiar de herramienta"],"correcta":1},{"pregunta":"Mostrar un ejemplo de lo que quieres…","opciones":["Confunde a la IA","Suele mejorar el resultado","Solo sirve para imágenes"],"correcta":1},{"pregunta":"¿Qué restricción reduce los datos inventados?","opciones":["“Sé creativo”","“Marca lo que sea suposición y no inventes cifras”","“Escribe largo”"],"correcta":1}],"accion":"Guarda en tu Librería de Prompts los tres prompts que más usarás esta semana."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('chatgpt-y-claude-para-trabajar-mas-rapido', 'ChatGPT y Claude para trabajar más rápido', 138, true, 5, 'ia', 'curso',
          35, 'Principiante', array['todos']::text[], 'aliado', false, false, true, false,
          null, 'Flujos concretos para correo, documentos y análisis.', 't-prompts', 158, '2026-03-24')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Flujos concretos para correo, documentos y análisis","Cómo trabajar en conversación en lugar de pedir todo de una vez","Cómo usar archivos, proyectos e instrucciones personalizadas","Cómo construir tu propio flujo de trabajo con IA","Cómo medir el tiempo que ahorras"],"contexto":"Saber que la IA existe no ahorra tiempo; integrarla a tus tareas repetitivas sí. La diferencia entre quien la prueba y quien la aprovecha está en los flujos: secuencias de pasos que se repiten cada semana y que la IA puede acelerar.\n\nEste curso se enfoca en ChatGPT y Claude porque son dos de las herramientas más usadas para trabajo profesional, pero los flujos funcionan igual en Gemini o Copilot. La idea es que al terminar tengas al menos tres flujos montados para tu trabajo real: uno de comunicación, uno de documentos y uno de análisis.","lecciones":[{"titulo":"Flujo de correo","texto":"Pega el hilo, explica tu objetivo y pide dos versiones de respuesta con tono y extensión definidos.\n\nEn lugar de escribir desde cero, pega el correo que recibiste y di: “Soy [rol]. Quiero responder aceptando la reunión, proponiendo dos fechas y pidiendo la factura de energía antes. Máximo 100 palabras, tono cordial y directo. Dame dos versiones”. Elige la mejor, ajusta un detalle y envía. Con práctica, una respuesta que tomaba diez minutos toma dos."},{"titulo":"Flujo de documentos","texto":"Sube el archivo, pide un resumen estructurado y luego haz preguntas específicas.\n\nAmbas herramientas permiten adjuntar PDFs, presentaciones y documentos de texto. Empieza con una instrucción de estructura: “Resume en tres ideas principales, cifras clave con su página y preguntas que quedan abiertas”. Después profundiza: “¿Qué dice sobre los plazos?”, “¿hay riesgos para nosotros?”. Siempre pide que cite la página de donde saca cada dato para poder verificarlo."},{"titulo":"Flujo de análisis","texto":"Sube una hoja de cálculo y pide tendencias, valores atípicos y conclusiones accionables.\n\nLas versiones actuales pueden leer archivos de Excel o CSV, hacer cálculos y generar gráficos. Una buena instrucción: “Analiza estas ventas mensuales por cliente. Identifica los cinco clientes con mayor crecimiento, los que cayeron más de 20% y tres conclusiones. Muestra los cálculos”. Revisa los cálculos clave antes de usar los resultados en una decisión."},{"titulo":"Itera, no empieces de cero","texto":"Trata la conversación como trabajo con un colega: corrige, precisa y pide ajustes.\n\nSi la primera respuesta no sirve, no abras un chat nuevo. Di qué cambiar: “Más corto”, “menos formal”, “agrega un dato sobre el sector”, “quita la última frase”. El modelo conserva el contexto de la conversación y mejora con cada indicación. Tres o cuatro iteraciones suelen producir un resultado mejor que cualquier instrucción perfecta en el primer intento."},{"titulo":"Instrucciones personalizadas y proyectos","texto":"Configura una vez quién eres y cómo quieres las respuestas; ahorra contexto en cada conversación.\n\nChatGPT ofrece instrucciones personalizadas y proyectos; Claude ofrece proyectos con instrucciones y documentos de referencia. Escribe ahí tu rol, tu audiencia, tu tono y tus formatos preferidos, y sube documentos que uses con frecuencia (portafolio, preguntas frecuentes, guías). Así, cada conversación empieza con tu contexto ya cargado."}],"ejercicio":"Monta tres flujos de trabajo con IA para tareas que repites cada semana.","pasos":["Lista las cinco tareas que más tiempo te toman cada semana.","Elige tres que involucren escribir, leer documentos o analizar datos.","Para cada una, escribe la instrucción base que usarás siempre.","Configura tus instrucciones personalizadas o un proyecto con tu contexto.","Usa los tres flujos durante una semana y registra el tiempo antes y después."],"quiz":[{"pregunta":"¿Qué hacer si la primera respuesta no sirve?","opciones":["Abrir un chat nuevo","Iterar indicando qué ajustar","Cambiar de herramienta"],"correcta":1},{"pregunta":"¿Qué conviene pedir al resumir un documento?","opciones":["Que cite la página de cada dato","Que invente lo que falte","Solo una frase"],"correcta":0},{"pregunta":"¿Para qué sirven las instrucciones personalizadas o los proyectos?","opciones":["Para cargar tu contexto en cada conversación","Para pagar menos","Para borrar el historial"],"correcta":0},{"pregunta":"¿Qué debes revisar antes de usar un análisis de datos hecho con IA?","opciones":["Los cálculos clave","El color del gráfico","Nada"],"correcta":0}],"accion":"Configura tus instrucciones personalizadas con tu rol, tu audiencia y tu tono."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-para-reuniones', 'IA para reuniones', 139, true, 5, 'ia', 'micro',
          14, 'Principiante', array['todos']::text[], 'aliado', false, true, false, false,
          null, 'Prepara, toma notas y resume acuerdos automáticamente.', 't-reunion', 96, '2026-04-04')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Preparar una reunión en 15 minutos con IA","Tomar notas y transcribir de forma responsable","Convertir notas en acta, compromisos y seguimiento","Errores que hay que evitar"],"contexto":"Las reuniones consumen buena parte de la semana de un profesional y, sin embargo, muchas terminan sin acuerdos claros o sin seguimiento. La IA puede intervenir en los tres momentos: antes, para preparar; durante, para registrar; y después, para convertir lo conversado en acciones.\n\nEl objetivo no es tener más reuniones ni delegar la conversación a una máquina, sino llegar mejor preparado, escuchar con más atención (porque no estás escribiendo cada palabra) y asegurar que lo acordado ocurra.","lecciones":[{"titulo":"Antes: preparar","texto":"Investigación de la empresa, hipótesis de necesidad, preguntas y agenda en un solo flujo.\n\nPide a la IA un resumen de la empresa con base en su sitio web y noticias públicas (verificando los datos), tres hipótesis sobre sus retos y cinco preguntas de diagnóstico. Luego pide una agenda de 30 minutos con tiempos. En 15 minutos tienes una preparación que antes tomaba una hora. Revisa siempre que la información de la empresa sea actual y correcta."},{"titulo":"Durante: registrar","texto":"Herramientas de transcripción pueden registrar la conversación, siempre con el consentimiento de los participantes.\n\nTeams, Zoom, Google Meet y aplicaciones especializadas ofrecen transcripción y resúmenes automáticos. Antes de activarlas, pide permiso: “¿Les molesta si activo la transcripción para no perder ningún acuerdo?”. En reuniones presenciales o sensibles, basta con notas propias breves. Lo importante es capturar decisiones, compromisos y frases textuales del cliente."},{"titulo":"Después: actas y seguimiento","texto":"Pega tus notas o la transcripción y pide acta, compromisos con responsable y fecha, y correo de seguimiento.\n\nUna instrucción efectiva: “Con estas notas, escribe un acta con decisiones, compromisos (responsable y fecha) y temas pendientes. Luego redacta un correo de seguimiento de máximo 120 palabras para el cliente”. Revisa que los compromisos sean exactos y envía el seguimiento en las primeras 24 horas."},{"titulo":"Errores a evitar","texto":"Grabar sin permiso, compartir información confidencial en herramientas no autorizadas y enviar resúmenes sin revisar.\n\nUna transcripción automática puede confundir nombres, cifras o el sentido de una frase. Un resumen enviado sin revisar puede comprometer un acuerdo. Y pegar información confidencial de un cliente en una herramienta sin acuerdo corporativo puede violar políticas de privacidad. La regla: la IA prepara, tú revisas y decides."}],"ejercicio":"Usa la IA para preparar, registrar y hacer el seguimiento de una reunión real esta semana.","pasos":["Elige una reunión de esta semana con un cliente o aliado.","Pide a la IA un resumen de la empresa, tres hipótesis y cinco preguntas.","Durante la reunión, toma notas breves o usa transcripción con permiso.","Al terminar, pide a la IA un acta con compromisos y un correo de seguimiento.","Revisa, corrige y envía el seguimiento en menos de 24 horas."],"quiz":[{"pregunta":"¿Qué debes hacer antes de activar una transcripción?","opciones":["Nada","Pedir permiso a los participantes","Avisar después"],"correcta":1},{"pregunta":"¿En cuánto tiempo conviene enviar el seguimiento?","opciones":["Una semana","Menos de 24 horas","Un mes"],"correcta":1},{"pregunta":"¿Qué riesgo tiene enviar un resumen automático sin revisar?","opciones":["Errores en nombres, cifras o acuerdos","Ninguno","Que llegue tarde"],"correcta":0},{"pregunta":"¿Qué debe incluir un buen compromiso en el acta?","opciones":["Responsable y fecha","Solo el tema","Un emoji"],"correcta":0}],"accion":"Envía el seguimiento de tu próxima reunión en menos de 24 horas, preparado con IA y revisado por ti."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-para-analizar-informacion', 'IA para analizar información', 140, true, 5, 'ia', 'micro',
          18, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Hojas de cálculo, PDFs y reportes: preguntas que ahorran horas.', 't-prompts', 94, '2026-05-11')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Analizar hojas de cálculo, PDFs y reportes con IA","Las preguntas que ahorran horas de lectura","Cómo verificar los resultados","Cómo presentar las conclusiones"],"contexto":"Buena parte del trabajo profesional consiste en leer información para extraer conclusiones: estados financieros, informes sectoriales, contratos, encuestas, reportes de ventas. La IA puede hacer el primer análisis en minutos y dejarte el tiempo para lo que requiere criterio: interpretar, decidir y comunicar.\n\nLa clave está en las preguntas. Un análisis pobre suele venir de una instrucción vaga (“analiza esto”); un análisis útil viene de una pregunta precisa que define qué buscar, cómo organizarlo y qué hacer con lo que no está en el documento.","lecciones":[{"titulo":"Hojas de cálculo","texto":"Pide tendencias, comparaciones, valores atípicos y conclusiones, y que muestre los cálculos.\n\n“Esta tabla tiene las ventas mensuales de 2024 y 2025 por línea de producto. Calcula el crecimiento de cada línea, identifica las que cayeron más de 10%, los meses atípicos y tres conclusiones accionables. Muestra las fórmulas o cálculos que usaste.” Pedir los cálculos permite verificar el resultado y detectar errores de interpretación de columnas."},{"titulo":"PDFs e informes","texto":"Estructura la salida: ideas principales, cifras con su página, implicaciones y preguntas abiertas.\n\nPara un informe sectorial de 60 páginas, una buena instrucción es: “Resume en cinco ideas principales, una tabla con las diez cifras más relevantes y su página, tres implicaciones para empresas de [sector] en [región] y las preguntas que el informe no responde. No incluyas información que no esté en el documento”. La última frase reduce las invenciones."},{"titulo":"Comparar documentos","texto":"Sube dos versiones o dos propuestas y pide diferencias en una tabla.\n\nLa IA es muy útil para comparar propuestas de proveedores, versiones de un contrato o informes de dos años. “Compara estas dos propuestas en una tabla: alcance, precio, plazos, garantías, exclusiones y riesgos. Señala lo que una incluye y la otra no.” Revisa las diferencias críticas directamente en los documentos originales."},{"titulo":"Verificar y presentar","texto":"Contrasta las cifras clave con la fuente, y presenta conclusiones, no datos.\n\nAntes de usar un análisis, verifica al menos tres cifras al azar en el documento original. Si alguna no coincide, revisa todo. Luego convierte el análisis en un mensaje: “Las ventas de la línea B cayeron 18%, concentradas en dos clientes; recomendamos visitarlos este mes”. El valor no está en el resumen, sino en la decisión que permite tomar."}],"ejercicio":"Analiza con IA un documento o una hoja de cálculo real y verifica tres cifras.","pasos":["Elige un documento o tabla que necesites entender esta semana.","Escribe una instrucción precisa con estructura de salida.","Pide que muestre cálculos o cite páginas.","Verifica tres cifras en la fuente original.","Escribe una conclusión accionable de máximo dos frases."],"quiz":[{"pregunta":"¿Qué produce un análisis pobre?","opciones":["Una instrucción vaga","Una pregunta precisa","Pedir los cálculos"],"correcta":0},{"pregunta":"¿Por qué pedir que muestre los cálculos?","opciones":["Para verificar el resultado","Para que sea más largo","No sirve"],"correcta":0},{"pregunta":"¿Qué frase reduce las invenciones al resumir un PDF?","opciones":["“No incluyas información que no esté en el documento”","“Sé creativo”","“Completa lo que falte”"],"correcta":0},{"pregunta":"¿Cuántas cifras conviene verificar como mínimo?","opciones":["Ninguna","Al menos tres al azar","Solo la primera"],"correcta":1}],"accion":"Analiza con IA un documento de esta semana y comparte una conclusión accionable con tu equipo."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('crea-tu-primer-asistente-de-ia', 'Crea tu primer asistente de IA', 141, true, 5, 'ia', 'curso',
          40, 'Intermedio', array['todos']::text[], 'aliado', false, true, false, false,
          null, 'Un asistente configurado con tu contexto de trabajo.', 't-prompts', 92, '2026-06-18')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es un asistente personalizado y para qué sirve","Cómo escribir sus instrucciones","Qué documentos darle como conocimiento","Cómo probarlo y mejorarlo","Límites de privacidad y uso responsable"],"contexto":"Un asistente de IA personalizado es una configuración que guarda tu contexto, tus instrucciones y tus documentos de referencia para una tarea específica. En lugar de explicar quién eres y qué necesitas en cada conversación, el asistente ya lo sabe.\n\nLas principales herramientas ofrecen esta función con distintos nombres: GPTs personalizados y proyectos en ChatGPT, proyectos en Claude, Gems en Gemini y agentes en Copilot. Un buen asistente puede preparar reuniones con tu metodología, responder preguntas frecuentes de tus clientes con tu información o redactar contenidos en tu tono. Este curso te guía para construir el primero en menos de una hora.","lecciones":[{"titulo":"Elige una tarea","texto":"Un buen asistente resuelve una tarea concreta y repetitiva, no “todo”.\n\nEjemplos: un asistente que prepara reuniones comerciales con tu plantilla; uno que responde preguntas sobre el programa Aliados del Sol con base en sus documentos; uno que escribe publicaciones de LinkedIn en tu voz; uno que revisa propuestas y señala lo que falta. Cuanto más específica la tarea, mejor el resultado. Empieza con la que repites más de tres veces por semana."},{"titulo":"Escribe las instrucciones","texto":"Rol, objetivo, audiencia, pasos, formato de salida y qué no debe hacer.\n\nUnas buenas instrucciones parecen un manual breve: “Eres un asistente de preparación de reuniones para un ejecutivo de banca empresarial. Cuando te dé el nombre de una empresa, investiga información pública, formula tres hipótesis de necesidad, cinco preguntas de diagnóstico y una agenda de 30 minutos. Usa tablas. Marca lo que sea suposición. Nunca inventes cifras”. Escribe en segunda persona y con frases cortas."},{"titulo":"Dale conocimiento","texto":"Sube los documentos que necesita: guías, preguntas frecuentes, plantillas y ejemplos de buen trabajo.\n\nEl asistente responderá mejor si tiene ejemplos concretos: una reunión bien preparada, tres publicaciones que te gustan, la guía del Referido Perfecto. No subas información confidencial de clientes ni datos personales a herramientas sin acuerdo corporativo. Mantén los documentos actualizados: un asistente con información vieja da respuestas viejas."},{"titulo":"Prueba y mejora","texto":"Haz cinco pruebas con casos reales, anota los errores y ajusta las instrucciones.\n\nLa primera versión siempre tiene fallas: respuestas demasiado largas, formatos inconsistentes, suposiciones no marcadas. Cada error es una instrucción que falta. Agrega frases como “máximo 200 palabras”, “usa siempre esta estructura” o “si no sabes algo, pregunta”. Tras dos o tres rondas, el asistente será confiable para el uso diario."},{"titulo":"Comparte con criterio","texto":"Si tu equipo puede usarlo, compártelo; documenta para qué sirve y para qué no.\n\nUn asistente bien construido puede estandarizar la calidad del trabajo de un equipo. Al compartirlo, incluye una descripción clara, ejemplos de uso y las limitaciones. Revisa periódicamente las respuestas para asegurar que sigue funcionando como esperas, especialmente si cambian los documentos de referencia."}],"ejercicio":"Construye un asistente personalizado para una tarea que repites cada semana.","pasos":["Elige la tarea y escribe en una frase qué debe hacer el asistente.","Redacta las instrucciones con rol, objetivo, pasos, formato y restricciones.","Reúne dos o tres documentos o ejemplos de referencia (sin datos confidenciales).","Crea el asistente en tu herramienta y haz cinco pruebas con casos reales.","Ajusta las instrucciones según los errores y documenta para qué sirve."],"quiz":[{"pregunta":"¿Qué tarea conviene para un primer asistente?","opciones":["Todo tu trabajo","Una tarea concreta y repetitiva","Una tarea que haces una vez al año"],"correcta":1},{"pregunta":"¿Qué deben incluir las instrucciones?","opciones":["Rol, objetivo, pasos, formato y restricciones","Solo un saludo","Tu contraseña"],"correcta":0},{"pregunta":"¿Qué no debes subir como conocimiento sin acuerdo corporativo?","opciones":["Plantillas propias","Datos confidenciales de clientes","Ejemplos de buen trabajo"],"correcta":1},{"pregunta":"¿Cómo se mejora un asistente?","opciones":["Probando con casos reales y ajustando instrucciones","Dejándolo igual","Cambiando de nombre"],"correcta":0}],"accion":"Crea tu primer asistente para la tarea que más repites y úsalo durante una semana."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('automatizaciones-sin-programar', 'Automatizaciones sin programar', 142, true, 5, 'ia', 'curso',
          38, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Conecta tus herramientas y elimina tareas repetitivas.', 't-automatiza', 90, '2026-07-25')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es una automatización y cómo se estructura","Herramientas sin código: Power Automate, Zapier, Make y otras","Las cinco automatizaciones más útiles para un profesional","Cómo diseñar, probar y mantener un flujo","Cuándo no automatizar"],"contexto":"Una automatización es una regla que ejecuta acciones por ti cuando ocurre algo: llega un correo, se llena un formulario, cambia una fecha o se agrega una fila a una hoja de cálculo. Las herramientas sin código permiten crear estas reglas arrastrando bloques, sin escribir una línea de programación.\n\nPara un profesional que gestiona contactos, seguimientos y reportes, las automatizaciones eliminan el trabajo de copiar, pegar, recordar y reenviar. Y cuando se combinan con IA, pueden además resumir, clasificar o redactar dentro del flujo. Este curso te enseña a pensar en automatizaciones y a construir las primeras.","lecciones":[{"titulo":"La estructura: disparador y acciones","texto":"Cuando pasa X (disparador), haz Y y Z (acciones). Toda automatización sigue esa lógica.\n\nEjemplo: cuando llega un correo con la palabra “factura” en el asunto (disparador), guarda el adjunto en una carpeta de Drive (acción 1) y agrega una fila en una hoja de seguimiento con el remitente y la fecha (acción 2). Antes de abrir cualquier herramienta, escribe tu automatización en una frase con esa estructura: si no puedes describirla así, todavía no está clara."},{"titulo":"Las herramientas","texto":"Power Automate (Microsoft 365), Zapier, Make y las automatizaciones nativas de Google, CRMs y WhatsApp Business.\n\nSi tu empresa usa Microsoft 365, Power Automate está probablemente incluido y se conecta con Outlook, Teams, Excel y SharePoint. Zapier y Make conectan miles de aplicaciones y tienen planes gratuitos con límites. Muchos CRMs (como Clientify o HubSpot) tienen automatizaciones propias para seguimientos. WhatsApp Business permite respuestas rápidas y mensajes automáticos de bienvenida o ausencia."},{"titulo":"Cinco automatizaciones útiles","texto":"Recordatorios de seguimiento, guardar adjuntos, registrar formularios, resúmenes semanales y alertas de fechas.\n\n1) Si un contacto no responde en cinco días, crea una tarea de seguimiento. 2) Guarda automáticamente las facturas que llegan por correo. 3) Cuando alguien llena un formulario, agrégalo a tu hoja de contactos y envíale un correo de bienvenida. 4) Cada viernes, recibe un resumen de las tareas pendientes. 5) Recibe una alerta una semana antes del vencimiento de un contrato o de una fecha clave."},{"titulo":"Diseñar, probar y mantener","texto":"Empieza pequeño, prueba con datos reales y revisa cada mes que siga funcionando.\n\nConstruye primero la versión más simple: un disparador y una acción. Pruébala con casos reales, incluidos los casos raros (un correo sin adjunto, un formulario incompleto). Luego agrega pasos. Las automatizaciones se rompen cuando cambia una contraseña, una carpeta o un formato, así que revísalas periódicamente y documenta qué hace cada una."},{"titulo":"Cuándo no automatizar","texto":"Si la tarea requiere criterio, ocurre pocas veces o afecta una relación sensible, no la automatices.\n\nUna regla práctica: automatiza lo que se repite al menos una vez por semana, sigue siempre los mismos pasos y no requiere juicio. Un mensaje personal a un cliente importante, una negociación o una respuesta a una queja deben seguir siendo humanos. La automatización debe liberar tiempo para las relaciones, no reemplazarlas."}],"ejercicio":"Diseña y construye tu primera automatización para una tarea semanal.","pasos":["Lista cinco tareas repetitivas que haces cada semana.","Elige una que no requiera criterio y escríbela como “Cuando pasa X, haz Y”.","Identifica la herramienta disponible en tu empresa o una gratuita.","Construye la versión más simple y pruébala con tres casos reales.","Documenta qué hace y programa una revisión mensual."],"quiz":[{"pregunta":"¿Cuál es la estructura de toda automatización?","opciones":["Disparador y acciones","Pregunta y respuesta","Inicio y fin"],"correcta":0},{"pregunta":"¿Qué herramienta suele estar incluida en Microsoft 365?","opciones":["Power Automate","Photoshop","Canva"],"correcta":0},{"pregunta":"¿Qué tarea NO conviene automatizar?","opciones":["Guardar adjuntos de facturas","Responder una queja de un cliente importante","Recordatorios de seguimiento"],"correcta":1},{"pregunta":"¿Por qué revisar las automatizaciones periódicamente?","opciones":["Porque se rompen con cambios de contraseña, carpetas o formatos","No es necesario","Para borrarlas"],"correcta":0}],"accion":"Construye esta semana una automatización simple de seguimiento o de guardado de archivos."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-responsable', 'IA responsable', 143, true, 5, 'ia', 'flash',
          7, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Privacidad, sesgos y verificación: reglas de uso profesional.', 't-prompts', 88, '2026-08-05')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las tres reglas de privacidad que nunca debes romper","Cómo reconocer y reducir sesgos","Cómo verificar lo que produce la IA"],"contexto":"La IA es una herramienta poderosa, y como toda herramienta poderosa exige reglas de uso. Un error de privacidad, un dato inventado en una propuesta o un contenido sesgado pueden dañar la confianza de un cliente o la reputación de una organización.\n\nEn Colombia, la Ley 1581 de 2012 regula el tratamiento de datos personales, y muchas organizaciones ya tienen políticas internas sobre el uso de IA. A nivel global, marcos como la Ley de IA de la Unión Europea están definiendo estándares que influyen en las prácticas corporativas. Usar la IA de forma responsable no es un freno: es lo que permite usarla con confianza.","lecciones":[{"titulo":"Privacidad","texto":"No pegues datos personales, financieros o confidenciales en herramientas sin acuerdo corporativo.\n\nLas versiones gratuitas de algunas herramientas pueden usar las conversaciones para mejorar sus modelos, según sus términos. Las versiones empresariales suelen ofrecer garantías de que los datos no se usan para entrenamiento. Antes de pegar un estado financiero, una base de clientes o un contrato, verifica qué herramienta autoriza tu organización. Si no estás seguro, anonimiza: reemplaza nombres, NIT y cifras sensibles."},{"titulo":"Sesgos","texto":"Los modelos reflejan patrones de los datos con que se entrenaron, incluidos estereotipos.\n\nUna IA puede asumir el género de un cargo, favorecer ciertos perfiles en una selección o generar imágenes con estereotipos. Revisa los contenidos con una pregunta simple: ¿esto trataría de forma justa a cualquier persona o grupo? En decisiones sobre personas (contratación, crédito, evaluación), la IA puede apoyar, pero nunca decidir sola."},{"titulo":"Verificación","texto":"Todo dato, cifra, norma o cita que produce la IA debe verificarse antes de usarse.\n\nPide a la IA que marque lo que es suposición y que indique sus fuentes, y luego revisa esas fuentes. En temas regulatorios —como la Ley 1715 o las resoluciones de la CREG— consulta siempre el texto oficial o un experto. La regla final es simple: la IA redacta, tú decides y tú firmas."}],"ejercicio":"Revisa tus últimas tres interacciones con IA y evalúa si cumplieron las reglas de privacidad, sesgo y verificación.","pasos":["Abre tus últimas tres conversaciones con una herramienta de IA.","Revisa si compartiste datos personales o confidenciales.","Identifica cualquier dato o cifra que no hayas verificado.","Escribe tres reglas personales de uso responsable de la IA."],"quiz":[{"pregunta":"¿Qué debes hacer antes de pegar un contrato de un cliente en una herramienta de IA?","opciones":["Nada","Verificar que la herramienta esté autorizada o anonimizar","Publicarlo"],"correcta":1},{"pregunta":"¿Qué ley regula los datos personales en Colombia?","opciones":["Ley 1581 de 2012","Ley 1715 de 2014","Ley 100 de 1993"],"correcta":0},{"pregunta":"¿Quién es responsable final de un contenido generado con IA?","opciones":["La herramienta","La persona que lo usa y firma","Nadie"],"correcta":1}],"accion":"Escribe tus tres reglas personales de uso responsable de IA y compártelas con tu equipo."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-recuperar-5-horas-de-trabajo-cada-semana', 'Cómo recuperar 5 horas de trabajo cada semana', 144, true, 5, 'ia', 'micro',
          15, 'Principiante', array['todos']::text[], 'aliado', false, false, true, false,
          null, 'Audita tu semana y automatiza lo que no requiere criterio.', 't-automatiza', 146, '2026-09-12')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Auditar tu semana para encontrar el tiempo perdido","Clasificar tareas: criterio, delegar, automatizar o eliminar","Aplicar IA y automatización a lo repetitivo","Proteger el tiempo recuperado"],"contexto":"La mayoría de los profesionales sienten que no tienen tiempo, pero pocos saben exactamente en qué se les va. Diversos estudios sobre el trabajo del conocimiento —incluidos los informes de Microsoft sobre tendencias laborales— muestran que una parte importante de la semana se dedica a correos, reuniones y búsqueda de información, más que al trabajo que realmente genera valor.\n\nRecuperar cinco horas semanales equivale a más de 200 horas al año: cinco semanas laborales completas. No se logra trabajando más rápido, sino eliminando, automatizando y delegando lo que no requiere tu criterio.","lecciones":[{"titulo":"Audita tu semana","texto":"Registra durante cinco días en qué usas tu tiempo, en bloques de 30 minutos.\n\nNo confíes en tu memoria: anota cada bloque de media hora con la tarea real. Al final de la semana, agrupa por tipo: correos, reuniones, preparación, seguimiento, reportes, búsqueda de información, trabajo de fondo. Casi siempre aparecen sorpresas: horas en correos que no requieren respuesta, reuniones sin agenda o búsquedas repetidas de los mismos documentos."},{"titulo":"Clasifica","texto":"Cuatro categorías: requiere mi criterio, se puede delegar, se puede automatizar o se puede eliminar.\n\nPasa cada tipo de tarea por estas preguntas: ¿qué pasaría si no la hiciera?, ¿alguien más podría hacerla igual de bien?, ¿sigue siempre los mismos pasos?, ¿necesita mi juicio? Lo que no pasa ningún filtro se elimina. Lo que sigue pasos fijos se automatiza. Lo que otro puede hacer se delega. Lo que queda es tu trabajo de verdad."},{"titulo":"Aplica IA y automatización","texto":"Correos, resúmenes, actas, reportes y seguimientos son los candidatos más claros.\n\nUsa la IA para redactar primeros borradores de correos, resumir documentos largos y convertir notas en actas. Usa automatizaciones para recordatorios de seguimiento, guardado de archivos y reportes periódicos. Cada flujo que montes puede ahorrarte entre 15 y 60 minutos semanales; cinco flujos bien elegidos suman las cinco horas."},{"titulo":"Protege el tiempo recuperado","texto":"Bloquea en tu calendario el tiempo ganado para trabajo de alto valor.\n\nSi no lo proteges, el tiempo recuperado se llena con más correos y reuniones. Reserva dos o tres bloques semanales de 90 minutos para trabajo profundo: preparar clientes clave, prospectar oportunidades, aprender. Ese es el tiempo que realmente mueve tus resultados."}],"ejercicio":"Audita tu semana, clasifica tus tareas y monta dos mejoras con IA o automatización.","pasos":["Registra tu tiempo en bloques de 30 minutos durante cinco días.","Agrupa los bloques por tipo de tarea y suma las horas.","Clasifica cada tipo: criterio, delegar, automatizar o eliminar.","Elige dos tareas para automatizar o hacer con IA y monta el flujo.","Bloquea en tu calendario el tiempo recuperado para trabajo de alto valor."],"quiz":[{"pregunta":"¿Cuál es el primer paso para recuperar tiempo?","opciones":["Trabajar más rápido","Auditar en qué se usa el tiempo","Comprar una herramienta"],"correcta":1},{"pregunta":"Una tarea que sigue siempre los mismos pasos y no requiere juicio se debe…","opciones":["Eliminar","Automatizar","Hacer a mano"],"correcta":1},{"pregunta":"¿Cuánto equivalen cinco horas semanales al año?","opciones":["Unas 20 horas","Más de 200 horas","Mil horas"],"correcta":1},{"pregunta":"¿Qué hacer con el tiempo recuperado?","opciones":["Dejarlo libre para más correos","Protegerlo para trabajo de alto valor","Nada"],"correcta":1}],"accion":"Registra tu tiempo durante los próximos cinco días hábiles."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inbox-zero-para-ejecutivos', 'Inbox Zero para ejecutivos', 145, true, 5, 'negocios', 'flash',
          7, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Un método para que el correo deje de controlar tu día.', 't-automatiza', 84, '2026-01-19')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["El método para que el correo deje de controlar tu día","Las cinco decisiones para cada correo","Rutinas y reglas para sostenerlo"],"contexto":"El correo electrónico es, para muchos ejecutivos, la principal fuente de interrupciones. Revisarlo de forma constante fragmenta la atención y deja poco tiempo para el trabajo que requiere concentración.\n\nEl método Inbox Zero, propuesto por Merlin Mann a mediados de la década de 2000, no busca tener la bandeja vacía todo el tiempo, sino que procesar el correo deje de consumir atención. La clave: decidir qué hacer con cada mensaje una sola vez.","lecciones":[{"titulo":"Las cinco decisiones","texto":"Eliminar, delegar, responder, posponer o archivar.\n\nCada correo debe tener un destino: si no requiere acción, elimínalo o archívalo. Si otra persona debe resolverlo, delégalo. Si se responde en menos de dos minutos, respóndelo de inmediato (regla tomada del método GTD de David Allen). Si requiere más tiempo, conviértelo en una tarea con fecha. Lo que no tomes decisión hoy volverá a quitarte atención mañana."},{"titulo":"Bloques de correo","texto":"Revisa el correo en dos o tres bloques al día, no de forma continua.\n\nDesactiva las notificaciones y define horarios: por ejemplo, a las 9 a. m., a la 1 p. m. y a las 5 p. m. En cada bloque, procesa todo hasta dejar la bandeja vacía. Si tu rol exige respuestas rápidas, comunica a tus contactos clave cuál es el mejor canal para lo urgente."},{"titulo":"Reglas y plantillas","texto":"Automatiza la clasificación y guarda respuestas frecuentes.\n\nCrea reglas para mover boletines y notificaciones a carpetas específicas, y plantillas para las respuestas que escribes con frecuencia. Date de baja de los boletines que no lees. Estas acciones reducen el volumen que llega a tu bandeja principal y aceleran cada bloque."}],"ejercicio":"Lleva tu bandeja de entrada a cero con las cinco decisiones y define tus bloques de correo.","pasos":["Reserva 45 minutos y procesa tu bandeja con las cinco decisiones.","Crea tres reglas para boletines y notificaciones.","Define tus bloques de correo y desactiva las notificaciones.","Date de baja de cinco boletines que no lees."],"quiz":[{"pregunta":"¿Cuál es el objetivo de Inbox Zero?","opciones":["Tener cero correos siempre","Que procesar el correo deje de consumir atención","No usar correo"],"correcta":1},{"pregunta":"¿Qué hacer con un correo que se responde en menos de dos minutos?","opciones":["Posponerlo","Responderlo de inmediato","Eliminarlo"],"correcta":1},{"pregunta":"¿Cada cuánto conviene revisar el correo?","opciones":["De forma continua","En dos o tres bloques al día","Una vez al mes"],"correcta":1}],"accion":"Desactiva las notificaciones de correo y define tus bloques diarios."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('el-sistema-personal-de-seguimiento', 'El sistema personal de seguimiento', 146, true, 5, 'negocios', 'micro',
          12, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Nunca más una oportunidad perdida por olvido.', 't-automatiza', 82, '2026-02-26')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Por qué la memoria no es un sistema","Los elementos de un sistema de seguimiento","Herramientas simples para implementarlo","La revisión semanal"],"contexto":"Una oportunidad perdida por olvido es una de las pérdidas más evitables en el trabajo comercial. Sin un sistema, los compromisos quedan dispersos entre correos, chats, notas y la memoria, y algo siempre se escapa.\n\nLa psicóloga Bluma Zeigarnik describió en los años veinte cómo las tareas incompletas permanecen en la mente y consumen atención. Un sistema de seguimiento externo libera esa carga mental: todo lo pendiente está registrado en un lugar confiable, con su próxima acción y su fecha.","lecciones":[{"titulo":"La memoria no es un sistema","texto":"Los pendientes dispersos generan olvidos y estrés.\n\nCuando los compromisos viven en tu cabeza, ocupan atención y, aun así, se olvidan. Un sistema externo —una lista, una hoja o un CRM— permite confiar en que nada se perderá. David Allen, en su método Getting Things Done, lo resume así: la mente es para tener ideas, no para guardarlas."},{"titulo":"Los elementos","texto":"Un único lugar, cada pendiente con próxima acción concreta, responsable y fecha.\n\nPara cada contacto u oportunidad registra: nombre, empresa, estado, próxima acción (en verbo: “llamar para pedir factura”), fecha y notas clave. Un pendiente sin próxima acción ni fecha es un deseo, no un compromiso. Usa un solo lugar: tener varias listas es lo mismo que no tener ninguna."},{"titulo":"Herramientas simples","texto":"Una hoja de cálculo con formato condicional, tareas del correo o un CRM sencillo.\n\nNo necesitas software complejo. Una hoja con columnas de contacto, estado, próxima acción, fecha y notas, con formato condicional que resalte fechas vencidas, funciona muy bien. Las tareas de Outlook o Google también sirven. Para tus referidos de Aliados del Sol, el Hub ya registra la etapa de cada oportunidad; tu sistema personal complementa con tus acciones."},{"titulo":"La revisión semanal","texto":"Treinta minutos cada viernes para revisar todo y planear la semana siguiente.\n\nEn la revisión semanal: actualiza el estado de cada pendiente, define la próxima acción de los que no la tienen, revisa las fechas de la semana siguiente y agrega cualquier compromiso nuevo. Este ritual es lo que mantiene vivo el sistema; sin él, la lista se desactualiza en pocas semanas."}],"ejercicio":"Monta tu sistema personal de seguimiento y haz tu primera revisión semanal.","pasos":["Reúne todos tus pendientes de correos, chats y notas.","Crea una hoja con columnas: contacto, estado, próxima acción, fecha y notas.","Escribe una próxima acción concreta y una fecha para cada pendiente.","Agrega formato condicional para fechas vencidas.","Agenda una revisión semanal de 30 minutos cada viernes."],"quiz":[{"pregunta":"¿Qué libera un sistema de seguimiento externo?","opciones":["Carga mental","Tiempo de vacaciones","Nada"],"correcta":0},{"pregunta":"¿Qué debe tener cada pendiente?","opciones":["Próxima acción concreta y fecha","Solo el nombre","Un color"],"correcta":0},{"pregunta":"¿Cuántos lugares de registro conviene tener?","opciones":["Uno","Cinco","Ninguno"],"correcta":0},{"pregunta":"¿Qué mantiene vivo el sistema?","opciones":["La revisión semanal","Comprar software","Recordar todo"],"correcta":0}],"accion":"Agenda tu revisión semanal de 30 minutos cada viernes."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('automatiza-tu-trabajo-sin-ser-programador', 'Automatiza tu trabajo sin ser programador', 147, true, 5, 'ia', 'micro',
          18, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Plantillas, reglas y flujos para el día a día.', 't-automatiza', 80, '2026-03-06')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Plantillas, reglas y atajos para el día a día","Reglas de correo y respuestas rápidas","Plantillas de documentos y mensajes","Combinar IA con automatizaciones simples"],"contexto":"No todas las automatizaciones requieren una herramienta especializada. Muchas de las que más tiempo ahorran ya están en las aplicaciones que usas todos los días: reglas de correo, plantillas, respuestas rápidas, atajos de texto y funciones de las hojas de cálculo.\n\nEste curso se enfoca en esas automatizaciones cotidianas: pequeñas, fáciles de configurar y con un efecto acumulado grande. Son el primer paso antes de pasar a flujos más complejos.","lecciones":[{"titulo":"Reglas de correo","texto":"Filtra, clasifica y prioriza automáticamente los correos que recibes.\n\nOutlook y Gmail permiten crear reglas: mover boletines a una carpeta, marcar como importantes los correos de tus clientes clave, etiquetar las facturas o reenviar ciertos mensajes a tu equipo. Diez minutos configurando reglas pueden reducir a la mitad el tiempo que pasas clasificando tu bandeja."},{"titulo":"Plantillas y respuestas rápidas","texto":"Guarda los mensajes que escribes una y otra vez.\n\nSi envías con frecuencia el mismo tipo de mensaje —solicitud de factura, confirmación de reunión, seguimiento, presentación de GEENERA—, guárdalo como plantilla en tu correo o como respuesta rápida en WhatsApp Business. Deja espacios entre corchetes para personalizar el nombre y el detalle. Personalizar una plantilla toma 30 segundos; escribir desde cero, cinco minutos."},{"titulo":"Atajos y hojas de cálculo","texto":"Expansores de texto, validaciones de datos y fórmulas que evitan trabajo manual.\n\nLos expansores de texto convierten una abreviatura en un párrafo completo. En hojas de cálculo, las listas desplegables evitan errores de digitación, el formato condicional resalta fechas vencidas y funciones como BUSCARX o FILTRAR reemplazan búsquedas manuales. Una hoja de seguimiento bien configurada te avisa visualmente qué contacto requiere atención."},{"titulo":"IA dentro del flujo","texto":"Usa la IA para el paso que requiere redactar o resumir dentro de una rutina repetitiva.\n\nCombina plantillas con IA: una plantilla base de seguimiento y una instrucción para personalizarla según las notas de la reunión. O una regla que guarda los correos de clientes en una carpeta y una sesión semanal donde la IA resume los pendientes. Con Copilot o Gemini integrados al correo, este paso puede hacerse sin cambiar de aplicación."}],"ejercicio":"Configura tres automatizaciones cotidianas: una regla de correo, una plantilla y un atajo.","pasos":["Identifica el tipo de correo que más tiempo te quita clasificar y crea una regla.","Escribe la plantilla del mensaje que más repites y guárdala.","Configura una respuesta rápida en WhatsApp Business o un atajo de texto.","Agrega formato condicional a tu hoja de seguimiento para resaltar fechas vencidas.","Al final de la semana, estima cuánto tiempo ahorraste."],"quiz":[{"pregunta":"¿Qué hace una regla de correo?","opciones":["Filtra y clasifica correos automáticamente","Borra todos los correos","Escribe respuestas largas"],"correcta":0},{"pregunta":"¿Para qué sirve una plantilla?","opciones":["Para no escribir desde cero los mensajes repetidos","Para decorar el correo","Para nada"],"correcta":0},{"pregunta":"¿Qué función resalta visualmente fechas vencidas en una hoja de cálculo?","opciones":["Formato condicional","Imprimir","Ordenar alfabéticamente"],"correcta":0},{"pregunta":"¿Dónde conviene usar la IA dentro de una rutina?","opciones":["En el paso que requiere redactar o resumir","En ninguno","Para decidir por ti"],"correcta":0}],"accion":"Crea hoy una plantilla para el mensaje que más repites."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
