insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Ingresos, costos y márgenes sin tecnicismos","Por qué utilidad no es lo mismo que caja","Endeudamiento: cuándo es sano y cuándo preocupa","Cómo se evalúa una inversión","Cómo hablar de números con un gerente"],"contexto":"No necesitas ser financiero para entender cómo funciona una empresa. Con unos pocos conceptos puedes leer la situación de un negocio, entender qué le preocupa al gerente y conversar con el área financiera sin sentirte fuera de lugar.\n\nEsta habilidad es especialmente valiosa para aliados que no vienen de las finanzas: consultores, líderes gremiales, referidores. La mayoría de decisiones empresariales importantes —invertir, contratar, expandirse, ahorrar— se discuten en el lenguaje de los números. Quien entiende ese lenguaje participa en la conversación; quien no, se queda esperando afuera.","lecciones":[{"titulo":"Ingresos, costos y márgenes","texto":"Lo que entra, lo que cuesta producirlo y lo que queda. El margen dice cuántos pesos quedan por cada $100 vendidos.\n\nEl margen bruto es lo que queda después de restar el costo directo de producir o comprar lo que se vende. El margen operativo descuenta además los gastos de administración y ventas. El margen neto es lo que queda tras intereses e impuestos. Un supermercado puede vivir con márgenes netos de 2% a 3% porque vende mucho volumen; una empresa de software puede tener márgenes de 20% o más. Comparar márgenes solo tiene sentido dentro del mismo sector."},{"titulo":"Utilidad no es caja","texto":"Una empresa puede ganar dinero en el papel y quedarse sin efectivo para pagar la nómina.\n\nLa utilidad se registra cuando se vende, aunque el cliente pague a 90 días. La caja se mueve cuando el dinero realmente entra o sale. Una empresa que crece rápido vendiendo a crédito puede tener utilidades y, al mismo tiempo, problemas de liquidez, porque financia a sus clientes con su propio capital de trabajo. Por eso los gerentes hablan tanto de flujo de caja: es lo que mantiene viva a la empresa."},{"titulo":"Endeudamiento","texto":"La deuda es una herramienta: sana si financia activos que generan más de lo que cuestan, riesgosa si cubre pérdidas.\n\nDos indicadores bastan para empezar: deuda total sobre patrimonio (cuánto financian los acreedores frente a los socios) y la capacidad de pago, medida como EBITDA sobre servicio de la deuda. Si el EBITDA cubre con holgura las cuotas, hay espacio para nueva deuda. Si apenas las cubre, cualquier nueva inversión debe pagarse sola desde el inicio, lo que hace atractivos los proyectos cuyo ahorro supera la cuota."},{"titulo":"Cómo se evalúa una inversión","texto":"Cuánto cuesta, cuánto genera, en cuánto tiempo se recupera y cuánto rinde frente a otras opciones.\n\nLos tres indicadores más usados son el payback (tiempo de recuperación), el VPN (valor que crea en pesos de hoy) y la TIR (rentabilidad anual). Una inversión es atractiva cuando recupera el dinero en un plazo razonable frente a su vida útil y rinde más que el costo de financiarla. No necesitas calcularlos a mano: necesitas entender qué preguntan y cómo se interpretan."},{"titulo":"Hablar de números con un gerente","texto":"Usa sus cifras, redondea, compara y termina con una pregunta.\n\nEn lugar de decir “su margen operativo es 8,37%”, di “de cada $100 que venden, les quedan unos $8 después de operar; ¿cómo lo ven frente al año pasado?”. Los gerentes piensan en órdenes de magnitud, tendencias y comparaciones. Un aliado que habla así parece alguien que entiende el negocio, no alguien que recita un informe."}],"ejercicio":"Lee el estado de resultados de una empresa y explícalo en tres frases a alguien que no sea financiero.","pasos":["Consigue un estado de resultados (de tu empresa, de un cliente o uno público).","Calcula margen bruto, operativo y neto como porcentaje de ventas.","Compáralos con el año anterior e identifica el mayor cambio.","Escribe tres frases que expliquen la situación en lenguaje sencillo.","Formula una pregunta que le harías al gerente sobre ese cambio."],"quiz":[{"pregunta":"¿Qué indica el margen?","opciones":["Cuántos pesos quedan por cada $100 vendidos","El número de clientes","El valor de la empresa"],"correcta":0},{"pregunta":"¿Por qué una empresa rentable puede quedarse sin caja?","opciones":["Porque vende a crédito y financia a sus clientes","Porque la utilidad es caja","No puede ocurrir"],"correcta":0},{"pregunta":"¿Cuándo es sana la deuda?","opciones":["Cuando financia activos que generan más de lo que cuestan","Siempre","Nunca"],"correcta":0},{"pregunta":"¿Cómo conviene hablar de números con un gerente?","opciones":["Con decimales exactos","Con redondeos, comparaciones y una pregunta","Evitando los números"],"correcta":1}],"accion":"En tu próxima conversación con un gerente, usa una cifra de su negocio y termina con una pregunta."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('roi-tir-y-payback-sin-complicaciones', 'ROI, TIR y Payback sin complicaciones', 149, true, 5, 'finanzas', 'micro',
          15, 'Principiante', array['todos']::text[], 'aliado', false, false, true, false,
          null, 'Tres indicadores para hablar de cualquier inversión.', 't-roi', 136, '2026-05-20')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
