insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué pregunta responde cada indicador","Cómo calcularlos con un ejemplo simple","Cuándo usar cada uno","Errores frecuentes al presentarlos"],"contexto":"ROI, TIR y payback son los tres indicadores que más se usan para hablar de cualquier inversión: una máquina, una sede, un software o un sistema solar. Cada uno responde una pregunta distinta y ninguno, por sí solo, cuenta la historia completa.\n\nEntenderlos te permite participar en conversaciones de inversión con gerentes y áreas financieras, revisar propuestas con criterio y explicar decisiones en lenguaje simple. No necesitas fórmulas complejas: una hoja de cálculo y claridad sobre qué mide cada uno es suficiente.","lecciones":[{"titulo":"Payback: ¿en cuánto tiempo recupero?","texto":"Inversión ÷ flujo neto anual. Es el indicador más intuitivo y el preferido por la gerencia general.\n\nSi una inversión de $200 millones libera $50 millones al año, se recupera en 4 años. Es útil como filtro: muchas empresas tienen una regla interna del tipo “solo aprobamos inversiones que se paguen en menos de X años”. Su limitación es que no mide lo que pasa después ni considera el valor del dinero en el tiempo."},{"titulo":"ROI: ¿cuántas veces recupero lo invertido?","texto":"(Ganancia total − inversión) ÷ inversión. Muestra el retorno acumulado como porcentaje.\n\nSi la misma inversión de $200 millones genera $50 millones al año durante 20 años, la ganancia total es $1.000 millones y el ROI es (1.000 − 200) ÷ 200 = 400%. Es fácil de comunicar, pero no dice en cuánto tiempo se logra: un ROI de 400% en 20 años no es lo mismo que en 5. Por eso conviene acompañarlo de un horizonte explícito."},{"titulo":"TIR: ¿cuánto rinde al año?","texto":"La rentabilidad anual equivalente de la inversión. Se compara con el costo de capital o con otras alternativas.\n\nSe calcula con la función TIR de una hoja de cálculo sobre la serie de flujos. Es el indicador favorito del área financiera porque permite comparar inversiones de distinto tamaño y duración. Una TIR del 20% frente a un costo de financiación del 14% indica que la inversión crea valor."},{"titulo":"Cuándo usar cada uno","texto":"Payback para la gerencia, TIR para finanzas, ROI para comunicar la magnitud. Lo ideal es presentar los tres.\n\nUn error frecuente es presentar solo el indicador que mejor luce. Otro es comparar el ROI de proyectos con horizontes distintos. El tercero es olvidar los costos de operación al calcular el flujo. La recomendación práctica: presenta los tres, con los supuestos explícitos, y deja que cada interlocutor mire el que le importa."}],"ejercicio":"Calcula los tres indicadores para una inversión real o de ejemplo.","pasos":["Define una inversión: valor inicial, flujo neto anual y vida útil.","Calcula el payback simple.","Calcula el ROI acumulado durante la vida útil.","En una hoja de cálculo, calcula la TIR con la serie de flujos.","Escribe una frase que explique los tres resultados juntos."],"quiz":[{"pregunta":"¿Qué pregunta responde el payback?","opciones":["¿Cuánto rinde al año?","¿En cuánto tiempo recupero la inversión?","¿Cuál es el valor de la empresa?"],"correcta":1},{"pregunta":"¿Cuál es la principal limitación del ROI?","opciones":["No indica en cuánto tiempo se logra el retorno","No usa la inversión","Solo sirve para bancos"],"correcta":0},{"pregunta":"¿Con qué se compara la TIR?","opciones":["Con el costo de capital o alternativas","Con el payback","Con el número de empleados"],"correcta":0},{"pregunta":"¿Qué recomendación es correcta?","opciones":["Presentar solo el indicador que mejor luce","Presentar los tres con supuestos explícitos","No presentar indicadores"],"correcta":1}],"accion":"Calcula los tres indicadores de una inversión que esté evaluando un cliente o tu empresa."}'::jsonb from m
on conflict (modulo_id) do nothing;
