insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Diferencia entre invertir (CAPEX) y pagar por uso (OPEX)","Efectos en caja, balance e impuestos","Cuándo conviene cada modelo"],"contexto":"Comprar un activo o pagar por usarlo es una de las decisiones más frecuentes en una empresa: vehículos, software, maquinaria y, cada vez más, energía. La elección afecta la caja, el balance, los impuestos y el riesgo.\n\nEn proyectos solares, esta decisión es central: la empresa puede comprar el sistema (CAPEX) y quedarse con todo el ahorro y los incentivos, o pagar por la energía que produce un sistema de un tercero (OPEX), sin invertir. Ninguna opción es mejor en abstracto: depende de las prioridades del cliente.","lecciones":[{"titulo":"CAPEX: invertir en el activo","texto":"La empresa compra el activo, lo registra en su balance y lo deprecia. Asume la inversión y recibe todo el beneficio.\n\nEn un sistema solar comprado, la empresa desembolsa la inversión (con recursos propios o financiación), es dueña del activo, aplica los incentivos tributarios de la Ley 1715 y se queda con el 100% del ahorro durante la vida útil. También asume el mantenimiento y el riesgo de desempeño, aunque estos suelen gestionarse con contratos de operación y garantías."},{"titulo":"OPEX: pagar por uso","texto":"La empresa paga una cuota o un precio por unidad, sin invertir. El gasto se registra en el estado de resultados.\n\nEn un contrato de pago por energía (PPA) o de renting, un tercero invierte, instala, opera y mantiene el sistema. La empresa paga cada kWh a un precio menor que su tarifa, por lo que ahorra desde el primer día sin desembolso inicial. El ahorro total es menor que en compra, porque el inversionista recupera su capital y obtiene un margen, y los incentivos quedan para él."},{"titulo":"Cuándo conviene cada uno","texto":"CAPEX si hay caja o capacidad de crédito y se busca el máximo ahorro. OPEX si se prioriza la liquidez o no se quiere operar activos.\n\nUna empresa rentable, con caja y capacidad de aprovechar la deducción en renta, suele obtener más valor comprando. Una empresa en expansión que necesita su caja para el negocio principal, o que no quiere aumentar su endeudamiento, puede preferir OPEX. La pregunta de diagnóstico es simple: “¿Prefiere maximizar el ahorro o no invertir capital?”."}],"ejercicio":"Compara las dos modalidades para un cliente y recomienda una según su prioridad.","pasos":["Describe la situación de un cliente: caja, endeudamiento y prioridades.","Lista ventajas y desventajas de CAPEX para ese cliente.","Lista ventajas y desventajas de OPEX para ese cliente.","Escribe tu recomendación y la razón en una frase."],"quiz":[{"pregunta":"En un modelo OPEX, ¿quién invierte en el activo?","opciones":["El cliente","Un tercero","Nadie"],"correcta":1},{"pregunta":"¿En qué modelo recibe la empresa todo el ahorro y los incentivos?","opciones":["CAPEX (compra)","OPEX (pago por uso)","En ambos por igual"],"correcta":0},{"pregunta":"¿Cuándo suele convenir OPEX?","opciones":["Cuando se prioriza la liquidez","Cuando sobra caja","Nunca"],"correcta":0}],"accion":"Pregunta a un cliente si prefiere maximizar el ahorro o no invertir capital."}'::jsonb from m
on conflict (modulo_id) do nothing;
