insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["La estructura de una presentación que obtiene un sí","Cómo adaptar el mensaje a cada miembro del comité","Cómo anticipar objeciones","Qué hacer después de la presentación"],"contexto":"Una buena inversión mal presentada se aplaza; una inversión razonable bien presentada se aprueba. La diferencia no está en la cantidad de datos, sino en la claridad de la recomendación y en la anticipación de las preguntas del comité.\n\nLos comités de gerencia tienen poco tiempo, muchas propuestas compitiendo por el mismo capital y una pregunta implícita detrás de cada presentación: ¿por qué esto, por qué ahora y qué pasa si sale mal? La técnica de comunicación ejecutiva conocida como principio de la pirámide, desarrollada por Barbara Minto en McKinsey, propone empezar por la conclusión y luego sustentarla. Es la estructura que mejor funciona frente a una junta.","lecciones":[{"titulo":"Empieza por la recomendación","texto":"En la primera diapositiva o el primer minuto: qué se propone, cuánto cuesta y qué genera.\n\n“Proponemos invertir $500 millones en un sistema solar que reduce 35% la factura de energía y se paga en cinco años.” Con esa frase el comité sabe de qué se trata y puede escuchar el resto con un marco claro. Los detalles técnicos y los supuestos van después, en orden de importancia, y los anexos al final."},{"titulo":"Tres números y una comparación","texto":"Payback, TIR y ahorro acumulado, comparados con una alternativa concreta.\n\nEl comité no recordará diez indicadores. Elige los tres que mejor responden a sus preguntas y compáralos con algo conocido: el costo del crédito, la rentabilidad de su negocio principal o el costo de no hacer nada. “Rinde 21% anual, frente al 15% que pagamos por nuestra deuda” es más poderoso que una tabla de flujos."},{"titulo":"Habla a cada interlocutor","texto":"El gerente general piensa en estrategia, el financiero en caja y riesgo, el de operaciones en continuidad.\n\nPrepara una frase para cada uno. Al gerente general: cómo la inversión mejora la competitividad. Al financiero: cómo se financia y qué pasa en el escenario pesimista. Al de operaciones: cómo se instala sin interrumpir la producción. Si alguien tiene una objeción conocida, respóndela en la presentación antes de que la plantee."},{"titulo":"Anticipa y cierra","texto":"Prepara las cinco preguntas difíciles, define el siguiente paso y envía un resumen en 24 horas.\n\nLas preguntas más comunes son: ¿qué pasa si la tarifa baja?, ¿qué garantías hay?, ¿cómo afecta la cubierta?, ¿por qué este proveedor?, ¿qué pasa si nos mudamos? Ten respuestas cortas para cada una. Cierra pidiendo una decisión o un siguiente paso concreto con fecha, y envía después un resumen de una página con lo acordado."}],"ejercicio":"Estructura la presentación de una inversión real en cinco diapositivas o una página.","pasos":["Escribe la recomendación en una sola frase: qué, cuánto cuesta y qué genera.","Elige los tres números más relevantes y una comparación para cada uno.","Escribe una frase para el gerente general, el financiero y el de operaciones.","Lista las cinco preguntas difíciles y una respuesta corta para cada una.","Define el siguiente paso que pedirás al cierre."],"quiz":[{"pregunta":"¿Con qué debe empezar una presentación ante gerencia?","opciones":["Con la historia de la empresa","Con la recomendación","Con los anexos técnicos"],"correcta":1},{"pregunta":"¿Cuántos números clave conviene destacar?","opciones":["Tres, con una comparación","Veinte","Ninguno"],"correcta":0},{"pregunta":"¿Qué le importa principalmente al gerente financiero?","opciones":["El color de los paneles","Caja, financiación y riesgo","El logo del proveedor"],"correcta":1},{"pregunta":"¿Qué hacer después de presentar?","opciones":["Esperar","Enviar un resumen con acuerdos en 24 horas","Nada"],"correcta":1}],"accion":"Prepara la frase de recomendación de una inversión que estés acompañando."}'::jsonb from m
on conflict (modulo_id) do nothing;
