  values ('como-leer-un-negocio-en-15-minutos', 'Cómo leer un negocio en 15 minutos', 152, true, 5, 'negocios', 'micro',
          15, 'Principiante', array['todos']::text[], 'free', true, false, false, false,
          null, 'Modelo, clientes, costos y riesgos: una lectura rápida y útil.', 't-reunion', 70, '2026-08-14')
