insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las cinco preguntas para entender cualquier negocio","Dónde encontrar la información","Cómo identificar necesidades y oportunidades","Cómo usar la lectura en una conversación"],"contexto":"Antes de una reunión, un ejecutivo, consultor o aliado necesita entender rápidamente cómo funciona el negocio de su interlocutor: qué vende, a quién, cómo gana dinero y qué lo presiona. Esa lectura rápida permite hacer mejores preguntas y detectar oportunidades.\n\nMarcos como el Business Model Canvas de Alexander Osterwalder ayudan a organizar esta lectura. Este microcurso propone una versión simplificada de cinco preguntas que puedes responder en 15 minutos con información pública.","lecciones":[{"titulo":"Las cinco preguntas","texto":"Qué vende, a quién, cómo gana dinero, cuáles son sus costos principales y qué riesgos enfrenta.\n\nQué vende: productos o servicios principales. A quién: tipo de clientes y mercados. Cómo gana dinero: márgenes, volumen, recurrencia. Costos principales: materias primas, personal, energía, logística. Riesgos: competencia, regulación, tipo de cambio, clima. Con estas cinco respuestas tienes una imagen suficiente para una primera conversación."},{"titulo":"Dónde buscar","texto":"Sitio web, LinkedIn, noticias, informes sectoriales y registros públicos.\n\nEl sitio web muestra productos, clientes y presencia geográfica. LinkedIn revela tamaño del equipo, contrataciones recientes y trayectoria de los directivos. Las noticias informan expansiones, premios o dificultades. Los informes de gremios y del DANE dan contexto del sector. En Colombia, el RUES y la Superintendencia de Sociedades ofrecen información de registro y, para muchas empresas, estados financieros."},{"titulo":"Detectar necesidades","texto":"Busca presiones de costos, planes de crecimiento y exigencias externas.\n\nUna empresa con costos de energía relevantes en un sector de márgenes estrechos tiene una presión clara. Una que contrata y abre sedes está creciendo. Una que exporta o vende a multinacionales probablemente enfrenta exigencias de sostenibilidad. Cada una de estas señales es una hipótesis de necesidad para validar en la conversación."},{"titulo":"Usar la lectura","texto":"Abre con lo que sabes, valida con preguntas y deja que el cliente complete el cuadro.\n\n“Vi que están ampliando la planta en Girón y que su sector ha tenido presión en costos. ¿Cómo lo están viviendo?”. Mostrar que hiciste la tarea genera respeto; preguntar en lugar de afirmar evita errores y permite al cliente contarte lo que no está en internet."}],"ejercicio":"Lee un negocio en 15 minutos con las cinco preguntas antes de tu próxima reunión.","pasos":["Elige una empresa con la que te reunirás pronto.","Responde las cinco preguntas con información pública.","Identifica dos hipótesis de necesidad.","Escribe la frase de apertura que muestra tu lectura y termina en pregunta."],"quiz":[{"pregunta":"¿Cuál es una de las cinco preguntas para leer un negocio?","opciones":["¿Cuáles son sus costos principales?","¿De qué color es el logo?","¿Cuántos pisos tiene la sede?"],"correcta":0},{"pregunta":"¿Dónde encontrar estados financieros de muchas empresas colombianas?","opciones":["Superintendencia de Sociedades","Redes sociales personales","En ningún lugar"],"correcta":0},{"pregunta":"¿Qué indica una empresa que contrata y abre sedes?","opciones":["Crecimiento","Crisis","Nada"],"correcta":0},{"pregunta":"¿Cómo usar la lectura en la conversación?","opciones":["Afirmando conclusiones","Abriendo con lo que sabes y validando con preguntas","No mencionándola"],"correcta":1}],"accion":"Lee en 15 minutos el negocio de tu próximo cliente antes de la reunión."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('networking-que-realmente-genera-oportunidades', 'Networking que realmente genera oportunidades', 153, true, 5, 'relaciones', 'micro',
          16, 'Principiante', array['todos']::text[], 'free', false, false, true, false,
          null, 'Qué hacer antes, durante y después de cada encuentro.', 't-red', 128, '2026-09-21')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué hacer antes de un encuentro","Cómo conversar durante el evento","Cómo hacer seguimiento después","Cómo convertir contactos en oportunidades"],"contexto":"La mayoría de las personas sale de un evento con varias tarjetas y ninguna oportunidad. La diferencia entre el networking que genera negocios y el que no está en tres momentos: la preparación previa, la calidad de las conversaciones y, sobre todo, el seguimiento.\n\nEste microcurso te da una rutina simple para cada momento. No requiere ser extrovertido ni dominar la sala: requiere intención, curiosidad genuina y disciplina para hacer seguimiento.","lecciones":[{"titulo":"Antes","texto":"Define a quién quieres conocer, prepara tu presentación en una frase y tres preguntas.\n\nRevisa la agenda, los panelistas y, si es posible, la lista de asistentes. Elige tres personas o perfiles prioritarios. Prepara una presentación breve que diga a quién ayudas y cómo: “Conecto empresas industriales con soluciones para reducir su costo de energía”. Y prepara tres preguntas abiertas sobre el negocio del otro."},{"titulo":"Durante","texto":"Pregunta más de lo que hablas, busca dos o tres conversaciones de calidad y anota algo de cada una.\n\nLas mejores conversaciones de networking empiezan con curiosidad: “¿Qué te trajo a este evento?”, “¿qué está siendo lo más retador para tu empresa este año?”. Escucha con atención y busca un punto en común o una forma de ayudar. Al terminar cada conversación, anota en el celular un dato clave: así el seguimiento será personal."},{"titulo":"Después","texto":"Escribe en 48 horas, con referencia a la conversación y un aporte.\n\n“Hola, [nombre]. Me gustó conversar sobre [tema] en [evento]. Te comparto el dato que te mencioné sobre [tema]. Si te parece útil, podemos tomar un café en las próximas semanas.” Agrega a la persona a tu mapa de red y programa un recordatorio. El seguimiento es lo que convierte un contacto en una relación."},{"titulo":"De contacto a oportunidad","texto":"Aporta valor antes de pedir, y detecta señales en las siguientes conversaciones.\n\nLa oportunidad rara vez aparece en el primer encuentro. Aparece en el segundo o tercer contacto, cuando ya existe confianza. Comparte información útil, haz una introducción, invita a un espacio relevante. Cuando la persona mencione un reto que puedas conectar —por ejemplo, el costo de energía—, ofrece la conexión con GEENERA como un favor."}],"ejercicio":"Aplica la rutina antes–durante–después en tu próximo evento.","pasos":["Elige el próximo evento al que asistirás.","Define tres personas o perfiles prioritarios y tu presentación en una frase.","Prepara tres preguntas abiertas.","Durante el evento, anota un dato clave de cada conversación.","En las 48 horas siguientes, envía mensajes de seguimiento personalizados."],"quiz":[{"pregunta":"¿Qué momento es más importante en el networking?","opciones":["La entrada al evento","El seguimiento posterior","La comida"],"correcta":1},{"pregunta":"¿Cómo empezar una buena conversación?","opciones":["Con tu portafolio","Con una pregunta de curiosidad genuina","Con tu tarjeta"],"correcta":1},{"pregunta":"¿En cuánto tiempo conviene hacer seguimiento?","opciones":["48 horas","Un mes","Nunca"],"correcta":0},{"pregunta":"¿Cuándo suele aparecer la oportunidad?","opciones":["En el primer minuto","En el segundo o tercer contacto, con confianza","Nunca"],"correcta":1}],"accion":"Envía en las próximas 48 horas un seguimiento personalizado a una persona que conociste recientemente."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-pedir-un-referido-sin-incomodar', 'Cómo pedir un referido sin incomodar', 154, true, 5, 'relaciones', 'flash',
          6, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Frases y momentos que hacen natural la petición.', 't-red', 66, '2026-01-01')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["El mejor momento para pedir un referido","Frases que hacen natural la petición","Cómo facilitarle el trabajo a quien te refiere"],"contexto":"Las recomendaciones de personas conocidas siguen siendo una de las fuentes de confianza más poderosas en las decisiones de compra, tanto de consumidores como de empresas. Sin embargo, muchas personas no piden referidos por temor a incomodar o parecer necesitadas.\n\nPedir un referido no incomoda si se hace en el momento correcto, con una petición específica y facilitándole el trabajo a la otra persona. Bien hecho, es una muestra de confianza mutua.","lecciones":[{"titulo":"El momento","texto":"Después de aportar valor: tras un buen resultado, un agradecimiento o una conversación útil.\n\nEl mejor momento para pedir es cuando la otra persona acaba de reconocer el valor de lo que hiciste: un cliente satisfecho, un contacto al que ayudaste o un colega que te agradece una introducción. En ese momento, la petición se siente como una continuación natural de la relación."},{"titulo":"La petición específica","texto":"Pide por un perfil concreto, no “si conoces a alguien”.\n\n“¿Conoces a alguien que necesite…?” obliga a la otra persona a pensar en todo su universo de contactos y suele terminar en “déjame pensarlo”. Es mejor: “¿Conoces a algún gerente de una planta o bodega en la zona que esté preocupado por su costo de energía?”. Un perfil específico activa nombres concretos en la memoria."},{"titulo":"Facilita el trabajo","texto":"Ofrece un mensaje listo para reenviar y confirma que la persona referida acepta el contacto.\n\nSi te dan un nombre, ofrece: “¿Te parece si te envío un mensaje corto que puedas reenviarle?”. Redacta un texto de tres líneas que explique quién eres y por qué podría interesarle. Pide que confirme con su contacto antes de que tú escribas. Después, agradece y cuéntale cómo terminó la conversación."}],"ejercicio":"Pide un referido específico a una persona con quien tengas una relación de confianza.","pasos":["Elige a alguien a quien hayas ayudado recientemente.","Define el perfil concreto de empresa o persona que buscas.","Escribe la petición específica en una frase.","Prepara el mensaje de tres líneas para que pueda reenviarlo."],"quiz":[{"pregunta":"¿Cuál es el mejor momento para pedir un referido?","opciones":["Al conocer a alguien","Después de aportar valor","Nunca"],"correcta":1},{"pregunta":"¿Qué tipo de petición funciona mejor?","opciones":["“Si conoces a alguien…”","Un perfil concreto","Una lista de 50 sectores"],"correcta":1},{"pregunta":"¿Cómo facilitar el trabajo a quien refiere?","opciones":["Con un mensaje listo para reenviar","Pidiéndole que escriba todo","Llamando sin avisar"],"correcta":0}],"accion":"Pide esta semana un referido con un perfil específico y un mensaje listo para reenviar."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-construir-relaciones-con-tomadores-de-decision', 'Cómo construir relaciones con tomadores de decisión', 155, true, 5, 'relaciones', 'curso',
          34, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Acceso, credibilidad y continuidad con la alta dirección.', 't-reunion', 64, '2026-02-08')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Cómo piensan y deciden los altos directivos","Cómo conseguir acceso sin saltarte a tu contacto","Cómo construir credibilidad en pocas interacciones","Cómo mantener la relación en el tiempo","Qué errores cierran puertas"],"contexto":"En las decisiones de inversión de una empresa, el acceso al decisor marca la diferencia entre una oportunidad que avanza y una que se estanca. Pero los gerentes generales, financieros y miembros de junta tienen agendas llenas, filtros estrictos y poca paciencia para conversaciones que no les aportan.\n\nConstruir relaciones con tomadores de decisión no es cuestión de insistencia, sino de relevancia: entender sus prioridades, aportar perspectiva y ser confiable. Este curso combina prácticas de la venta consultiva y de la gestión de cuentas estratégicas para que puedas ganarte un lugar en su agenda.","lecciones":[{"titulo":"Cómo piensan","texto":"Piensan en estrategia, riesgo, tiempo y resultados. Valoran la síntesis y desconfían de la venta.\n\nUn gerente general quiere saber cómo algo afecta el crecimiento y la competitividad. Un financiero, cómo afecta la caja, el retorno y el riesgo. Ambos tienen poco tiempo y muchas propuestas. Por eso valoran a quien llega con una idea clara, datos de su negocio y una propuesta de siguiente paso concreta. El tecnicismo y la presentación genérica los alejan."},{"titulo":"Conseguir acceso","texto":"A través de tu contacto, con una razón de valor para el decisor.\n\nSi hablas con alguien que no decide, no lo saltes: conviértelo en tu aliado. Pregúntale qué le importa a su gerente y pídele que te ayude a presentar la idea: “¿Te parece si preparamos juntos una propuesta para presentársela?”. La introducción de alguien de confianza dentro de la empresa vale más que cualquier correo frío."},{"titulo":"Credibilidad rápida","texto":"Preparación impecable, una perspectiva relevante y respeto absoluto por el tiempo.\n\nLlega sabiendo lo esencial de la empresa y su sector. Abre con una observación relevante: “Revisando su sector, vi que el costo de energía creció más rápido que las ventas”. Respeta el tiempo acordado y termina antes si cumpliste el objetivo. Cumple cualquier compromiso en la fecha exacta. Tres interacciones así construyen más credibilidad que un año de llamadas."},{"titulo":"Mantener la relación","texto":"Contacto periódico con valor: información, introducciones y reconocimiento.\n\nUn decisor recuerda a quien le aporta. Comparte datos del sector, invítalo a espacios relevantes (una masterclass, un desayuno con pares), preséntale a personas útiles y reconoce sus logros. Un contacto cada cuatro a seis semanas, siempre con un motivo, mantiene la relación viva sin desgastarla."},{"titulo":"Errores que cierran puertas","texto":"Saltarse a tu contacto, insistir sin aportar, prometer lo que no controlas o hablar mal de otros.\n\nSaltarse a la persona que te abrió la puerta genera resentimiento interno. Insistir con “¿pudo revisar?” sin aportar algo nuevo desgasta. Prometer resultados que dependen de otros —tasas, tiempos de aprobación, ahorros exactos— compromete tu credibilidad. Y hablar mal de competidores o de otros proveedores hace que el decisor se pregunte qué dirás de él."}],"ejercicio":"Diseña tu plan de relación con un tomador de decisión clave de tu cartera o tu red.","pasos":["Elige un tomador de decisión con quien quieras construir relación.","Escribe sus tres prioridades probables según su cargo y su empresa.","Define cómo conseguirás acceso (directo o a través de un contacto).","Prepara una perspectiva relevante para la primera conversación.","Planea tres contactos de valor para los próximos tres meses."],"quiz":[{"pregunta":"¿Qué valoran los tomadores de decisión?","opciones":["Tecnicismos","Síntesis, perspectiva y siguiente paso claro","Presentaciones largas"],"correcta":1},{"pregunta":"Si tu contacto no decide, ¿qué haces?","opciones":["Te lo saltas","Lo conviertes en aliado para llegar al decisor","Abandonas"],"correcta":1},{"pregunta":"¿Qué construye credibilidad rápida?","opciones":["Preparación, perspectiva y respeto por el tiempo","Insistencia","Regalos"],"correcta":0},{"pregunta":"¿Qué error cierra puertas?","opciones":["Cumplir compromisos","Prometer lo que no controlas","Aportar datos"],"correcta":1}],"accion":"Prepara una perspectiva relevante para tu próxima conversación con un tomador de decisión."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('linkedin-que-genera-conversaciones', 'LinkedIn que genera conversaciones', 156, true, 5, 'marca', 'micro',
          14, 'Principiante', array['todos']::text[], 'free', false, false, false, false,
          null, 'Publicaciones y mensajes que abren diálogos, no solo likes.', 't-linkedin', 62, '2026-03-15')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Publicaciones que invitan a responder","Comentarios que abren puertas","Mensajes que inician conversaciones de negocio","Una rutina semanal sostenible"],"contexto":"El objetivo de LinkedIn para un aliado no es acumular likes, sino iniciar conversaciones con las personas correctas. Una publicación con pocas reacciones pero que genera dos mensajes de gerentes interesados vale más que una viral sin consecuencias.\n\nLas conversaciones nacen de tres prácticas: publicar contenido que invite a opinar, comentar con criterio en las publicaciones de tu audiencia y escribir mensajes privados que continúen esas interacciones. Este microcurso te da fórmulas para cada una.","lecciones":[{"titulo":"Publicaciones que invitan","texto":"Un dato o una experiencia, tu opinión y una pregunta abierta.\n\nLa estructura más efectiva para generar conversación: una primera línea que despierta curiosidad, un dato o una situación concreta, tu punto de vista y una pregunta que invite a compartir experiencias. “Esta semana tres gerentes me dijeron lo mismo: su factura de energía subió más que sus ventas. ¿En su empresa cómo lo están manejando?”. Las preguntas genuinas generan respuestas."},{"titulo":"Comentarios que abren puertas","texto":"Aporta un dato, una experiencia o una pregunta en las publicaciones de tu audiencia.\n\nComentar es una de las formas más subestimadas de construir visibilidad: tu comentario aparece ante la red de la otra persona. Un buen comentario agrega algo: “Coincido. En las empresas de alimentos que conozco, la energía pasó de ser un costo fijo a una variable de riesgo. ¿Han evaluado autogeneración?”. Cinco comentarios de calidad por semana construyen más relaciones que una publicación diaria."},{"titulo":"Mensajes que inician","texto":"Referencia a la interacción, una pregunta y, si hay interés, una propuesta concreta.\n\n“Hola, [nombre]. Gracias por tu comentario sobre el costo de energía. Me quedé pensando en lo que dijiste de [punto]. ¿Cómo lo están viviendo en [empresa]?”. Si la respuesta muestra interés: “¿Te parecería útil una conversación de 15 minutos? Puedo contarte cómo lo han resuelto otras empresas del sector”. Nunca envíes una oferta en el primer mensaje."},{"titulo":"Rutina semanal","texto":"30 minutos: comentar, publicar, responder y escribir.\n\n10 minutos para comentar con criterio en cinco publicaciones de tu audiencia; 10 para publicar o preparar tu próxima publicación; 5 para responder comentarios y mensajes; 5 para escribir a dos personas que interactuaron contigo. Sostener esta rutina durante tres meses produce más resultados que cualquier campaña puntual."}],"ejercicio":"Aplica la rutina semanal de 30 minutos durante dos semanas.","pasos":["Bloquea 30 minutos semanales en tu calendario.","Comenta con criterio en cinco publicaciones de tu audiencia.","Publica una vez con la estructura dato–opinión–pregunta.","Responde todos los comentarios recibidos.","Escribe a dos personas que interactuaron contigo."],"quiz":[{"pregunta":"¿Cuál es el objetivo de LinkedIn para un aliado?","opciones":["Acumular likes","Iniciar conversaciones con las personas correctas","Ser viral"],"correcta":1},{"pregunta":"¿Qué debe tener una publicación que invita a conversar?","opciones":["Una pregunta abierta genuina","Muchos hashtags","Solo una foto"],"correcta":0},{"pregunta":"¿Qué no debes hacer en el primer mensaje privado?","opciones":["Hacer una pregunta","Enviar una oferta","Referenciar la interacción"],"correcta":1},{"pregunta":"¿Cuánto tiempo semanal propone la rutina?","opciones":["30 minutos","10 horas","Ninguno"],"correcta":0}],"accion":"Comenta con criterio en cinco publicaciones de tu audiencia esta semana."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-publicar-sin-convertirte-en-influencer', 'Cómo publicar sin convertirte en influencer', 157, true, 5, 'marca', 'flash',
          7, 'Principiante', array['todos']::text[], 'aliado', false, true, false, false,
          null, 'Una rutina simple y auténtica para mostrar tu criterio.', 't-linkedin', 60, '2026-04-22')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Por qué publicar aunque no quieras ser influencer","Una rutina simple y auténtica","Qué publicar cuando no sabes qué publicar"],"contexto":"Muchos profesionales no publican porque no quieren parecer influencers, exponerse o dedicar horas a las redes. Es comprensible. Pero publicar con criterio no tiene nada que ver con ser influencer: es mostrar cómo piensas a las personas que podrían trabajar contigo.\n\nUna o dos publicaciones útiles por semana, con tu experiencia real, son suficientes para que tu audiencia te recuerde y te asocie con un tema.","lecciones":[{"titulo":"Por qué publicar","texto":"Para que tu red recuerde a qué te dedicas y te tenga en cuenta cuando surja la necesidad.\n\nLa mayoría de tus contactos no sabe exactamente qué haces o lo olvidó. Una publicación ocasional sobre tu trabajo —un aprendizaje, una pregunta frecuente, un caso— les recuerda tu tema. Cuando alguien en su entorno necesite reducir su costo de energía, pensará en ti."},{"titulo":"Una rutina simple","texto":"Dos publicaciones por semana, 20 minutos cada una, con tu voz.\n\nNo necesitas producción ni diseño: un texto breve con una idea clara es suficiente. Escribe como hablas, sin frases de cliché ni emojis excesivos. Si te cuesta empezar, usa la IA para pasar de notas a borrador, pero edítalo para que suene a ti. La constancia vale más que la perfección."},{"titulo":"Qué publicar","texto":"Preguntas de clientes, aprendizajes, errores comunes, datos con opinión y reconocimientos.\n\nCada semana escuchas preguntas, ves errores y aprendes algo: eso es contenido. “Un gerente me preguntó esta semana si la energía solar funciona en Bogotá. La respuesta corta es sí, y te explico por qué.” Reconocer el trabajo de un cliente o un aliado también es una publicación valiosa y generosa."}],"ejercicio":"Escribe y publica dos publicaciones esta semana con la rutina simple.","pasos":["Anota tres preguntas que te hicieron clientes o contactos recientemente.","Elige una y escribe una respuesta breve con tu experiencia.","Revisa que suene a ti y publícala.","Repite con un aprendizaje o un reconocimiento."],"quiz":[{"pregunta":"¿Para qué publicar si no quieres ser influencer?","opciones":["Para que tu red recuerde a qué te dedicas","Para ser famoso","No sirve"],"correcta":0},{"pregunta":"¿Cuántas publicaciones por semana bastan?","opciones":["Una o dos útiles","Diez","Ninguna"],"correcta":0},{"pregunta":"¿Qué es buen contenido?","opciones":["Preguntas de clientes y aprendizajes reales","Frases genéricas","Solo fotos"],"correcta":0}],"accion":"Publica esta semana la respuesta a una pregunta que te hizo un cliente."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('ia-para-crear-contenido-profesional', 'IA para crear contenido profesional', 158, true, 5, 'marca', 'micro',
          16, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'De la idea al post en tu propia voz.', 't-prompts', 58, '2026-05-02')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["De la idea al post con IA, en tu propia voz","Cómo enseñarle tu estilo a la IA","Cómo generar ideas a partir de tu experiencia","Cómo editar para evitar el contenido genérico"],"contexto":"La IA puede convertir una idea en un borrador en segundos, pero también puede producir contenido genérico, lleno de frases de cliché, que todos reconocen como escrito por una máquina. La diferencia está en lo que tú aportas: experiencia, opinión y estilo.\n\nUsada bien, la IA reduce el tiempo de producción de contenido de horas a minutos y te permite publicar con constancia. Este microcurso te enseña a usarla como un editor que acelera tu trabajo, no como un reemplazo de tu voz.","lecciones":[{"titulo":"Empieza por tu experiencia","texto":"La IA redacta; tú aportas la historia, el dato y la opinión.\n\nAntes de pedir un post, escribe en notas rápidas qué pasó, qué aprendiste y qué opinas. “Reunión con gerente de planta de alimentos. Factura subió 30% en un año. No sabía que podía autogenerar. Aprendizaje: la mayoría no conoce la opción.” Con ese material, la IA tiene algo real con qué trabajar."},{"titulo":"Enséñale tu estilo","texto":"Pega dos o tres publicaciones tuyas y pide que imite el tono, la extensión y la estructura.\n\n“Estas son tres publicaciones que escribí y me gustan. Escribe un post sobre [tema] con base en estas notas, imitando mi tono, extensión y estructura. Sin emojis, sin hashtags genéricos, sin frases como ‘en el mundo actual’.” Guarda esta instrucción en tus instrucciones personalizadas o en un asistente para no repetirla."},{"titulo":"Genera ideas","texto":"Pide ideas basadas en las preguntas reales de tu audiencia.\n\n“Soy [rol] y mi audiencia son [perfil]. Estas son preguntas que me hacen con frecuencia: [lista]. Dame diez ideas de publicaciones, cada una con un ángulo propio y una primera línea que despierte curiosidad.” Elige las que conecten con tu experiencia; descarta las que no podrías sustentar."},{"titulo":"Edita sin piedad","texto":"Elimina relleno, clichés y afirmaciones que no puedas respaldar.\n\nRevisa cada borrador con tres preguntas: ¿esto lo diría yo en una conversación?, ¿cada frase aporta algo?, ¿hay algún dato que deba verificar? Elimina adjetivos exagerados, frases de transición vacías y conclusiones obvias. Un post de 120 palabras con una idea clara funciona mejor que uno de 300 con relleno."}],"ejercicio":"Escribe con IA una publicación basada en una experiencia real, en tu voz.","pasos":["Escribe notas rápidas de una experiencia reciente: qué pasó, qué aprendiste, qué opinas.","Pega dos publicaciones tuyas como ejemplo de estilo.","Pide el borrador con restricciones de tono y extensión.","Edita con las tres preguntas de revisión.","Publica y anota las reacciones y conversaciones generadas."],"quiz":[{"pregunta":"¿Qué aporta la persona en el contenido creado con IA?","opciones":["Nada","Experiencia, opinión y estilo","Solo la foto"],"correcta":1},{"pregunta":"¿Cómo enseñarle tu estilo a la IA?","opciones":["Pegando ejemplos de tus publicaciones","Pidiendo “escribe bonito”","No se puede"],"correcta":0},{"pregunta":"¿Qué eliminar al editar?","opciones":["Relleno, clichés y afirmaciones sin respaldo","Tu opinión","Los datos verificados"],"correcta":0},{"pregunta":"¿Qué funciona mejor?","opciones":["120 palabras con una idea clara","300 palabras con relleno","Solo hashtags"],"correcta":0}],"accion":"Guarda una instrucción con ejemplos de tu estilo para crear contenido con IA."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('social-selling-b2b', 'Social Selling B2B', 159, true, 5, 'marca', 'curso',
          36, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          null, 'Construye pipeline desde las redes profesionales.', 't-linkedin', 56, '2026-06-09')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es el social selling y por qué funciona en B2B","Los cuatro pilares: marca, búsqueda, interacción y relación","Cómo construir pipeline desde las redes profesionales","Cómo integrar el social selling con tu proceso comercial","Cómo medir resultados"],"contexto":"El social selling es el uso de las redes profesionales para encontrar, entender y relacionarse con clientes potenciales. No es publicidad ni envío masivo de mensajes: es la versión digital de la venta consultiva, basada en relaciones y en aportar valor.\n\nFunciona porque el comprador B2B ha cambiado. Investiga por su cuenta antes de hablar con un proveedor, revisa perfiles, lee contenidos y pide referencias en su red. LinkedIn estructuró este enfoque en su Social Selling Index, con cuatro pilares que organizan este curso. Para un aliado, el social selling permite detectar oportunidades y llegar a decisores que de otra forma serían inaccesibles.","lecciones":[{"titulo":"Marca profesional","texto":"Un perfil que comunica qué resuelves y contenido que demuestra criterio.\n\nEl primer pilar es que, cuando un cliente potencial revise tu perfil, encuentre a alguien relevante para su problema. Titular claro, sección “Acerca de” orientada al cliente, destacados con casos o contenidos útiles y publicaciones regulares sobre tu tema. Sin este pilar, los demás pierden fuerza."},{"titulo":"Encontrar a las personas correctas","texto":"Búsquedas por cargo, sector, ciudad y tamaño de empresa; listas de cuentas objetivo.\n\nLa búsqueda de LinkedIn permite filtrar por cargo, empresa, ubicación y sector. Construye una lista de 30 a 50 cuentas objetivo (empresas con señales de oportunidad) e identifica en cada una a los decisores y a los influenciadores. Herramientas como Sales Navigator amplían estas capacidades, pero la versión gratuita es suficiente para empezar."},{"titulo":"Interactuar con información","texto":"Comparte y comenta contenido relevante para tu audiencia; usa las señales de actividad.\n\nCuando un decisor publica sobre un reto, cambia de cargo o su empresa anuncia una expansión, es una señal para interactuar. Comenta con criterio, comparte un dato útil o felicita con una pregunta. Estas interacciones calientan la relación antes del primer mensaje privado."},{"titulo":"Construir relaciones","texto":"Pasa de la interacción pública a la conversación privada y luego a la reunión.\n\nLa secuencia típica: conectar con una nota personalizada, interactuar con su contenido durante unas semanas, enviar un mensaje con una pregunta relevante y, si hay interés, proponer una conversación breve. Cada paso aporta algo. El objetivo no es vender por LinkedIn, sino conseguir una conversación de calidad."},{"titulo":"Integrar y medir","texto":"Registra las oportunidades originadas en redes y mide conversaciones, reuniones y referidos.\n\nEl social selling no reemplaza tu proceso comercial: lo alimenta. Registra en tu hoja o CRM qué conversaciones nacieron en LinkedIn y en qué terminaron. Cada mes, revisa: conexiones relevantes nuevas, conversaciones iniciadas, reuniones agendadas y referidos generados. Ajusta tu enfoque según los resultados."}],"ejercicio":"Construye una lista de 20 cuentas objetivo e inicia la secuencia de social selling con cinco decisores.","pasos":["Define los criterios de tu cuenta objetivo (sector, tamaño, ciudad, señales).","Construye una lista de 20 empresas que los cumplan.","Identifica en cada una al decisor y a un influenciador.","Conecta con cinco decisores con una nota personalizada.","Interactúa con su contenido durante dos semanas y luego envía un mensaje con una pregunta relevante."],"quiz":[{"pregunta":"¿Qué es el social selling?","opciones":["Publicidad masiva","Usar redes profesionales para encontrar, entender y relacionarse con clientes","Enviar spam"],"correcta":1},{"pregunta":"¿Cuáles son los cuatro pilares del SSI?","opciones":["Marca, búsqueda, interacción y relaciones","Likes, fotos, videos y hashtags","Precio, producto, plaza y promoción"],"correcta":0},{"pregunta":"¿Cuál es el objetivo del social selling?","opciones":["Vender por mensaje directo","Conseguir una conversación de calidad","Tener más seguidores"],"correcta":1},{"pregunta":"¿Qué señal invita a interactuar con un decisor?","opciones":["Un anuncio de expansión de su empresa","Su fecha de nacimiento","Nada"],"correcta":0}],"accion":"Construye tu lista de 20 cuentas objetivo esta semana."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('5-prompts-que-te-ahorraran-tiempo-esta-semana', '5 prompts que te ahorrarán tiempo esta semana', 160, true, 5, 'ia', 'flash',
          5, 'Principiante', array['todos']::text[], 'free', false, false, true, true,
          null, 'Cinco instrucciones listas para copiar y usar en tu trabajo diario.', 't-prompts', 114, '2026-07-16')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Cinco prompts probados para tareas frecuentes","Cómo adaptarlos a tu contexto","Cómo guardarlos para reutilizarlos"],"contexto":"No necesitas dominar la IA para empezar a ahorrar tiempo. Cinco instrucciones bien diseñadas, adaptadas a tu trabajo, pueden ahorrarte varias horas desde esta semana.\n\nEstos prompts siguen la estructura de cuatro bloques —contexto, objetivo, restricciones y formato— y tienen espacios entre corchetes para tu información. Funcionan en ChatGPT, Claude, Gemini o Copilot.","lecciones":[{"titulo":"Correo y resumen","texto":"Prompt 1 · Correo: “Escribe un correo de máximo 120 palabras a [cargo] de [empresa] para [objetivo]. Tono cercano y profesional. Dame dos versiones de asunto.”\n\nPrompt 2 · Resumen: “Resume este documento en tres ideas principales, cifras clave con su página y preguntas abiertas. No incluyas nada que no esté en el texto.” Son los dos prompts que más tiempo ahorran porque se usan casi todos los días."},{"titulo":"Reunión y acta","texto":"Prompt 3 · Preparación: “Voy a reunirme con [cargo] de [empresa], sector [sector]. Dame un perfil con información pública, tres hipótesis de necesidad y cinco preguntas de diagnóstico. Marca las suposiciones.”\n\nPrompt 4 · Acta: “Con estas notas, escribe un acta con decisiones, compromisos (responsable y fecha) y pendientes, y un correo de seguimiento de 100 palabras.” Juntos cubren el antes y el después de cada reunión."},{"titulo":"Objeción","texto":"Prompt 5 · Objeción: “Un cliente me dijo: ‘[objeción]’. Dame tres respuestas que empiecen con una pregunta, reconozcan su punto y aporten un dato nuevo.”\n\nEste prompt te prepara para las conversaciones difíciles. Úsalo antes de una reunión donde esperas resistencia. Guarda los cinco prompts en un documento o en las instrucciones de tu herramienta con tu contexto ya escrito: la segunda vez tomarán 30 segundos."}],"ejercicio":"Adapta los cinco prompts a tu contexto y úsalos al menos una vez cada uno esta semana.","pasos":["Copia los cinco prompts en un documento.","Reemplaza los corchetes con tu información habitual.","Usa cada uno en una tarea real esta semana.","Anota cuánto tiempo ahorraste con cada uno."],"quiz":[{"pregunta":"¿Qué estructura siguen estos prompts?","opciones":["Contexto, objetivo, restricciones y formato","Solo una palabra","Una pregunta abierta"],"correcta":0},{"pregunta":"¿Para qué sirve el prompt de objeción?","opciones":["Para prepararte para conversaciones difíciles","Para discutir","Para evitar al cliente"],"correcta":0},{"pregunta":"¿Qué conviene hacer con los prompts que funcionan?","opciones":["Olvidarlos","Guardarlos con tu contexto ya escrito","Publicarlos sin revisar"],"correcta":1}],"accion":"Guarda hoy los cinco prompts adaptados a tu trabajo."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-investigar-una-empresa-antes-de-una-reunion', 'Cómo investigar una empresa antes de una reunión', 161, true, 5, 'negocios', 'flash',
          4, 'Principiante', array['todos']::text[], 'free', false, false, false, true,
          null, 'Diez minutos de investigación que cambian el resultado de una reunión.', 't-reunion', 52, '2026-08-23')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué investigar en diez minutos","Fuentes rápidas y confiables","Cómo convertir la investigación en preguntas"],"contexto":"Llegar a una reunión sin saber nada de la empresa es una señal de poco interés. Llegar sabiendo lo esencial genera respeto y permite que la conversación empiece en un nivel más profundo.\n\nNo necesitas horas: diez minutos bien usados son suficientes para conocer lo básico, identificar una noticia relevante y preparar preguntas inteligentes.","lecciones":[{"titulo":"Qué investigar","texto":"Qué hace la empresa, novedades recientes, la persona con quien te reúnes y su sector.\n\nCuatro preguntas guían la investigación: ¿qué vende y a quién?, ¿qué ha pasado en el último año (expansión, premios, cambios)?, ¿quién es la persona y cuál es su trayectoria?, ¿qué está pasando en su sector? Con estas respuestas puedes abrir la conversación con algo relevante."},{"titulo":"Fuentes rápidas","texto":"Sitio web, LinkedIn, noticias y una búsqueda del sector.\n\nDos minutos en el sitio web, tres en LinkedIn (empresa y persona), tres en noticias recientes y dos en una búsqueda sobre tendencias del sector. Si usas IA para acelerar la búsqueda, verifica los datos antes de mencionarlos: una noticia equivocada daña la credibilidad."},{"titulo":"De la investigación a preguntas","texto":"Convierte cada hallazgo en una pregunta abierta.\n\n“Vi que abrieron una nueva línea de producción. ¿Cómo ha cambiado eso su operación?”. “Su sector ha tenido presión en costos de energía. ¿Es algo que están viendo?”. Las preguntas basadas en tu investigación muestran interés y llevan la conversación a los temas que importan."}],"ejercicio":"Investiga en diez minutos la empresa de tu próxima reunión y prepara tres preguntas.","pasos":["Revisa el sitio web y anota qué vende y a quién.","Revisa LinkedIn de la empresa y de la persona.","Busca una noticia del último año.","Escribe tres preguntas basadas en lo que encontraste."],"quiz":[{"pregunta":"¿Cuánto tiempo basta para investigar lo esencial?","opciones":["Diez minutos bien usados","Tres horas","No es necesario"],"correcta":0},{"pregunta":"¿Qué hacer con los datos encontrados con IA?","opciones":["Verificarlos antes de mencionarlos","Usarlos sin revisar","Ignorarlos"],"correcta":0},{"pregunta":"¿En qué convertir cada hallazgo?","opciones":["En una pregunta abierta","En una afirmación","En una oferta"],"correcta":0}],"accion":"Investiga diez minutos antes de tu próxima reunión y llega con tres preguntas."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
