  values ('roi-vs-payback', 'ROI vs. Payback', 162, true, 5, 'finanzas', 'flash',
          5, 'Principiante', array['todos']::text[], 'free', false, false, false, true,
          null, 'Un contenido práctico de Finanzas para Negocios para aplicar esta misma semana.', 't-roi', 50, '2026-09-03')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["La diferencia entre retorno total y tiempo de recuperación","Por qué uno sin el otro engaña","Cómo presentarlos juntos"],"contexto":"ROI y payback son los dos indicadores más usados en conversaciones informales de inversión, y también los que más se confunden. El primero mide cuánto se gana en total; el segundo, qué tan rápido se recupera lo invertido.\n\nUsarlos juntos evita dos errores comunes: elegir una inversión que se recupera rápido pero genera poco, o una que genera mucho pero tarda demasiado para la realidad de la empresa.","lecciones":[{"titulo":"Qué mide cada uno","texto":"ROI: retorno total como porcentaje de la inversión. Payback: años necesarios para recuperarla.\n\nUna inversión de $100 millones que genera $25 millones al año durante 20 años tiene un payback de 4 años y un ROI de 400%. Otra que genera $40 millones al año durante 3 años tiene un payback de 2,5 años y un ROI de solo 20%. La segunda se recupera más rápido; la primera crea mucho más valor."},{"titulo":"El error de usar solo uno","texto":"Solo payback favorece lo rápido y pequeño; solo ROI ignora el tiempo y el riesgo.\n\nUna empresa con caja ajustada puede preferir un payback corto, aunque el ROI sea menor. Una empresa sólida que piensa a largo plazo debería mirar el ROI y la TIR. Conocer la prioridad del cliente te permite enfatizar el indicador correcto sin ocultar el otro."},{"titulo":"Presentarlos juntos","texto":"“Se recupera en X años y, durante su vida útil, retorna Y veces la inversión.”\n\nEsta frase combina velocidad y magnitud. En un sistema solar, suele sonar así: “Se paga en unos cinco años y, en 25 años de vida útil, devuelve varias veces lo invertido”. Es la forma más clara de mostrar que la inversión es tanto prudente como rentable."}],"ejercicio":"Calcula ROI y payback de dos inversiones distintas y decide cuál recomendarías y por qué.","pasos":["Define dos inversiones con distinto flujo anual y vida útil.","Calcula el payback y el ROI de cada una.","Escribe cuál recomendarías a una empresa con caja ajustada.","Escribe cuál recomendarías a una empresa sólida de largo plazo."],"quiz":[{"pregunta":"¿Qué mide el payback?","opciones":["El retorno total","El tiempo de recuperación","La tasa de interés"],"correcta":1},{"pregunta":"Una inversión con payback corto…","opciones":["Siempre crea más valor","No necesariamente crea más valor","Nunca es buena"],"correcta":1},{"pregunta":"¿Cuál es la forma más clara de presentarlos?","opciones":["Solo el ROI","Juntos: tiempo de recuperación y retorno total","Solo el payback"],"correcta":1}],"accion":"Explica una inversión con la frase que combina payback y ROI."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
