  values ('como-pedir-una-introduccion-sin-incomodar', 'Cómo pedir una introducción sin incomodar', 163, true, 5, 'relaciones', 'flash',
          4, 'Principiante', array['todos']::text[], 'free', false, false, false, true,
          null, 'Un contenido práctico de Relaciones & Ventas para aplicar esta misma semana.', 't-diag', 48, '2026-01-10')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
