insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Cuándo y a quién pedir una introducción","Cómo formular la petición","Cómo facilitarla y agradecerla"],"contexto":"Una introducción de alguien de confianza es la forma más efectiva de llegar a una persona que no conoces: la recomendación transfiere credibilidad y aumenta mucho la probabilidad de respuesta frente a un mensaje en frío.\n\nPedirla bien es un arte simple: elegir a la persona correcta, explicar con claridad por qué quieres conocer a alguien y facilitarle el trabajo a quien te ayuda.","lecciones":[{"titulo":"A quién pedir","texto":"A alguien con buena relación con ambas partes y que entienda por qué quieres la conexión.\n\nRevisa en LinkedIn los contactos en común con la persona que quieres conocer y elige al que tenga la relación más cercana con ella, no necesariamente el más importante. Pregúntate si esa persona estaría cómoda haciendo la introducción y si entiende el valor que puedes aportar."},{"titulo":"Cómo pedir","texto":"Explica a quién quieres conocer, por qué, y qué gana esa persona.\n\n“Vi que conoces a [nombre], gerente de [empresa]. Estoy trabajando con empresas de su sector que han reducido su costo de energía con autogeneración solar y creo que le podría interesar. ¿Estarías cómodo presentándonos?” Ofrece siempre una salida fácil: “Si no es el momento, no te preocupes”."},{"titulo":"Facilitar y agradecer","texto":"Envía un párrafo listo para reenviar y cuenta después cómo resultó.\n\nRedacta un texto breve sobre ti y el motivo de la conexión para que tu contacto lo reenvíe con mínima edición. Después de la conversación, agradécele y cuéntale el resultado, aunque no haya oportunidad. Ese cierre hace que la próxima vez te ayude con gusto."}],"ejercicio":"Pide una introducción a una persona que quieras conocer este mes.","pasos":["Identifica a la persona que quieres conocer y por qué.","Busca contactos en común y elige al más cercano a ella.","Escribe la petición con motivo y salida fácil.","Prepara el párrafo listo para reenviar."],"quiz":[{"pregunta":"¿A quién conviene pedir una introducción?","opciones":["Al contacto más importante","Al que tiene mejor relación con ambas partes","A cualquiera"],"correcta":1},{"pregunta":"¿Qué debe incluir la petición?","opciones":["A quién, por qué y qué gana esa persona","Solo el nombre","Una exigencia"],"correcta":0},{"pregunta":"¿Qué hacer después de la conversación?","opciones":["Nada","Agradecer y contar el resultado","Pedir otra introducción de inmediato"],"correcta":1}],"accion":"Pide esta semana una introducción con un párrafo listo para reenviar."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-escribir-un-whatsapp-profesional', 'Cómo escribir un WhatsApp profesional', 164, true, 5, 'marca', 'flash',
          3, 'Principiante', array['todos']::text[], 'free', false, true, false, true,
          null, 'Un contenido práctico de Marca & Crecimiento Profesional para aplicar esta misma semana.', 't-linkedin', 46, '2026-02-17')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las reglas de un mensaje profesional por WhatsApp","Estructura de un mensaje que se responde","Qué evitar"],"contexto":"En Colombia, WhatsApp es el canal de comunicación más usado, también en los negocios. Un buen mensaje puede abrir una conversación que un correo no lograría; uno malo puede parecer invasivo o poco profesional.\n\nLa clave está en la brevedad, el contexto y una pregunta fácil de responder.","lecciones":[{"titulo":"Las reglas","texto":"Breve, con contexto, en horario laboral y con un propósito claro.\n\nPresenta quién eres y por qué escribes en la primera línea si no te conocen. Escribe en horario laboral. Evita audios largos en un primer contacto: muchas personas prefieren leer. Un mensaje profesional cabe en la pantalla sin desplazarse."},{"titulo":"La estructura","texto":"Saludo con nombre, contexto, propósito y una pregunta fácil.\n\n“Hola, [nombre]. Soy [tu nombre]; nos presentó [contacto]. Te escribo porque estamos ayudando a empresas como [empresa] a reducir su costo de energía con autogeneración solar. ¿Te parecería útil que un especialista revise tu factura sin compromiso?” Cuatro líneas, una pregunta y la puerta abierta."},{"titulo":"Qué evitar","texto":"Cadenas, mensajes sin contexto, insistencia y archivos pesados sin aviso.\n\nNo envíes “Hola” y esperes respuesta para explicar el motivo. No mandes varios mensajes seguidos si no responden; espera unos días y haz un seguimiento con valor. Antes de enviar una presentación o un PDF, pregunta si es un buen canal para recibirlo."}],"ejercicio":"Reescribe tu mensaje de WhatsApp de primer contacto con la estructura de cuatro partes.","pasos":["Toma el último mensaje de primer contacto que enviaste.","Reescríbelo con saludo, contexto, propósito y pregunta.","Verifica que quepa en una pantalla.","Guárdalo como respuesta rápida en WhatsApp Business."],"quiz":[{"pregunta":"¿Qué debe tener la primera línea si no te conocen?","opciones":["Quién eres y por qué escribes","Un audio largo","Un emoji"],"correcta":0},{"pregunta":"¿Con qué debe terminar el mensaje?","opciones":["Con una pregunta fácil de responder","Con un archivo pesado","Sin cierre"],"correcta":0},{"pregunta":"¿Qué evitar?","opciones":["Enviar “Hola” sin contexto y esperar","Ser breve","Escribir en horario laboral"],"correcta":0}],"accion":"Guarda tu mensaje de primer contacto como respuesta rápida en WhatsApp Business."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('3-senales-de-una-oportunidad-comercial', '3 señales de una oportunidad comercial', 165, true, 5, 'relaciones', 'flash',
          5, 'Principiante', array['todos']::text[], 'aliado', false, false, false, true,
          null, 'Un contenido práctico de Relaciones & Ventas para aplicar esta misma semana.', 't-diag', 44, '2026-03-24')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las tres señales que indican una oportunidad real","Cómo detectarlas en una conversación","Qué hacer cuando aparecen"],"contexto":"No toda conversación interesante es una oportunidad. Muchas personas invierten tiempo en contactos que nunca avanzarán, mientras dejan pasar señales claras en otros.\n\nTres señales, presentes al mismo tiempo, suelen indicar una oportunidad real: un problema reconocido, una capacidad de decisión y un momento propicio. Aprender a detectarlas te ayuda a enfocar tu tiempo.","lecciones":[{"titulo":"Problema reconocido","texto":"La persona reconoce que tiene un problema y le importa resolverlo.\n\nNo basta con que tú veas el problema: la persona debe reconocerlo. “La energía nos está costando muchísimo” es un problema reconocido; “pagamos lo normal” no lo es. Cuando el problema está reconocido, la conversación avanza sola. Si no lo está, tu trabajo es ayudar a dimensionarlo con preguntas, no convencer."},{"titulo":"Capacidad de decisión","texto":"Hablas con quien decide o con quien puede llevarte a quien decide.\n\nUn problema reconocido por alguien sin influencia rara vez avanza. Identifica si tu interlocutor decide, influye o solo opera. Si no decide, pregunta: “¿Cómo toman normalmente este tipo de decisiones?” y pide una introducción al decisor."},{"titulo":"Momento propicio","texto":"Hay un detonante que hace que actuar ahora tenga sentido.\n\nUn aumento reciente de la tarifa, una expansión, un nuevo cliente que exige metas de sostenibilidad o un presupuesto de inversión en preparación son detonantes. Sin momento, la oportunidad queda para “más adelante”. Cuando las tres señales coinciden, refiere esta semana."}],"ejercicio":"Evalúa tus tres conversaciones comerciales más recientes con las tres señales.","pasos":["Lista tus tres conversaciones comerciales más recientes.","Marca en cada una si hay problema reconocido, capacidad de decisión y momento propicio.","Para las que tengan las tres, define el siguiente paso de esta semana.","Para las que no, identifica qué señal falta."],"quiz":[{"pregunta":"¿Cuál es la primera señal?","opciones":["Un problema reconocido por la persona","Un logo bonito","Un correo"],"correcta":0},{"pregunta":"Si tu interlocutor no decide, ¿qué haces?","opciones":["Preguntar cómo deciden y pedir introducción","Abandonar","Insistir"],"correcta":0},{"pregunta":"¿Qué es un momento propicio?","opciones":["Un detonante que hace sensato actuar ahora","Un viernes","Cualquier momento"],"correcta":0}],"accion":"Identifica una conversación con las tres señales y define su siguiente paso."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-resumir-un-pdf-con-ia', 'Cómo resumir un PDF con IA', 166, true, 5, 'ia', 'flash',
          4, 'Principiante', array['todos']::text[], 'aliado', false, false, false, true,
          null, 'De 40 páginas a una tabla útil en minutos, sin perder precisión.', 't-prompts', 42, '2026-04-04')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["La instrucción que produce resúmenes útiles","Cómo pedir citas y verificar","Cómo adaptar el resumen a tu propósito"],"contexto":"Leer un documento de 40 páginas puede tomar una hora; resumirlo con IA, dos minutos. Pero un resumen genérico rara vez es útil: lo valioso es un resumen estructurado para tu propósito, con las cifras citadas para poder verificarlas.\n\nEste flash te da una instrucción probada y la forma de adaptarla a informes, contratos, propuestas o estudios sectoriales.","lecciones":[{"titulo":"La instrucción base","texto":"Estructura la salida: ideas principales, cifras con página, implicaciones y preguntas abiertas.\n\n“Resume este documento en: 1) cinco ideas principales, 2) una tabla con las cifras relevantes y su página, 3) implicaciones para [tu contexto], 4) preguntas que el documento no responde. No incluyas información que no esté en el texto.” Esta estructura convierte un documento en una herramienta de decisión."},{"titulo":"Citas y verificación","texto":"Pide siempre la página de cada dato y revisa al menos tres cifras en el original.\n\nLos modelos pueden confundir cifras o atribuir afirmaciones a la sección equivocada. Pedir la página te permite revisar rápido. Si una cifra no coincide, revisa el resumen completo. En documentos legales o financieros, verifica todo lo que vayas a usar en una decisión o comunicación."},{"titulo":"Adapta al propósito","texto":"Un contrato pide obligaciones y riesgos; un informe, tendencias; una propuesta, alcance y exclusiones.\n\nPara un contrato: “Lista obligaciones de cada parte, plazos, penalidades y cláusulas de terminación”. Para una propuesta: “Resume alcance, entregables, precio, exclusiones y garantías”. Para un informe sectorial: “Tendencias, cifras clave y oportunidades para empresas de [sector]”. La pregunta define la utilidad del resumen."}],"ejercicio":"Resume un PDF real con la instrucción base y verifica tres cifras.","pasos":["Elige un PDF que necesites leer esta semana.","Adapta la instrucción base a tu propósito.","Pide el resumen con cita de página.","Verifica tres cifras en el documento original."],"quiz":[{"pregunta":"¿Qué hace útil un resumen?","opciones":["Que sea genérico","Que esté estructurado para tu propósito y con citas","Que sea muy largo"],"correcta":1},{"pregunta":"¿Para qué pedir la página de cada dato?","opciones":["Para verificar rápido","Para que sea más largo","No sirve"],"correcta":0},{"pregunta":"Al resumir un contrato conviene pedir…","opciones":["Obligaciones, plazos, penalidades y terminación","Solo el título","Una opinión"],"correcta":0}],"accion":"Resume con IA el próximo documento largo que recibas y verifica las cifras clave."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-preparar-una-reunion-con-un-ceo', 'Cómo preparar una reunión con un CEO', 167, true, 5, 'relaciones', 'flash',
          5, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, true,
          null, 'Un contenido práctico de Relaciones & Ventas para aplicar esta misma semana.', 't-reunion', 40, '2026-05-11')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué espera un CEO de una reunión","Cómo prepararla en 30 minutos","Cómo conducirla y cerrarla"],"contexto":"Una reunión con un CEO o gerente general es una oportunidad escasa: su tiempo es limitado y su atención, selectiva. Si la reunión no aporta, difícilmente habrá una segunda.\n\nLos CEOs valoran tres cosas: que conozcas su negocio, que vayas al punto y que les propongas algo concreto. Esta preparación te ayuda a cumplir las tres en una reunión de 20 a 30 minutos.","lecciones":[{"titulo":"Qué espera un CEO","texto":"Una conversación sobre su negocio, una idea relevante y un siguiente paso claro.\n\nUn CEO no quiere una presentación de tu empresa; quiere entender cómo lo que propones afecta su crecimiento, sus márgenes o su riesgo. Llega con una tesis breve: “Creo que hay una oportunidad de reducir su costo de energía de forma importante con una inversión que se paga sola”. Luego escucha y ajusta."},{"titulo":"Preparación en 30 minutos","texto":"Empresa, sector, persona, tesis, tres preguntas y un siguiente paso.\n\nRevisa el sitio web, noticias recientes y el perfil del CEO. Identifica dos tendencias de su sector. Escribe tu tesis en una frase, tres preguntas para validarla y la propuesta de siguiente paso (una visita técnica, una propuesta, una reunión con su financiero). Prepara una cifra relevante de su negocio para abrir."},{"titulo":"Conducir y cerrar","texto":"Confirma el tiempo, abre con la tesis, escucha más de lo que hablas y cierra con un acuerdo.\n\n“Tengo 20 minutos agendados; ¿sigue siendo así?” muestra respeto. Abre con la tesis y una pregunta. Escucha y toma nota de sus prioridades. Faltando cinco minutos, resume y propone: “¿Le parece si el equipo técnico visita la planta la próxima semana y le presentamos una cifra real?”. Envía el resumen en 24 horas."}],"ejercicio":"Prepara una reunión con un CEO o gerente general siguiendo los seis elementos.","pasos":["Investiga empresa, sector y persona.","Escribe tu tesis en una frase.","Prepara tres preguntas para validarla.","Define el siguiente paso que propondrás."],"quiz":[{"pregunta":"¿Qué espera un CEO de una reunión?","opciones":["Una presentación larga de tu empresa","Conversación sobre su negocio, una idea y un siguiente paso","Un regalo"],"correcta":1},{"pregunta":"¿Con qué conviene abrir?","opciones":["Con tu historia personal","Con una tesis breve y una pregunta","Con precios"],"correcta":1},{"pregunta":"¿Cuándo enviar el resumen?","opciones":["En 24 horas","En un mes","No enviarlo"],"correcta":0}],"accion":"Escribe tu tesis en una frase antes de tu próxima reunión con un gerente general."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('5-errores-comunes-haciendo-networking', '5 errores comunes haciendo networking', 168, true, 5, 'relaciones', 'flash',
          5, 'Principiante', array['todos']::text[], 'aliado', false, false, false, true,
          null, 'Un contenido práctico de Relaciones & Ventas para aplicar esta misma semana.', 't-red', 38, '2026-06-18')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Los cinco errores que hacen inútil el networking","Cómo corregir cada uno","Una regla para cada próximo evento"],"contexto":"El networking falla menos por falta de contactos que por errores repetidos. Identificarlos es el primer paso para convertir los eventos y encuentros en relaciones que generen oportunidades.\n\nEstos son los cinco errores más frecuentes y la forma más simple de corregirlos.","lecciones":[{"titulo":"Hablar de ti y vender de inmediato","texto":"Error 1: presentar tu oferta en el primer minuto. Error 2: hablar más de lo que escuchas.\n\nNadie va a un evento a recibir una oferta. Presentarte en una frase y luego preguntar por el negocio del otro genera conversaciones mucho más valiosas. Una regla útil: habla menos del 30% del tiempo en cada conversación."},{"titulo":"Buscar cantidad","texto":"Error 3: intentar hablar con todos y repartir tarjetas.\n\nDiez conversaciones superficiales valen menos que dos profundas. Elige con quién quieres hablar, invierte tiempo en conocerlo y busca un punto en común real. La calidad de las conversaciones define la calidad de la red."},{"titulo":"No hacer seguimiento ni aportar","texto":"Error 4: no escribir después del evento. Error 5: pedir antes de aportar.\n\nSin seguimiento en las 48 horas siguientes, la mayoría de los contactos se olvida. Y quien solo aparece para pedir pierde credibilidad. Aporta primero —un dato, una introducción, un recurso— y la reciprocidad llegará sola."}],"ejercicio":"Revisa tu último evento con los cinco errores y define una regla para el próximo.","pasos":["Piensa en el último evento de networking al que asististe.","Identifica cuáles de los cinco errores cometiste.","Escribe una regla concreta para corregir el más importante.","Aplícala en tu próximo evento."],"quiz":[{"pregunta":"¿Qué porcentaje del tiempo conviene hablar como máximo?","opciones":["30%","80%","100%"],"correcta":0},{"pregunta":"¿Qué vale más?","opciones":["Diez conversaciones superficiales","Dos conversaciones profundas","Repartir 50 tarjetas"],"correcta":1},{"pregunta":"¿Qué hacer antes de pedir algo?","opciones":["Aportar valor","Nada","Insistir"],"correcta":0}],"accion":"Define una regla concreta para tu próximo evento y cúmplela."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-saber-si-una-empresa-podria-aprovechar-energia-solar', 'Cómo saber si una empresa podría aprovechar energía solar', 169, true, 5, 'energia', 'flash',
          5, 'Principiante', array['todos']::text[], 'free', false, false, false, true,
          null, 'Un contenido práctico de Energía & Sostenibilidad para aplicar esta misma semana.', 't-solar', 36, '2026-07-25')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las cuatro condiciones de una buena candidata","Cómo verificarlas en una conversación","Señales de que no es el momento"],"contexto":"Saber si una empresa podría aprovechar la energía solar no requiere conocimientos técnicos. Basta con revisar cuatro condiciones que el equipo de GEENERA confirma después con un diagnóstico.\n\nEste filtro rápido te permite enfocar tu tiempo, enviar referidos de mejor calidad y evitar conversaciones que no llevarán a un proyecto. Funciona igual para un ejecutivo financiero que revisa su cartera, un consultor que visita clientes o un líder gremial que conoce a sus afiliados.","lecciones":[{"titulo":"Las cuatro condiciones","texto":"Consumo relevante, operación diurna, espacio disponible y capacidad de decisión sobre la sede.\n\nConsumo: una factura de varios millones de pesos al mes. Operación: actividad principal entre las 6 a. m. y las 6 p. m. o continua. Espacio: cubierta amplia en buen estado, parqueaderos o terreno. Decisión: sede propia o arrendamiento de largo plazo con autorización, y acceso a quien aprueba inversiones. Si se cumplen tres o cuatro, la empresa merece un diagnóstico."},{"titulo":"Cómo verificarlas","texto":"Con preguntas naturales y una mirada a la sede o a una imagen satelital.\n\n“¿Cuánto pagan de energía?”, “¿en qué horario operan?”, “¿la sede es propia?” y “¿quién aprueba inversiones?” cubren casi todo. El espacio puedes verificarlo visitando la sede o en Google Earth. Si tienes la factura, confirmas el consumo y el costo unitario de una vez."},{"titulo":"Cuándo no es el momento","texto":"Mudanza próxima, crisis de caja, cubierta que debe reemplazarse o decisión en manos de un tercero lejano.\n\nEstas señales no descartan la empresa para siempre, pero indican que hoy no avanzará. Regístralas en tu seguimiento y retoma la conversación cuando cambie la situación: tras la mudanza, la recuperación o la reparación de la cubierta. Un buen aliado sabe esperar el momento correcto."}],"ejercicio":"Evalúa tres empresas de tu red con las cuatro condiciones.","pasos":["Elige tres empresas que conozcas bien.","Marca cuáles de las cuatro condiciones cumple cada una.","Para las que cumplan tres o cuatro, identifica qué dato falta confirmar.","Para las que no, anota la señal que indica que no es el momento.","Elige una para referir y una para seguimiento."],"quiz":[{"pregunta":"¿Cuántas condiciones debe cumplir una empresa para merecer un diagnóstico?","opciones":["Una","Tres o cuatro","Ninguna"],"correcta":1},{"pregunta":"¿Cómo se verifica el espacio disponible?","opciones":["Visitando la sede o con imagen satelital","Preguntando el número de empleados","No se verifica"],"correcta":0},{"pregunta":"Si la empresa se muda en seis meses…","opciones":["Refiérela ya","Regístrala en seguimiento y retoma tras la mudanza","Descártala para siempre"],"correcta":1}],"accion":"Aplica las cuatro condiciones a la próxima empresa que visites."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('como-funciona-una-factura-de-energia', 'Cómo funciona una factura de energía', 170, true, 5, 'energia', 'micro',
          12, 'Principiante', array['todos']::text[], 'free', false, false, false, false,
          'e1', 'Un contenido práctico de Energía & Sostenibilidad para aplicar esta misma semana.', 't-solar', 34, '2026-08-05')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Leer las partes de una factura comercial","Identificar consumo, tarifa y contribución","Detectar cifras que indican potencial solar","Explicarlo en lenguaje de gerente"],"contexto":"La factura es el documento más útil para hablar de energía: muestra cuánto consume una empresa, cuánto paga por cada kWh y cómo cambia mes a mes. Saber leerla te da credibilidad inmediata.\n\nEn Colombia, el costo unitario de la energía para usuarios regulados se calcula con la fórmula tarifaria definida por la Comisión de Regulación de Energía y Gas (CREG), que suma los costos de cada eslabón de la cadena. Entender esa estructura permite explicar por qué dos empresas en ciudades distintas pagan precios diferentes, por qué la factura cambia aunque el consumo sea igual y qué parte del costo puede evitar una empresa que genera su propia energía.","lecciones":[{"titulo":"Consumo en kWh","texto":"Es la energía usada en el periodo. Busca el histórico de seis meses: muestra estacionalidad y estabilidad.\n\nEl consumo se mide en kilovatios hora y se registra en el medidor. La mayoría de facturas comerciales incluye un gráfico con el histórico de los últimos seis o doce meses: si las barras son parecidas, la empresa tiene un consumo estable y predecible; si hay picos, conviene preguntar qué los explica (temporadas, turnos adicionales, nuevos equipos). Este histórico es la base del dimensionamiento solar."},{"titulo":"Costo unitario","texto":"Lo que se paga por cada kWh. Incluye generación, transmisión, distribución, comercialización, pérdidas y restricciones.\n\nEl costo unitario resulta de sumar generación (G), transmisión (T), distribución (D), comercialización (C), pérdidas (PR) y restricciones (R). La generación suele ser el componente más grande y el más sensible a la hidrología; la distribución varía según el operador de red y el nivel de tensión. Los usuarios conectados en nivel 1 (baja tensión) pagan normalmente más que los conectados en niveles 2 o 3, porque usan más infraestructura de la red."},{"titulo":"Contribución y otros cargos","texto":"Los usuarios comerciales suelen pagar contribución sobre el valor del consumo; algunos industriales están exentos. También aparecen alumbrado y aseo.\n\nLa contribución de solidaridad es un recargo del 20% sobre el valor del consumo que pagan los usuarios comerciales y, en algunos casos, los industriales, para subsidiar a los estratos bajos. Las actividades industriales pueden solicitar la exención ante su comercializador cumpliendo los requisitos de registro. Cada kWh que la empresa genera en su propia cubierta evita también la contribución asociada, lo que mejora el ahorro real frente al cálculo simple."},{"titulo":"Qué mirar primero","texto":"Valor total, kWh del mes, costo por kWh y tendencia. Con esos cuatro datos ya puedes estimar el potencial.\n\nCon valor total, kWh, costo unitario y tendencia ya puedes formular una hipótesis: “Su factura es de $20 millones, consume 24.000 kWh y paga cerca de $830 por kWh; si la mitad de su consumo es diurno, un sistema solar podría cubrir una parte significativa”. No es una propuesta, es una conversación informada que motiva al cliente a pedir un diagnóstico."}],"ejercicio":"Toma una factura (tuya o de una empresa cercana) y ubica consumo, costo unitario, contribución y valor total.","pasos":["Consigue una factura comercial o industrial (la de tu empresa o la de un contacto).","Ubica el consumo del mes en kWh y el histórico de seis meses.","Calcula el costo unitario: valor de la energía ÷ kWh consumidos.","Identifica si paga contribución y en qué nivel de tensión está conectada.","Escribe en dos frases cómo le explicarías al gerente lo que encontraste."],"quiz":[{"pregunta":"¿Qué unidad mide el consumo?","opciones":["kW","kWh","Voltios"],"correcta":1},{"pregunta":"¿Qué muestra mejor la estabilidad del consumo?","opciones":["El último mes","El histórico de seis meses","El logo del operador"],"correcta":1},{"pregunta":"¿Qué recargo pagan normalmente los usuarios comerciales sobre el valor del consumo?","opciones":["5%","20% de contribución","Ninguno"],"correcta":1},{"pregunta":"¿Qué componente del costo unitario es más sensible al clima?","opciones":["Comercialización","Generación","Alumbrado público"],"correcta":1}],"accion":"Pide a un contacto su última factura y léela con él."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('mercado-energetico-colombiano-explicado-facil', 'Mercado energético colombiano explicado fácil', 171, true, 5, 'energia', 'micro',
          14, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e1', 'Un contenido práctico de Energía & Sostenibilidad para aplicar esta misma semana.', 't-solar', 32, '2026-09-12')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Quién genera, transporta y vende la energía","Diferencia entre usuario regulado y no regulado","Qué hace la CREG","Dónde entra la autogeneración"],"contexto":"Entender quién hace qué en el mercado te permite responder preguntas básicas del empresario y explicar por qué generar su propia energía es una decisión estratégica.\n\nEl mercado eléctrico colombiano se organizó a partir de las leyes 142 y 143 de 1994, que separaron las actividades de generación, transmisión, distribución y comercialización y crearon un mercado mayorista donde se compra y vende energía. XM opera el sistema y administra ese mercado; la CREG regula; la Superintendencia de Servicios Públicos vigila; y la UPME planea la expansión. Con este mapa puedes responder con seguridad las preguntas que un gerente hace sobre su factura.","lecciones":[{"titulo":"La cadena","texto":"Generadores producen, transmisores llevan en alta tensión, distribuidores llegan a cada empresa y comercializadores facturan.\n\nLos generadores venden su energía en contratos de largo plazo o en la bolsa, donde el precio se forma hora a hora según la oferta y la demanda. Los transmisores operan las redes de alta tensión del Sistema de Transmisión Nacional; los operadores de red distribuyen en cada región; y los comercializadores compran la energía y la facturan al usuario final. Un mismo grupo empresarial puede participar en varias actividades, pero cada una se remunera por separado."},{"titulo":"Regulado y no regulado","texto":"Las empresas pequeñas pagan tarifa regulada. Las grandes pueden negociar contratos como usuarios no regulados.\n\nUn usuario puede ser no regulado si su demanda máxima supera 0,1 MW o su consumo mensual supera 55 MWh, según la regulación vigente. Estos usuarios negocian libremente precio y condiciones con un comercializador, mientras que los regulados pagan la tarifa calculada con la fórmula de la CREG. Para la mayoría de PyMEs, la tarifa regulada es la única opción, lo que hace más atractiva la autogeneración como forma de controlar el costo."},{"titulo":"El regulador","texto":"La CREG define reglas y fórmulas tarifarias. La matriz colombiana depende mucho del agua, por eso el clima afecta precios.\n\nLa matriz de generación colombiana es predominantemente hidráulica, con una participación creciente de solar y eólica. En años con fenómeno de El Niño, como 2015–2016 y 2023–2024, la menor disponibilidad de agua presionó al alza el precio de bolsa y, con rezago, las tarifas. Esta dependencia climática explica buena parte de la volatilidad que perciben los empresarios."},{"titulo":"Autogeneración","texto":"Una empresa puede producir parte de su energía con paneles en su techo y, bajo ciertas reglas, entregar excedentes a la red.\n\nLa Ley 1715 de 2014 y la Ley 2099 de 2021 promovieron las fuentes no convencionales de energía y la autogeneración. La resolución CREG 174 de 2021 regula la autogeneración a pequeña escala (hasta 1 MW) y la generación distribuida, incluyendo la entrega de excedentes a la red. En la práctica, una empresa puede instalar paneles en su cubierta, consumir lo que produce y, cumpliendo los procedimientos del operador de red, recibir reconocimiento por la energía que no consume."}],"ejercicio":"Explica en tres frases, como si hablaras con un gerente, por qué su factura sube aunque consuma lo mismo.","pasos":["Dibuja en una hoja la cadena: generación → transmisión → distribución → comercialización → usuario.","Ubica en cada eslabón una empresa real que opere en tu región.","Escribe dónde entra la autogeneración solar en esa cadena.","Prepara una explicación de 30 segundos para un gerente que pregunta por qué su factura sube."],"quiz":[{"pregunta":"¿Quién define las reglas tarifarias?","opciones":["La CREG","El banco","La alcaldía"],"correcta":0},{"pregunta":"¿Por qué el clima influye en el precio?","opciones":["Por la dependencia de generación hidráulica","Por los paneles","No influye"],"correcta":0},{"pregunta":"¿Quién opera el sistema y administra el mercado mayorista?","opciones":["XM","La UPME","El comercializador"],"correcta":0},{"pregunta":"¿Qué norma regula la autogeneración a pequeña escala?","opciones":["CREG 174 de 2021","Ley 100 de 1993","Ninguna"],"correcta":0}],"accion":"Usa la explicación de la cadena en tu próxima conversación."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('por-que-cambia-el-precio-de-la-energia', 'Por qué cambia el precio de la energía', 172, true, 5, 'energia', 'micro',
          16, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e1', 'Un contenido práctico de Energía & Sostenibilidad para aplicar esta misma semana.', 't-roi', 30, '2026-01-19')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Factores que mueven la tarifa","Efecto del clima y la demanda","Por qué el precio es difícil de predecir","Cómo la autogeneración da certeza"],"contexto":"Los empresarios suelen sentir que la energía sube sin razón. Explicar los factores detrás de la tarifa abre la conversación sobre cómo fijar parte de ese costo.\n\nEntre 2021 y 2024, muchas empresas colombianas vieron incrementos de dos dígitos en el costo por kWh, impulsados por la inflación, la indexación de componentes tarifarios, la recuperación de saldos de la opción tarifaria aplicada durante la pandemia y, más adelante, el fenómeno de El Niño. Para un gerente, entender estas causas convierte una molestia en una variable de riesgo que se puede gestionar.","lecciones":[{"titulo":"Clima e hidrología","texto":"Temporadas secas reducen generación hidráulica y encarecen la energía en bolsa.\n\nCuando llueve menos, los embalses bajan y el sistema debe despachar más plantas térmicas, que tienen costos variables más altos. El precio de bolsa sube y se traslada a los usuarios cuyos comercializadores compran una parte de su energía en bolsa. Aunque los contratos de largo plazo amortiguan el efecto, los periodos secos prolongados suelen reflejarse en la tarifa con algunos meses de rezago."},{"titulo":"Indexación","texto":"Varios componentes de la tarifa se actualizan con índices de precios, por eso suben con la inflación.\n\nVarios componentes de la tarifa y muchos contratos de energía se actualizan con índices como el IPP o el IPC. En años de inflación alta, la tarifa sube aunque no cambie nada en el sistema eléctrico. Además, decisiones regulatorias como la opción tarifaria —que difirió aumentos durante la pandemia— generaron saldos que luego se recuperaron en las facturas."},{"titulo":"Demanda y expansión","texto":"Si la demanda crece más rápido que la nueva generación, el precio tiende a subir.\n\nLa demanda de energía crece con la economía, la electrificación de procesos y nuevos usos como la movilidad eléctrica o los centros de datos. Si los proyectos de generación y transmisión se retrasan, el margen entre oferta y demanda se estrecha y el sistema se vuelve más sensible a cualquier choque. Esta es una de las razones por las que los analistas del sector advierten sobre la necesidad de nueva capacidad en los próximos años."},{"titulo":"Certeza con solar","texto":"La energía que produces en tu techo tiene un costo conocido durante décadas: es una cobertura natural contra la volatilidad.\n\nUn sistema solar tiene un costo concentrado al inicio y costos operativos bajos durante más de 25 años. Por eso, el costo de cada kWh que produce es prácticamente fijo y conocido desde el primer día. Para el área financiera, eso equivale a una cobertura parcial frente a la volatilidad: la porción del consumo que se autogenera deja de depender del clima, la inflación y la regulación."}],"ejercicio":"Busca el valor del kWh de una factura de hace un año y compáralo con la actual. Calcula la variación.","pasos":["Consigue dos facturas de la misma empresa con un año de diferencia.","Calcula el costo unitario de cada una (valor de energía ÷ kWh).","Calcula la variación porcentual entre ambas.","Identifica cuál de los factores de la lección explica mejor el cambio.","Redacta un mensaje de tres líneas para compartir el hallazgo con el gerente."],"quiz":[{"pregunta":"¿Qué da certeza de costo a largo plazo?","opciones":["Comprar en bolsa","Autogenerar con solar","Consumir de noche"],"correcta":1},{"pregunta":"¿Qué efecto tiene una temporada seca?","opciones":["Baja el precio","Suele subir el precio","Ninguno"],"correcta":1},{"pregunta":"¿Qué mecanismo difirió aumentos tarifarios durante la pandemia?","opciones":["La opción tarifaria","La contribución","El alumbrado público"],"correcta":0}],"accion":"Comparte con un cliente la variación de su tarifa en el último año."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('kw-kwh-y-demanda', 'kW, kWh y demanda', 173, true, 5, 'energia', 'micro',
          12, 'Principiante', array['todos']::text[], 'free', false, false, false, false,
          'e1', 'Un contenido práctico de Energía & Sostenibilidad para aplicar esta misma semana.', 't-solar', 28, '2026-02-26')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Diferencia entre potencia y energía","Qué es la demanda pico","Cómo se relaciona con el tamaño de un sistema solar","Errores comunes al hablar de cifras"],"contexto":"Confundir kW con kWh es el error más frecuente en conversaciones sobre energía. Dominar estas unidades te hace sonar preciso sin ser ingeniero.\n\nLas unidades de energía aparecen en facturas, propuestas y conversaciones financieras. Un error —decir “la empresa consume 50 kW al mes”— resta credibilidad de inmediato frente a un gerente de planta o un ingeniero. Esta lección te da el vocabulario mínimo para hablar con precisión y entender una propuesta solar sin ser técnico.","lecciones":[{"titulo":"kW: potencia","texto":"Es la velocidad a la que se usa energía en un momento. Un aire acondicionado de 3 kW consume a ese ritmo mientras está encendido.\n\nLa potencia indica cuánta energía se usa por unidad de tiempo. Un motor de 15 kW, una nevera industrial de 5 kW o un aire acondicionado de 3 kW describen la intensidad con la que consumen mientras están encendidos. En una empresa, la suma de los equipos que funcionan al mismo tiempo define la potencia demandada en cada momento."},{"titulo":"kWh: energía","texto":"Es la cantidad acumulada. Ese aire de 3 kW, encendido 2 horas, consume 6 kWh.\n\nLa energía es potencia multiplicada por tiempo. Es lo que mide el medidor y lo que se cobra en la factura. Si una planta tiene en promedio 80 kW encendidos durante 10 horas diarias y 22 días al mes, consume 80 × 10 × 22 = 17.600 kWh mensuales. Esta multiplicación sencilla te permite verificar si una cifra tiene sentido."},{"titulo":"Demanda pico","texto":"La potencia máxima que la empresa requiere en algún momento. Define la capacidad de la conexión.\n\nLa demanda máxima es la potencia más alta registrada en un periodo, por ejemplo cuando arrancan varios motores a la vez. Define la capacidad de la conexión y del transformador, y para usuarios no regulados puede influir en el costo. Conocerla ayuda al equipo técnico a decidir el tamaño del inversor y la forma de conexión del sistema solar."},{"titulo":"kWp en solar","texto":"Los sistemas solares se dimensionan en kWp (kilovatio pico). En Colombia, cada kWp produce del orden de 110 a 130 kWh al mes.\n\nUn kilovatio pico es la potencia que entrega un panel en condiciones estándar de laboratorio. En condiciones reales, la producción mensual depende de la radiación solar del lugar, la orientación, la inclinación, las sombras y la temperatura. En Colombia, un sistema bien instalado produce aproximadamente entre 110 y 150 kWh por cada kWp al mes: más en la región Caribe y en zonas de alta radiación, menos en zonas con mayor nubosidad."}],"ejercicio":"Calcula cuántos kWh al mes consume un equipo de 5 kW que trabaja 8 horas diarias, 22 días.","pasos":["Calcula el consumo mensual de un equipo de 5 kW que trabaja 8 horas diarias, 22 días al mes.","Supón que la empresa consume 15.000 kWh al mes y quiere cubrir el 40% con solar.","Divide esa energía entre 120 kWh/kWp para estimar el tamaño del sistema.","Multiplica los kWp por 6 m² para estimar el área de cubierta necesaria.","Revisa tus resultados con la Guía para leer una factura de energía."],"quiz":[{"pregunta":"Un equipo de 2 kW encendido 5 horas consume…","opciones":["7 kWh","10 kWh","2,5 kWh"],"correcta":1},{"pregunta":"¿En qué unidad se dimensiona un sistema solar?","opciones":["kWp","kWh","Amperios"],"correcta":0},{"pregunta":"Una empresa consume 6.000 kWh al mes. ¿Qué sistema cubriría aproximadamente la mitad?","opciones":["25 kWp","250 kWp","2,5 kWp"],"correcta":0}],"accion":"Usa kW y kWh correctamente en tu próxima conversación energética."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('energia-como-costo-empresarial', 'Energía como costo empresarial', 174, true, 5, 'energia', 'micro',
          14, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e1', 'Un contenido práctico de Energía & Sostenibilidad para aplicar esta misma semana.', 't-factura', 100, '2026-03-06')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Cuánto pesa la energía en distintos sectores","Cómo afecta márgenes y competitividad","Qué decisiones toman las empresas líderes","Cómo plantearlo al gerente financiero"],"contexto":"Para muchas empresas la energía es uno de los tres costos operativos más grandes, pero rara vez se gestiona como tal. Quien ayuda a controlarlo gana un lugar en la mesa de decisiones.\n\nEn muchas empresas, la energía se registra como un gasto general y nadie es “dueño” de él: llega la factura, se paga y se archiva. Sin embargo, en un entorno de márgenes estrechos, un incremento sostenido de la tarifa puede borrar puntos de rentabilidad que costó años construir. Tratar la energía como un costo estratégico —medido, presupuestado y gestionado— es el primer paso para que una inversión en eficiencia o autogeneración tenga sentido para la gerencia.","lecciones":[{"titulo":"Peso por sector","texto":"En manufactura, frío, alimentos y hotelería la energía puede representar una parte significativa de los costos de operación.\n\nEl peso de la energía varía enormemente. En una oficina de servicios puede ser marginal; en una planta de plásticos, un frigorífico, una panadería industrial o un supermercado puede ubicarse entre los tres primeros costos operativos después de materia prima y nómina. Preguntar “¿qué porcentaje de sus costos es energía?” obliga al gerente a hacer la cuenta, y con frecuencia la cifra lo sorprende."},{"titulo":"Margen y precio","texto":"Si la energía sube y la empresa no puede trasladarlo al precio, el aumento sale directamente del margen.\n\nSi un producto se vende con un margen operativo del 8% y la energía representa el 10% de los costos, un aumento del 20% en la tarifa reduce el margen en cerca de dos puntos. La empresa tiene tres opciones: trasladar el costo al precio (si el mercado lo permite), absorberlo (perdiendo rentabilidad) o reducirlo. La autogeneración pertenece a la tercera opción y tiene la ventaja de que su efecto dura décadas."},{"titulo":"Costo fijo vs. variable","texto":"La energía suele tratarse como inevitable. Las empresas líderes la gestionan: miden, reducen y generan.\n\nParte del consumo es fijo —iluminación, refrigeración, servidores— y parte varía con la producción. Esta distinción ayuda a dimensionar: un sistema solar suele diseñarse para cubrir la base de consumo diurno, que se mantiene incluso en meses de baja producción, de modo que casi toda la energía generada se aproveche dentro de la empresa."},{"titulo":"El lenguaje correcto","texto":"Habla de impacto en EBITDA y en costo por unidad producida, no de paneles.\n\nCon el gerente general, habla de margen y competitividad; con el financiero, de flujo de caja, retorno y riesgo; con el gerente de planta, de continuidad y control. El mismo proyecto se explica de tres maneras distintas, y adaptar el lenguaje es una de las habilidades que más diferencia a un aliado que abre puertas de uno que solo envía contactos."}],"ejercicio":"Estima qué porcentaje de los costos de un cliente representa la energía y cuánto margen liberaría reducirla 30%.","pasos":["Elige una empresa de tu red cuyo sector conozcas.","Estima qué porcentaje de sus costos operativos podría ser energía (baja, media o alta intensidad).","Calcula el efecto en su margen de un aumento del 15% en la tarifa.","Escribe una frase para el gerente general y otra para el financiero que expliquen ese efecto."],"quiz":[{"pregunta":"Si la energía sube y no se traslada al precio…","opciones":["Se reduce el margen","Sube la utilidad","No pasa nada"],"correcta":0},{"pregunta":"¿Qué lenguaje funciona con un CFO?","opciones":["Paneles y vatios","EBITDA y costo por unidad","Colores de la marca"],"correcta":1},{"pregunta":"Si la energía es el 10% de los costos y sube 20%, ¿qué pasa con un margen del 8%?","opciones":["Se reduce cerca de dos puntos","No cambia","Se duplica"],"correcta":0}],"accion":"Pregunta a un cliente cuánto pesa la energía en su estructura de costos."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('introduccion-a-la-autogeneracion', 'Introducción a la autogeneración', 175, true, 5, 'energia', 'micro',
          16, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e1', 'Un contenido práctico de Energía & Sostenibilidad para aplicar esta misma semana.', 't-solar', 98, '2026-04-13')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es autogenerar energía","Diferencia entre consumo propio y excedentes","Marco general en Colombia","Cuándo tiene sentido"],"contexto":"Autogenerar es producir en tu propia sede parte de la energía que consumes. Para una empresa significa pagar menos a la red y tener un costo más predecible.\n\nLa autogeneración dejó de ser una práctica exclusiva de grandes industrias. Desde la Ley 1715 de 2014 y, especialmente, con la resolución CREG 174 de 2021, Colombia cuenta con reglas claras para que empresas de todos los tamaños produzcan su propia energía, se conecten a la red y entreguen excedentes. El resultado ha sido un crecimiento sostenido de instalaciones solares en cubiertas comerciales e industriales en todo el país.","lecciones":[{"titulo":"Autoconsumo","texto":"La energía solar se usa primero en la operación. Cada kWh producido es un kWh que no se compra.\n\nEn el autoconsumo, la energía que producen los paneles se usa primero dentro de la empresa. La red cubre lo que falta en las horas sin sol o cuando la demanda supera la generación. Como cada kWh autoconsumido evita comprar uno a la tarifa completa —incluidos cargos de red y, cuando aplica, contribución—, el autoconsumo es la forma más rentable de aprovechar un sistema."},{"titulo":"Excedentes","texto":"Si se produce más de lo que se consume en un momento, el excedente puede entregarse a la red y reconocerse según la regulación vigente.\n\nCuando los paneles producen más de lo que la empresa consume en un momento dado, el excedente se entrega a la red a través de un medidor bidireccional. La regulación define cómo se reconoce: para sistemas pequeños, buena parte de los excedentes puede compensarse como créditos de energía contra el consumo; lo que supera el consumo se valora a precio de bolsa, que suele ser menor que la tarifa. Por eso, en general, conviene dimensionar para autoconsumir la mayor parte de lo generado."},{"titulo":"Pequeña escala","texto":"La mayoría de proyectos empresariales son autogeneración a pequeña escala, con trámites más simples ante el operador de red.\n\nLa regulación distingue a los autogeneradores a pequeña escala, hasta 1 MW, de los de gran escala. Para los primeros, el procedimiento de conexión ante el operador de red es simplificado: solicitud, estudio de disponibilidad, instalación conforme al RETIE, inspección y conexión. GEENERA gestiona este trámite como parte del proyecto, lo que reduce la carga administrativa para el cliente."},{"titulo":"Cuándo conviene","texto":"Consumo diurno, sede propia, cubierta disponible y factura relevante: las cuatro condiciones clásicas.\n\nLa autogeneración solar suele ser atractiva cuando la empresa tiene consumo diurno significativo, cubierta disponible, sede propia o contrato de largo plazo, y una tarifa que justifica la inversión. Es menos atractiva cuando el consumo es mayoritariamente nocturno, la cubierta requiere reparación costosa o la empresa planea mudarse pronto. Saber distinguir estos casos te ahorra tiempo y protege tu credibilidad."}],"ejercicio":"Piensa en una empresa conocida y evalúa las cuatro condiciones: consumo diurno, sede propia, cubierta y factura.","pasos":["Elige una empresa de tu red con sede propia.","Describe su consumo: ¿es mayoritariamente diurno o nocturno?","Estima si autoconsumiría casi toda la energía generada o tendría excedentes frecuentes (fines de semana, festivos).","Escribe cómo le explicarías la diferencia entre autoconsumo y excedentes en dos frases."],"quiz":[{"pregunta":"¿Qué se usa primero, la energía solar o la de la red?","opciones":["La de la red","La solar","Se alternan"],"correcta":1},{"pregunta":"¿Qué pasa con los excedentes?","opciones":["Se pierden siempre","Pueden entregarse a la red","Dañan el sistema"],"correcta":1},{"pregunta":"¿Por qué conviene autoconsumir la mayor parte de lo generado?","opciones":["Porque cada kWh autoconsumido evita pagar la tarifa completa","Porque los excedentes están prohibidos","Porque la red no acepta energía solar"],"correcta":0},{"pregunta":"¿Hasta qué capacidad se considera autogeneración a pequeña escala?","opciones":["100 MW","1 MW","10 kW"],"correcta":1}],"accion":"Explica la autogeneración a un contacto en menos de un minuto."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-como-funciona-un-sistema-fotovoltaico', 'Solar · Cómo funciona un sistema fotovoltaico', 176, true, 5, 'energia', 'flash',
          5, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'Del sol al tomacorriente, explicado en tres pasos.', 't-solar', 96, '2026-05-20')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["El recorrido de la energía solar","Qué hace cada componente","Cómo se integra con la red"],"contexto":"No necesitas ser técnico para explicar un sistema solar. Basta con entender tres pasos: captar, convertir y consumir.\n\nUn sistema fotovoltaico no tiene partes móviles, no hace ruido ni consume combustible. Convierte directamente la radiación del sol en electricidad mediante el efecto fotovoltaico, descrito a comienzos del siglo XX y llevado a escala comercial durante las últimas décadas. Entender el recorrido de la energía —del panel al tablero de la empresa— te permite explicarlo con sencillez y responder la duda más común: “¿y qué pasa cuando no hay sol?”.","lecciones":[{"titulo":"Captar","texto":"Los paneles convierten la luz en electricidad de corriente continua.\n\nLos paneles están formados por celdas de silicio que liberan electrones cuando reciben luz. Un panel comercial moderno tiene potencias del orden de 550 a 650 W. La producción depende de la radiación del lugar, del ángulo y la orientación de los módulos, de la temperatura y de la ausencia de sombras. Colombia, por su ubicación cercana al ecuador, recibe una radiación relativamente estable durante todo el año."},{"titulo":"Convertir","texto":"El inversor transforma esa corriente en alterna, la misma que usan los equipos de la empresa.\n\nLos paneles producen corriente continua, mientras que los equipos de la empresa funcionan con corriente alterna. El inversor convierte una en otra, sincroniza el sistema con la red y optimiza la producción mediante seguimiento del punto de máxima potencia. Además, registra datos de generación que permiten monitorear el desempeño en tiempo real."},{"titulo":"Consumir","texto":"La energía va al tablero y se usa en la operación; si falta, la red completa la diferencia automáticamente.\n\nLa energía del inversor llega al tablero eléctrico y se distribuye a los equipos de la empresa, que la consumen antes que la de la red. Si hay excedentes, salen a la red a través del medidor bidireccional; si la producción no alcanza —en la noche o en días nublados—, la red suministra la diferencia sin interrupciones. Para el usuario, el cambio es imperceptible."}],"ejercicio":"Dibuja en una hoja el recorrido panel → inversor → tablero → red y explícaselo a alguien.","pasos":["Dibuja el recorrido: panel → inversor → tablero → equipos → medidor → red.","Marca en qué punto la energía pasa de corriente continua a alterna.","Escribe qué ocurre en tres momentos: mediodía, atardecer y noche.","Practica la explicación en voz alta en menos de un minuto."],"quiz":[{"pregunta":"¿Qué hace el inversor?","opciones":["Almacena energía","Convierte corriente continua en alterna","Limpia los paneles"],"correcta":1},{"pregunta":"Si el sol no alcanza, ¿qué pasa?","opciones":["Se apaga la empresa","La red completa","Se usa diésel"],"correcta":1},{"pregunta":"¿Qué ocurre en la noche en un sistema conectado a la red?","opciones":["La empresa se queda sin energía","La red suministra la energía necesaria","Los paneles siguen produciendo"],"correcta":1}],"accion":"Usa la explicación de tres pasos con un cliente."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-sistemas-on-grid', 'Solar · Sistemas On-Grid', 177, true, 5, 'energia', 'flash',
          6, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'El sistema más común para empresas conectadas a la red.', 't-solar', 94, '2026-06-27')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es un sistema conectado a red","Por qué es el más rentable","Su principal limitación"],"contexto":"La mayoría de empresas en ciudades usa sistemas On-Grid: generan durante el día y se apoyan en la red el resto del tiempo.\n\nLa gran mayoría de proyectos solares comerciales e industriales en zonas urbanas de Colombia son sistemas conectados a la red, también llamados on-grid. Su ventaja es económica: al no requerir baterías, la inversión es menor y el retorno más rápido. Su limitación es que dependen de la red para funcionar, algo que conviene explicar con claridad para evitar expectativas equivocadas.","lecciones":[{"titulo":"Cómo funciona","texto":"Paneles e inversor trabajan sincronizados con la red. No requieren baterías.\n\nEl sistema on-grid trabaja en paralelo con la red. El inversor se sincroniza con la frecuencia y la tensión de la red y entrega la energía solar al tablero. La empresa consume primero lo que producen los paneles y complementa con la red cuando es necesario. Un medidor bidireccional registra tanto la energía que entra como la que sale."},{"titulo":"Por qué rinde","texto":"Sin baterías, la inversión es menor y el payback más corto.\n\nSin baterías, casi todo el costo del sistema se destina a generar energía, y cada kWh producido se aprovecha de inmediato o se entrega como excedente. Por eso los sistemas on-grid suelen tener los paybacks más cortos del mercado solar. También requieren menos mantenimiento, ya que las baterías son el componente con menor vida útil en sistemas aislados o híbridos."},{"titulo":"Limitación","texto":"Si la red se cae, el sistema se apaga por seguridad. No es respaldo ante cortes.\n\nPor seguridad de los técnicos que trabajan en la red, la normativa exige que el inversor se apague automáticamente cuando la red falla; esta función se conoce como protección anti-isla. Un sistema on-grid, por tanto, no funciona como respaldo durante un corte. Si la continuidad es crítica para la empresa, la conversación debe derivar hacia un sistema híbrido."}],"ejercicio":"Identifica si la prioridad de un cliente es ahorro o respaldo.","pasos":["Piensa en tres empresas de tu red.","Para cada una, responde: ¿qué tan críticos son para ella los cortes de energía?","Clasifica cuáles serían candidatas a on-grid y cuáles requerirían híbrido.","Escribe cómo explicarías la protección anti-isla a un gerente que pregunta por qué el sistema se apaga en un corte."],"quiz":[{"pregunta":"¿Un On-Grid funciona durante un corte?","opciones":["Sí","No, se apaga por seguridad","Solo de noche"],"correcta":1},{"pregunta":"¿Por qué suele ser más rentable?","opciones":["No usa baterías","Usa más paneles","No requiere inversor"],"correcta":0},{"pregunta":"¿Por qué un sistema on-grid se apaga en un corte de red?","opciones":["Por falla del panel","Por la protección anti-isla, que protege a quienes trabajan en la red","Porque se agota la batería"],"correcta":1}],"accion":"Pregunta a tu próximo contacto: ¿buscas ahorro o respaldo?"}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-sistemas-off-grid', 'Solar · Sistemas Off-Grid', 178, true, 5, 'energia', 'flash',
          7, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'Energía donde la red no llega.', 't-solar', 92, '2026-07-07')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Cuándo se usa un sistema aislado","Rol de las baterías","Por qué cuesta más"],"contexto":"Los sistemas Off-Grid no dependen de la red. Son la solución en fincas, sitios remotos o infraestructura sin conexión confiable.\n\nMás de la mitad del territorio colombiano pertenece a las Zonas No Interconectadas, donde muchas comunidades y unidades productivas dependen de plantas diésel costosas y contaminantes. Allí, los sistemas solares aislados —off-grid— son una solución estratégica. En zonas con red, en cambio, rara vez son la opción más eficiente para una empresa.","lecciones":[{"titulo":"Dónde aplican","texto":"Zonas rurales, antenas, campamentos o fincas lejos de la red.\n\nLos sistemas off-grid son adecuados para fincas, operaciones agroindustriales lejanas, estaciones de telecomunicaciones, campamentos, bombeo de agua y comunidades sin conexión. También para sitios donde llevar la red sería más costoso que instalar un sistema propio. En estos casos, el ahorro se compara con el costo del combustible y la logística del diésel, que suele ser muy alto."},{"titulo":"Baterías","texto":"Almacenan la energía del día para usarla de noche. Son parte clave del costo.\n\nLas baterías almacenan la energía producida durante el día para usarla en la noche. Las tecnologías de litio ferrofosfato (LFP) se han vuelto estándar por su vida útil de miles de ciclos, mayor profundidad de descarga y menor mantenimiento frente a las de plomo-ácido. Aun así, representan una parte importante de la inversión y deben reemplazarse antes que los paneles."},{"titulo":"Dimensionamiento","texto":"Debe cubrir el 100% del consumo y días nublados: se diseña con más margen.\n\nDiseñar un sistema aislado exige conocer el consumo diario en kWh, la potencia máxima de los equipos y los días de autonomía requeridos sin sol. Un error de dimensionamiento significa cortes. Por eso el levantamiento de cargas —qué equipos, cuántas horas, en qué momento— es la información más importante que puedes reunir antes de referir un caso off-grid."}],"ejercicio":"Piensa en un cliente con sedes rurales que hoy use diésel.","pasos":["Identifica si en tu red hay fincas, operaciones rurales o sedes sin conexión estable.","Elige una y lista sus equipos principales y horas de uso.","Calcula el consumo diario aproximado en kWh.","Anota cuánto gasta hoy en combustible para generación."],"quiz":[{"pregunta":"¿Qué componente define el costo de un Off-Grid?","opciones":["Las baterías","El cable","El tablero"],"correcta":0},{"pregunta":"¿Dónde tiene más sentido?","opciones":["En el centro de Bogotá","Donde no hay red confiable","En oficinas"],"correcta":1},{"pregunta":"¿Qué tecnología de baterías se ha vuelto estándar en sistemas solares nuevos?","opciones":["Plomo-ácido abierta","Litio ferrofosfato (LFP)","Níquel-cadmio"],"correcta":1}],"accion":"Pregunta a un cliente agro si usa plantas diésel."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-sistemas-hibridos', 'Solar · Sistemas híbridos', 179, true, 5, 'energia', 'flash',
          5, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'Ahorro y respaldo en un mismo sistema.', 't-solar', 90, '2026-08-14')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué combina un sistema híbrido","Para quién es","Cómo justificar la inversión"],"contexto":"Un híbrido se conecta a la red y además tiene baterías. Es la opción cuando un corte cuesta caro: clínicas, frío, data centers.\n\nLos sistemas híbridos combinan lo mejor de los dos mundos: conexión a la red para optimizar costos y baterías para dar respaldo. La caída sostenida del precio de las baterías durante la última década ha ampliado sus aplicaciones, pero siguen siendo una inversión adicional que se justifica cuando la continuidad tiene un valor económico claro.","lecciones":[{"titulo":"Cómo funciona","texto":"Genera y consume como un On-Grid, y guarda energía para seguir operando si la red cae.\n\nEn un sistema híbrido, el inversor gestiona tres fuentes: paneles, baterías y red. Durante el día prioriza la energía solar y carga las baterías; en la noche o en un corte, las baterías alimentan los circuitos definidos como críticos. Algunos sistemas también pueden descargar las baterías en las horas de mayor costo o demanda para reducir la factura."},{"titulo":"Para quién","texto":"Operaciones críticas donde una interrupción daña producto o servicio.\n\nLos híbridos tienen sentido en clínicas, laboratorios, cadenas de frío, centros de datos, comercios con sistemas de pago críticos y zonas con cortes frecuentes o de mala calidad de energía. También donde hoy se usa una planta diésel de respaldo que se enciende con regularidad: el sistema híbrido puede reducir su uso y su costo de combustible."},{"titulo":"Justificación","texto":"Se suma al ahorro el costo evitado de los cortes: producto perdido, horas paradas, reputación.\n\nLa pregunta clave es: “¿cuánto le cuesta una hora sin energía?”. Si la respuesta incluye producto perdido, ventas no realizadas o riesgos para pacientes, el respaldo tiene un valor que se puede cuantificar y comparar con el costo de las baterías. Si la respuesta es “poco”, un sistema on-grid será normalmente la mejor opción financiera."}],"ejercicio":"Pregunta a un cliente cuánto le cuesta una hora sin energía.","pasos":["Elige una empresa con operación sensible a cortes.","Estima cuánto pierde por hora sin energía (producto, ventas, multas).","Estima cuántas horas de corte tiene al año.","Multiplica para obtener el costo anual de los cortes y compáralo con la idea de invertir en respaldo."],"quiz":[{"pregunta":"¿Qué agrega un híbrido frente a un On-Grid?","opciones":["Baterías y respaldo","Más paneles","Nada"],"correcta":0},{"pregunta":"¿Quién lo necesita más?","opciones":["Una oficina pequeña","Una operación crítica","Un parqueadero"],"correcta":1},{"pregunta":"¿Qué pregunta justifica mejor un sistema híbrido?","opciones":["¿Cuánto le cuesta una hora sin energía?","¿De qué color es su techo?","¿Cuántos empleados tiene?"],"correcta":0}],"accion":"Identifica un cliente para quien un corte sea costoso."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-componentes-principales', 'Solar · Componentes principales', 180, true, 5, 'energia', 'flash',
          6, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'Paneles, inversor, estructura y monitoreo.', 't-solar', 88, '2026-09-21')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Los cuatro componentes de un sistema","Qué preguntar sobre su calidad","Por qué el monitoreo importa"],"contexto":"Conocer los componentes te permite responder dudas básicas y entender por qué dos propuestas con el mismo tamaño pueden costar distinto.\n\nUn sistema solar empresarial es más que paneles: incluye inversores, estructura de montaje, cableado, protecciones eléctricas y un sistema de monitoreo, todo instalado según el Reglamento Técnico de Instalaciones Eléctricas (RETIE). La calidad de cada componente y de la instalación determina si el sistema producirá lo esperado durante 25 años o más.","lecciones":[{"titulo":"Paneles e inversor","texto":"Los paneles generan; el inversor convierte y gestiona. Marca, garantía y eficiencia diferencian calidad.\n\nLos paneles monocristalinos dominan el mercado por su eficiencia; tecnologías como PERC, TOPCon o bifaciales mejoran la producción por metro cuadrado. Los inversores pueden ser de cadena (string), centrales o microinversores; en proyectos comerciales, los inversores de cadena son los más comunes por su equilibrio entre costo, eficiencia y facilidad de mantenimiento. Elegir fabricantes con respaldo local y garantías claras es tan importante como la potencia."},{"titulo":"Estructura","texto":"Fija los paneles a la cubierta. Debe respetar la resistencia del techo y resistir viento.\n\nLa estructura fija los paneles a la cubierta o al suelo y debe resistir viento, lluvia y corrosión durante décadas. En techos de teja metálica se usan sujeciones que no perforan o que se sellan adecuadamente; en losas, estructuras con inclinación y lastre. Antes de instalar, el equipo técnico verifica que la cubierta soporte el peso adicional, normalmente entre 12 y 20 kg por metro cuadrado."},{"titulo":"Monitoreo","texto":"Permite ver producción y detectar fallas en tiempo real desde el celular.\n\nEl monitoreo permite ver en línea la generación, el consumo y las alarmas del sistema. Es la herramienta que demuestra el ahorro al cliente y detecta problemas temprano: un inversor detenido, un string con bajo desempeño o suciedad acumulada. Para el gerente financiero, es también la evidencia que respalda el retorno prometido."}],"ejercicio":"Revisa una propuesta solar y verifica si incluye los cuatro componentes.","pasos":["Revisa una propuesta solar (o un ejemplo público) e identifica marca y potencia de paneles e inversor.","Busca la garantía de producto y de desempeño de cada uno.","Anota qué tipo de estructura se propone y para qué cubierta.","Escribe tres preguntas de calidad que un cliente debería hacer a cualquier proveedor."],"quiz":[{"pregunta":"¿Qué permite el monitoreo?","opciones":["Ver producción y detectar fallas","Limpiar paneles","Bajar la tarifa"],"correcta":0},{"pregunta":"¿Qué debe respetar la estructura?","opciones":["El color del techo","La resistencia de la cubierta","El horario"],"correcta":1},{"pregunta":"¿Qué reglamento rige las instalaciones eléctricas en Colombia?","opciones":["RETIE","NIIF","ISO 9001"],"correcta":0}],"accion":"Explica a un cliente qué comparar entre dos propuestas."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-vida-util', 'Solar · Vida útil', 181, true, 5, 'energia', 'flash',
          7, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'Cuánto dura un sistema y qué esperar con los años.', 't-roi', 86, '2026-01-01')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Vida útil de paneles e inversores","Qué es la degradación","Cómo se refleja en el análisis financiero"],"contexto":"Un sistema solar es un activo de largo plazo. Saber cuánto dura ayuda al cliente a verlo como inversión y no como gasto.\n\nLa vida útil es lo que convierte a la energía solar en una inversión y no en un gasto: un sistema bien diseñado sigue produciendo energía mucho después de haberse pagado. Los fabricantes de paneles ofrecen hoy garantías de desempeño de 25 a 30 años, y la experiencia de instalaciones antiguas en el mundo muestra que muchos sistemas superan ese plazo.","lecciones":[{"titulo":"Paneles","texto":"Suelen operar 25 años o más, con garantías de producción de largo plazo.\n\nLas garantías se dividen en dos: la de producto, que cubre defectos de fabricación y suele ser de 12 a 25 años, y la de desempeño, que asegura un porcentaje mínimo de potencia al final del periodo, normalmente entre 80% y 88% a los 25 o 30 años. Leer ambas permite comparar proveedores con criterio."},{"titulo":"Degradación","texto":"Producen un poco menos cada año, típicamente alrededor de 0,5% anual.\n\nLos paneles pierden un poco de potencia cada año. En módulos de calidad, la degradación anual está alrededor de 0,4% a 0,55%, después de una pérdida inicial algo mayor el primer año. Un análisis financiero serio incluye esta degradación: el sistema producirá un poco menos cada año, pero el efecto es pequeño frente al aumento esperado de la tarifa."},{"titulo":"Inversores","texto":"Duran del orden de 10 a 15 años; un buen análisis incluye su reemplazo.\n\nEl inversor trabaja intensamente convirtiendo energía todo el día y su vida útil típica es de 10 a 15 años. Por eso las proyecciones financieras suelen incluir un reemplazo a mitad de la vida del proyecto. Algunas marcas ofrecen extensiones de garantía, una opción que conviene evaluar para reducir incertidumbre."}],"ejercicio":"Revisa si el análisis de una propuesta incluye degradación y reemplazo de inversor.","pasos":["Calcula cuánta potencia tendría un sistema de 100 kWp después de 25 años con 0,5% de degradación anual.","Compara ese resultado con una garantía de desempeño del 84,8% a 25 años.","Anota en qué año incluirías el reemplazo del inversor en una proyección.","Escribe cómo explicarías a un gerente por qué la degradación no cambia la decisión."],"quiz":[{"pregunta":"¿Cuánto suelen durar los paneles?","opciones":["5 años","25 años o más","2 años"],"correcta":1},{"pregunta":"¿Qué componente se reemplaza antes?","opciones":["El inversor","La estructura","El techo"],"correcta":0},{"pregunta":"¿Cuál es la vida útil típica de un inversor?","opciones":["3 a 5 años","10 a 15 años","50 años"],"correcta":1}],"accion":"Usa “activo de 25 años” en tu próxima conversación."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-mantenimiento', 'Solar · Mantenimiento', 182, true, 5, 'energia', 'flash',
          5, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'Poco mantenimiento, pero no cero.', 't-solar', 84, '2026-02-08')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué mantenimiento requiere un sistema","Cada cuánto","Qué pasa si se descuida"],"contexto":"Un argumento clave para el cliente: un sistema solar casi no requiere mantenimiento. Aun así, un plan básico protege la inversión.\n\nUno de los argumentos más sólidos de la energía solar es su bajo mantenimiento. Sin embargo, “bajo” no significa “cero”: la suciedad, las sombras nuevas o una falla no detectada pueden reducir la producción durante meses sin que nadie lo note. Un plan sencillo de mantenimiento protege el retorno de la inversión.","lecciones":[{"titulo":"Limpieza","texto":"Polvo y hojas reducen producción. En zonas secas o industriales se limpia más seguido.\n\nLa frecuencia de limpieza depende del entorno. En zonas con polvo, cercanía a vías destapadas, industrias o actividad agrícola, la suciedad puede reducir la producción de forma notable y se recomiendan limpiezas frecuentes; en zonas lluviosas, la lluvia hace parte del trabajo. Se usa agua y herramientas suaves, sin químicos abrasivos, preferiblemente en horas de baja radiación."},{"titulo":"Inspección","texto":"Revisión periódica de conexiones, estructura e inversor.\n\nUna inspección anual revisa estructura, sujeciones, cableado, conectores, protecciones y tableros. La termografía —imágenes infrarrojas— permite detectar puntos calientes en celdas o conexiones antes de que se conviertan en fallas. También se verifica que no hayan aparecido sombras nuevas por árboles o construcciones vecinas."},{"titulo":"Monitoreo","texto":"Una caída de producción en la app es la primera alerta.\n\nEl monitoreo es la primera línea de mantenimiento. Comparar la producción real con la esperada según la radiación permite identificar desviaciones de inmediato. Un buen contrato de operación y mantenimiento define tiempos de respuesta ante alarmas y reportes periódicos al cliente, lo que también fortalece la relación de largo plazo."}],"ejercicio":"Pregunta a un cliente con sistema instalado cada cuánto lo limpia.","pasos":["Elige una empresa candidata de tu red.","Describe su entorno: ¿polvo, salinidad, lluvia, árboles cercanos?","Propón una frecuencia de limpieza razonable.","Escribe qué le dirías al gerente si pregunta “¿quién se encarga del mantenimiento?”."],"quiz":[{"pregunta":"¿Qué reduce la producción con más frecuencia?","opciones":["Suciedad en los paneles","La luna","El color del inversor"],"correcta":0},{"pregunta":"¿Cuál es la primera alerta de una falla?","opciones":["Caída de producción en el monitoreo","Ruido","Olor"],"correcta":0},{"pregunta":"¿Para qué sirve una inspección termográfica?","opciones":["Para medir la temperatura ambiente","Para detectar puntos calientes antes de que fallen","Para limpiar los paneles"],"correcta":1}],"accion":"Menciona el bajo mantenimiento como argumento con un cliente."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('solar-riesgos', 'Solar · Riesgos', 183, true, 5, 'energia', 'flash',
          6, 'Principiante', array['todos']::text[], 'aliado', false, false, false, false,
          'e2', 'Los riesgos reales y cómo se mitigan.', 't-diag', 82, '2026-03-15')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Riesgos técnicos y de operación","Riesgos de propiedad y permisos","Cómo se mitigan"],"contexto":"Hablar de riesgos con honestidad genera confianza. Casi todos se gestionan con buen diseño, seguros y contratos claros.\n\nToda inversión tiene riesgos, y presentarlos con honestidad aumenta la confianza del cliente. En energía solar, la mayoría de riesgos son conocidos y gestionables mediante buen diseño, contratos claros y monitoreo. Saber nombrarlos —y cómo se mitigan— te diferencia de quien solo habla de beneficios.","lecciones":[{"titulo":"Técnicos","texto":"Mal dimensionamiento o cubierta débil. Se mitiga con estudio de consumo y estructural.\n\nLos riesgos técnicos incluyen sombras no previstas, cubiertas en mal estado, errores de dimensionamiento y componentes de baja calidad. Se mitigan con visita técnica, estudio de sombras, revisión estructural, ingeniería conforme al RETIE y proveedores con garantías respaldadas en el país."},{"titulo":"Propiedad","texto":"Sede arrendada sin autorización del dueño. Se resuelve antes de avanzar.\n\nSi la empresa no es dueña del inmueble, necesita autorización del propietario y un contrato que cubra al menos el periodo de recuperación de la inversión. También hay que prever qué pasa si la empresa vende la sede o se traslada: los sistemas pueden desmontarse y reinstalarse, pero con un costo. Aclarar esto desde el inicio evita sorpresas en la negociación."},{"titulo":"Operativos","texto":"Robo, daño o caída de producción. Seguros, monitoreo y garantías cubren la mayoría.\n\nCambios en la operación —reducción de turnos, cierre de líneas, nuevos equipos— modifican el autoconsumo y, por tanto, el ahorro. A esto se suman los riesgos regulatorios, como cambios en las reglas de excedentes o en los incentivos tributarios. Un análisis de sensibilidad muestra cómo se comporta el proyecto en escenarios menos favorables y ayuda a tomar una decisión informada."}],"ejercicio":"Lista las tres dudas más comunes de tus contactos sobre solar y cómo se responden.","pasos":["Elige una empresa candidata.","Lista un riesgo técnico, uno de propiedad y uno operativo que podría tener.","Para cada uno, escribe cómo se mitigaría.","Prepara una frase para presentar los riesgos con transparencia, sin asustar al cliente."],"quiz":[{"pregunta":"¿Qué riesgo se resuelve antes de avanzar?","opciones":["Autorización del dueño de la sede","El color de los paneles","La marca del celular"],"correcta":0},{"pregunta":"¿Qué mitiga el robo?","opciones":["Póliza y anclajes","Apagar el sistema","Nada"],"correcta":0},{"pregunta":"¿Qué herramienta muestra cómo se comporta el proyecto en escenarios menos favorables?","opciones":["El análisis de sensibilidad","El logo del proveedor","El estudio de mercado"],"correcta":0}],"accion":"Prepara tu respuesta a la objeción de riesgo más común."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inversion-solar-capex', 'Inversión solar · CAPEX', 184, true, 5, 'energia', 'flash',
          5, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e3', 'Qué incluye la inversión inicial de un proyecto solar y cómo comparar propuestas que no son equivalentes.', 't-propuestas', 80, '2026-04-22')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué compone el CAPEX de un sistema solar empresarial","Por qué el costo por kWp solo sirve si las propuestas incluyen lo mismo","Los costos ocultos que cambian el valor real de una oferta","Cómo leer una propuesta como lo haría un comité de compras"],"contexto":"El CAPEX (capital expenditure) es la inversión inicial que la empresa desembolsa para tener el sistema funcionando. Es la cifra que más pesa en la primera reacción del gerente y, por eso, la que más se presta a comparaciones injustas.\n\nEn el mercado colombiano, un sistema comercial o industrial instalado sobre cubierta suele ubicarse, como referencia orientativa, entre $3 y $4,5 millones por kWp, según el tamaño, el tipo de cubierta, la marca de los equipos y el alcance de la ingeniería. Una diferencia de 20% entre dos ofertas rara vez se explica solo por eficiencia del proveedor: casi siempre hay componentes, estudios o garantías que una incluye y la otra no. Entender qué hay dentro del CAPEX te permite ayudar al cliente a comparar manzanas con manzanas.","lecciones":[{"titulo":"Los componentes del CAPEX","texto":"Equipos (módulos, inversores, estructura, cableado, protecciones), ingeniería, instalación, trámites y puesta en marcha.\n\nLos equipos suelen representar entre la mitad y dos tercios de la inversión. El resto corresponde a la ingeniería de detalle (diseño eléctrico, estudio de sombras, cálculo estructural), la mano de obra y el montaje, el transporte, la obra eléctrica hasta el punto de conexión, el sistema de monitoreo y la gestión de trámites: certificación RETIE, solicitud de conexión ante el operador de red y, si aplica, la solicitud de incentivos tributarios. Una propuesta completa detalla cada uno de estos bloques; una incompleta los agrupa en una sola línea."},{"titulo":"El costo por kWp: útil, pero engañoso","texto":"Divide el CAPEX entre la potencia instalada. Sirve para comparar solo cuando el alcance es idéntico.\n\nEl costo por kWp baja con el tamaño (economías de escala) y sube con la complejidad: cubiertas en fibrocemento que requieren refuerzo, alturas que exigen equipos de elevación, distancias largas al tablero o necesidad de transformador. Por eso, un sistema de 40 kWp en una cubierta compleja puede costar más por kWp que uno de 300 kWp en una bodega plana, sin que ninguno de los dos esté mal cotizado. Antes de comparar la cifra, compara el alcance."},{"titulo":"Lo que no se ve en la cifra","texto":"Garantías, calidad de los equipos, monitoreo, seguros y respaldo posventa cambian el valor real.\n\nUn módulo de fabricante reconocido (con presencia en listados de bancabilidad como los de BloombergNEF) suele ofrecer 12 a 15 años de garantía de producto y 25 a 30 años de garantía de producción lineal. Un inversor de marca con soporte local reduce el tiempo de reparación ante una falla. La garantía de instalación, el plan de mantenimiento incluido y el monitoreo en línea determinan cuánto producirá realmente el sistema durante 25 años. Una oferta 10% más barata que produce 8% menos por fallas o suciedad no es más barata."},{"titulo":"Cómo comparar dos propuestas","texto":"Normaliza el alcance, compara la producción estimada y calcula el costo por kWh producido durante la vida útil.\n\nLa forma más justa de comparar es pasar del costo por kWp al costo por kWh generado: CAPEX más costos de operación durante 25 años, dividido entre la energía total que producirá el sistema. Esta métrica, conocida como LCOE (costo nivelado de energía), premia la calidad y penaliza los atajos. Si el cliente no quiere hacer el cálculo completo, basta con una tabla que liste qué incluye cada oferta y cuántos kWh al año promete cada una."}],"ejercicio":"Construye una lista de chequeo con todo lo que debería incluir un CAPEX completo y úsala para revisar una propuesta real o de ejemplo.","pasos":["Escribe los cinco bloques del CAPEX: equipos, ingeniería, instalación, trámites y puesta en marcha.","Debajo de cada bloque, anota dos o tres elementos concretos (ej.: estudio estructural, certificación RETIE, monitoreo).","Toma una propuesta solar (de un cliente o de ejemplo) y marca qué elementos incluye y cuáles no.","Calcula su costo por kWp y escribe qué podría explicar una diferencia con otra oferta.","Redacta una pregunta que le harías al proveedor sobre lo que falta."],"quiz":[{"pregunta":"¿Cuándo es válido comparar dos ofertas por costo por kWp?","opciones":["Siempre","Solo si el alcance es equivalente","Nunca"],"correcta":1},{"pregunta":"¿Qué suele quedar por fuera de las ofertas más baratas?","opciones":["Trámites, estudios y garantías","Los módulos","El inversor"],"correcta":0},{"pregunta":"¿Qué métrica compara mejor la calidad de dos sistemas en el largo plazo?","opciones":["Costo por kWp","Costo por kWh producido en la vida útil (LCOE)","Número de paneles"],"correcta":1},{"pregunta":"¿Por qué un sistema pequeño puede costar más por kWp?","opciones":["Porque no aprovecha economías de escala y puede tener mayor complejidad","Porque usa menos paneles","No puede costar más"],"correcta":0}],"accion":"Antes de que un cliente compare dos propuestas, ayúdale a revisar qué incluye cada una con tu lista de chequeo."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inversion-solar-ahorro', 'Inversión solar · Ahorro', 185, true, 5, 'energia', 'flash',
          6, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e3', 'Cómo pasar de kWh producidos a pesos ahorrados, con la tarifa correcta y una proyección realista.', 't-roi', 78, '2026-05-02')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
