insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué es el payback simple y el descontado","Cómo calcularlo con o sin incentivos","Qué rangos son razonables en Colombia","Por qué el payback no basta para decidir"],"contexto":"El payback responde la pregunta que casi todos los gerentes hacen primero: ¿en cuánto tiempo recupero mi plata? Es intuitivo, fácil de comunicar y funciona como filtro inicial.\n\nEn proyectos solares comerciales e industriales en Colombia, el payback simple suele ubicarse entre 4 y 7 años, según la tarifa, el porcentaje de autoconsumo, la irradiación y el uso de los incentivos de la Ley 1715. Frente a una vida útil de 25 años o más, eso significa que el sistema trabaja gratis durante la mayor parte de su vida. Pero el payback tiene limitaciones conocidas en finanzas corporativas, y saberlas te da credibilidad frente a un área financiera.","lecciones":[{"titulo":"Payback simple","texto":"CAPEX ÷ flujo neto anual (ahorro − costos de operación) = años para recuperar la inversión.\n\nEjemplo: un CAPEX de $420 millones con un ahorro anual de $100 millones y costos de mantenimiento de $4 millones da un flujo neto de $96 millones y un payback cercano a 4,4 años. Si el ahorro crece cada año, el payback real es algo menor, porque los flujos de los años siguientes son más altos que el del primero. Para una conversación inicial, el cálculo simple es suficiente."},{"titulo":"Payback con incentivos","texto":"La deducción de renta de la Ley 1715 reduce el impuesto a pagar y acorta el tiempo de recuperación.\n\nCuando la empresa puede aplicar la deducción de hasta el 50% de la inversión en el impuesto de renta, el beneficio tributario funciona como un flujo adicional. Con una tarifa de renta corporativa del 35%, deducir $210 millones (50% de $420 millones) significa pagar hasta $73,5 millones menos de impuesto, distribuidos según la capacidad de la empresa y en el plazo que permite la norma. Ese flujo puede bajar el payback de 4,4 a cerca de 3,5 años. El contador del cliente debe validar si la empresa tiene renta suficiente para aprovecharlo."},{"titulo":"Payback descontado","texto":"Trae los flujos futuros a valor presente con el costo de capital: es más exigente y más realista.\n\nEl payback simple trata igual un peso de hoy y uno de dentro de cinco años. El payback descontado divide cada flujo entre (1 + tasa)^año antes de sumarlo. Con una tasa del 14%, un payback simple de 4,4 años puede convertirse en un payback descontado de 5,5 a 6 años. Si el área financiera del cliente usa este indicador, es mejor mostrarlo tú antes de que lo calculen ellos."},{"titulo":"Lo que el payback no mide","texto":"No dice nada de lo que pasa después de recuperar la inversión ni compara el tamaño del valor creado.\n\nDos proyectos con el mismo payback pueden crear valores muy distintos: uno de 5 años de vida y otro de 25. Por eso el payback se complementa con el VPN y la TIR. La forma más útil de presentarlo es en una frase: “recupera la inversión en cerca de cuatro años y medio, y luego tiene más de veinte años de ahorro”. Así el gerente ve tanto la velocidad como la magnitud."}],"ejercicio":"Calcula el payback simple y con incentivos de un proyecto con datos conocidos.","pasos":["Usa estos datos o los de un cliente: CAPEX $300 millones, ahorro anual $70 millones, mantenimiento $3 millones.","Calcula el flujo neto anual y el payback simple.","Calcula el beneficio tributario: 50% del CAPEX × 35% de tarifa de renta.","Resta ese beneficio del CAPEX y recalcula el payback.","Escribe la frase con la que explicarías el resultado a un gerente."],"quiz":[{"pregunta":"Payback simple =","opciones":["Ahorro ÷ CAPEX","CAPEX ÷ flujo neto anual","CAPEX × vida útil"],"correcta":1},{"pregunta":"¿Qué rango de payback es habitual en proyectos solares empresariales en Colombia?","opciones":["1 a 2 años","4 a 7 años","15 a 20 años"],"correcta":1},{"pregunta":"¿Qué hace el payback descontado?","opciones":["Ignora el valor del dinero en el tiempo","Trae los flujos a valor presente con el costo de capital","Suma los incentivos dos veces"],"correcta":1},{"pregunta":"¿Qué limitación tiene el payback?","opciones":["No mide el valor creado después de la recuperación","No usa el CAPEX","Solo sirve para bancos"],"correcta":0}],"accion":"Explica a un cliente su payback en una frase que incluya los años de ahorro posteriores."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inversion-solar-tir', 'Inversión solar · TIR', 187, true, 5, 'energia', 'flash',
          5, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e3', 'La rentabilidad anual del proyecto solar y cómo usarla para competir con otras inversiones.', 't-roi', 74, '2026-07-16')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Qué mide la TIR y en qué se diferencia del VPN","Con qué compararla: costo de capital y alternativas","TIR del proyecto vs. TIR del inversionista","Cómo presentarla a un gerente financiero"],"contexto":"La TIR (tasa interna de retorno) expresa la rentabilidad de un proyecto como una tasa anual. Su gran ventaja es que permite comparar el sistema solar con cualquier otra alternativa de la empresa: ampliar una línea, comprar maquinaria o dejar el dinero en un CDT.\n\nLos proyectos solares comerciales bien dimensionados en Colombia suelen mostrar TIR del proyecto en un rango aproximado de 15% a 25% en pesos, y más cuando se aplican los incentivos tributarios. Para un gerente financiero acostumbrado a evaluar proyectos frente a un costo de capital del 12% al 16%, ese rango es atractivo. Pero la TIR tiene matices que conviene conocer para no perder credibilidad.","lecciones":[{"titulo":"Qué es la TIR","texto":"La tasa de descuento que hace que el valor presente de todos los flujos del proyecto sea igual a cero.\n\nSi un proyecto tiene una TIR del 20%, significa que el dinero invertido rinde, en promedio, el equivalente a un 20% anual durante la vida del proyecto. Se calcula con la función TIR de cualquier hoja de cálculo a partir de una serie de flujos: el año cero negativo (la inversión) y los años siguientes positivos (ahorro menos costos). Es la métrica favorita de las áreas financieras porque resume en un número la eficiencia del capital."},{"titulo":"Con qué compararla","texto":"Con el costo de capital de la empresa (WACC) o con la rentabilidad de las alternativas que compiten por el mismo dinero.\n\nSi la TIR supera el costo de capital, el proyecto crea valor. El costo de capital combina lo que cuesta la deuda de la empresa y lo que esperan ganar los accionistas. En la práctica, muchas PyMEs no lo tienen calculado y usan una tasa de referencia: la tasa de su crédito, la rentabilidad de su negocio principal o la de un CDT. Preguntar “¿qué rentabilidad mínima le exigen a una inversión?” te da la vara con la que medirán el proyecto."},{"titulo":"TIR del proyecto y TIR con financiación","texto":"Con deuda, la TIR sobre el capital propio sube, pero también el riesgo. Hay que saber cuál se está mostrando.\n\nLa TIR del proyecto supone que la empresa paga todo con recursos propios. Si financia parte con un crédito a una tasa menor que la TIR, la rentabilidad sobre el dinero que realmente pone el accionista aumenta (efecto apalancamiento). Ambas cifras son correctas, pero responden preguntas distintas. Presentar la TIR apalancada sin aclararlo puede generar desconfianza cuando el área financiera haga su propio cálculo."},{"titulo":"Cómo presentarla","texto":"Compárala con una alternativa concreta y acompáñala del VPN, que muestra cuánto valor crea en pesos.\n\nUna TIR aislada no convence; una comparación sí. “Este proyecto rinde cerca del 21% anual; su CDT rinde 10% y su costo de crédito es 15%” es una frase que un CFO entiende de inmediato. El VPN complementa: una TIR alta en un proyecto pequeño crea poco valor; una TIR moderada en un proyecto grande puede crear mucho más. Juntas, las dos métricas cuentan la historia completa."}],"ejercicio":"Calcula la TIR de un proyecto simple en una hoja de cálculo y compárala con dos alternativas.","pasos":["Abre una hoja de cálculo y escribe en la celda del año 0 el CAPEX en negativo (ej.: −300.000.000).","En los años 1 a 25 escribe el flujo neto, con un crecimiento anual de 3% y una degradación de 0,5%.","Usa la función TIR sobre la serie completa.","Busca dos tasas de comparación: la de un CDT y la de un crédito empresarial actual.","Escribe una frase que compare la TIR con ambas alternativas."],"quiz":[{"pregunta":"¿Con qué se compara la TIR?","opciones":["Con el costo de capital o alternativas de inversión","Con el tamaño de la cubierta","Con la tarifa de energía"],"correcta":0},{"pregunta":"Una TIR mayor al costo de capital indica que el proyecto…","opciones":["Destruye valor","Crea valor","Es irrelevante"],"correcta":1},{"pregunta":"¿Qué pasa con la TIR del accionista si se financia con deuda más barata que la TIR del proyecto?","opciones":["Baja","Sube, junto con el riesgo","No cambia"],"correcta":1},{"pregunta":"¿Qué métrica complementa la TIR mostrando el valor creado en pesos?","opciones":["El VPN","El costo por kWp","La irradiación"],"correcta":0}],"accion":"Presenta en tu próxima conversación una TIR comparada con una alternativa concreta del cliente."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inversion-solar-flujo-de-caja', 'Inversión solar · Flujo de caja', 188, true, 5, 'energia', 'flash',
          6, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e3', 'Cómo se mueve el dinero del proyecto año a año, con y sin financiación.', 't-roi', 72, '2026-08-23')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Construir un flujo de caja de un proyecto solar","Qué ingresos y egresos incluir, y cuándo","Cómo cambia el flujo con financiación","Cómo leerlo como lo lee un comité"],"contexto":"El flujo de caja muestra, año a año, cuánto dinero sale y cuánto entra. Es la herramienta que convierte el ahorro en una historia financiera clara y la base sobre la que se calculan el payback, el VPN y la TIR.\n\nPara quien firma la inversión, el flujo de caja responde una pregunta muy concreta: ¿este proyecto me quita caja o me la da? En proyectos financiados, la respuesta puede ser sorprendente: si la cuota mensual es menor que el ahorro mensual, el proyecto genera caja positiva desde el primer mes, sin que la empresa desembolse recursos propios significativos.","lecciones":[{"titulo":"Año cero","texto":"La inversión inicial (o la cuota inicial si hay financiación) y los costos de puesta en marcha.\n\nEl año cero concentra la salida grande: equipos, instalación, trámites. Si hay financiación, solo sale la porción que la empresa aporta (por ejemplo, 20% o 30%) y los costos de estructuración del crédito. Es importante registrar también el momento en que llegan los beneficios tributarios, que suelen materializarse en la declaración de renta del año siguiente."},{"titulo":"Años siguientes","texto":"Ahorro que crece con la tarifa, menos mantenimiento, seguros, monitoreo y reemplazos programados.\n\nLos egresos recurrentes de un sistema solar son bajos: limpieza de módulos, mantenimiento preventivo y correctivo, seguro todo riesgo y, a veces, el servicio de monitoreo. Como referencia, suelen estar entre 1% y 2% del CAPEX al año. El egreso extraordinario más conocido es el reemplazo del inversor, cuya vida útil típica está entre 10 y 15 años; un flujo bien construido lo programa en esa ventana."},{"titulo":"Con financiación","texto":"La cuota del crédito o del leasing se resta del ahorro. Si la cuota es menor, el flujo es positivo desde el inicio.\n\nUn crédito a 7 años con una cuota inferior al ahorro mensual hace que el proyecto se pague con su propio ahorro y deje un excedente desde el primer mes. Al terminar el plazo, la empresa recibe el ahorro completo durante el resto de la vida útil. Este es el argumento que más convence a empresas con caja ajustada o con otras prioridades de inversión."},{"titulo":"Cómo lo lee un comité","texto":"Mira tres cosas: cuánto sale al inicio, cuándo se vuelve positivo el acumulado y qué tan sensible es a los supuestos.\n\nEl flujo acumulado —la suma año a año— muestra el punto en que el proyecto recupera la inversión. Un gráfico con barras anuales y una línea del acumulado es la forma más clara de presentarlo. Acompáñalo de una nota sobre los supuestos: incremento de tarifa, degradación, costos de operación y momento del reemplazo del inversor. Lo que el comité valora es la transparencia."}],"ejercicio":"Arma un flujo de caja a 10 años con CAPEX, ahorro creciente, mantenimiento y reemplazo de inversor.","pasos":["Escribe en columnas los años 0 a 10.","Año 0: CAPEX en negativo. Años 1–10: ahorro con crecimiento de 4% anual.","Resta un mantenimiento anual equivalente al 1,5% del CAPEX.","Agrega en el año 10 un egreso por reemplazo de inversor (≈ 8% del CAPEX).","Calcula el flujo acumulado y marca el año en que se vuelve positivo."],"quiz":[{"pregunta":"Si la cuota del crédito es menor que el ahorro mensual…","opciones":["El flujo es negativo","El flujo es positivo desde el inicio","No hay ahorro"],"correcta":1},{"pregunta":"¿Qué egreso extraordinario suele programarse entre los años 10 y 15?","opciones":["Reemplazo del inversor","Cambio de todos los paneles","Ninguno"],"correcta":0},{"pregunta":"¿Cuánto representan aproximadamente los costos anuales de operación?","opciones":["1% a 2% del CAPEX","20% del CAPEX","50% del ahorro"],"correcta":0},{"pregunta":"¿Qué muestra el flujo acumulado?","opciones":["El tamaño del techo","El momento en que se recupera la inversión","La tarifa futura"],"correcta":1}],"accion":"Muestra a un cliente cómo se vería su flujo de caja con financiación frente a pago de contado."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inversion-solar-financiacion', 'Inversión solar · Financiación', 189, true, 5, 'energia', 'flash',
          7, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e3', 'Crédito, leasing y pago por energía: opciones para que el cliente no comprometa su caja.', 't-financiacion', 70, '2026-09-03')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las modalidades de financiación disponibles","Ventajas, costos y efectos contables de cada una","Cómo elegir según la prioridad del cliente","Cómo presentar la financiación sin prometer condiciones"],"contexto":"Muchas empresas quieren el ahorro, pero no quieren comprometer caja que necesitan para su operación o crecimiento. La financiación convierte el proyecto en una cuota que se paga, total o parcialmente, con el mismo ahorro que genera.\n\nEl sistema financiero colombiano ha desarrollado líneas específicas para eficiencia energética y energías renovables, impulsado por el Protocolo Verde firmado entre el Gobierno y Asobancaria en 2012 y, más recientemente, por la Taxonomía Verde de Colombia (2022), que clasifica la energía solar como actividad sostenible. Bancos comerciales, Bancóldex y entidades de leasing ofrecen alternativas cuyas condiciones define cada entidad según el perfil del cliente. Tu papel no es ofrecer tasas, sino mostrar que la financiación existe y conectar al cliente con quien puede estructurarla.","lecciones":[{"titulo":"Crédito para energía","texto":"Préstamo de largo plazo para comprar el sistema. El activo queda a nombre de la empresa desde el inicio.\n\nEl crédito permite que la empresa sea dueña del sistema y aplique directamente los beneficios tributarios de la Ley 1715. Algunos bancos tienen líneas verdes con plazos más largos o condiciones especiales, a veces con redescuento de Bancóldex o Findeter. El criterio clave es el plazo: cuanto más largo, menor la cuota y más probable que el ahorro la cubra por completo."},{"titulo":"Leasing financiero","texto":"La entidad compra el activo y lo entrega en arrendamiento con opción de compra al final.\n\nEl leasing es común en activos productivos. La empresa paga cánones periódicos y, al final del plazo, ejerce una opción de compra. Puede tener ventajas en el manejo tributario de los cánones y, en ciertos casos, en el uso de los incentivos, lo que debe validar el contador. Es una opción frecuente cuando la empresa ya tiene otros créditos y prefiere no aumentar su endeudamiento bancario tradicional."},{"titulo":"Pago por energía (PPA o renting)","texto":"Un tercero invierte, instala y opera el sistema; la empresa paga por la energía producida o una cuota fija.\n\nEn un contrato de compra de energía (PPA) on-site, el inversionista es dueño del sistema y vende la energía al cliente a un precio por kWh menor que su tarifa actual, durante un plazo largo (10 a 20 años). La empresa no invierte CAPEX, ahorra desde el primer mes y no se ocupa del mantenimiento. La contrapartida: el ahorro total es menor que si comprara el sistema y los incentivos tributarios quedan para el inversionista."},{"titulo":"Cómo elegir y presentar","texto":"Pregunta qué prioriza el cliente: maximizar el ahorro, proteger su caja o no tener activos en balance.\n\nSi la prioridad es el mayor ahorro posible y tiene caja o capacidad de endeudamiento, compra con recursos propios o crédito. Si quiere preservar caja sin renunciar a la propiedad, crédito largo o leasing. Si no quiere invertir ni operar, PPA. Nunca menciones tasas, plazos ni aprobaciones: cada entidad define sus condiciones. La frase segura es: “Existen alternativas de financiación; el equipo de GEENERA puede presentarle opciones con nuestros aliados financieros”."}],"ejercicio":"Identifica qué modalidad de financiación le convendría a tres clientes con prioridades distintas.","pasos":["Describe tres empresas: una con caja holgada, una con caja ajustada y una que no quiere activos.","Para cada una, escribe su prioridad principal (ahorro, caja, balance).","Asigna la modalidad más adecuada y una razón en una frase.","Escribe qué pregunta le harías a cada cliente para confirmar su prioridad.","Redacta la frase con la que presentarías la financiación sin mencionar tasas."],"quiz":[{"pregunta":"¿Qué modalidad evita que la empresa invierta CAPEX?","opciones":["Pago por energía (PPA)","Compra de contado","Crédito de consumo"],"correcta":0},{"pregunta":"¿Cuál es el objetivo ideal de la cuota de financiación?","opciones":["Ser mayor que el ahorro","Ser menor o igual que el ahorro","No importa"],"correcta":1},{"pregunta":"En un PPA, ¿quién aprovecha normalmente los incentivos tributarios?","opciones":["El cliente","El inversionista dueño del sistema","Nadie"],"correcta":1},{"pregunta":"¿Qué nunca debes prometer como aliado?","opciones":["Que existe financiación","Tasas, plazos o aprobaciones","Que GEENERA puede presentar opciones"],"correcta":1}],"accion":"Pregunta a un cliente qué prioriza (ahorro, caja o balance) y comparte la respuesta con tu consultora."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inversion-solar-incentivos', 'Inversión solar · Incentivos', 190, true, 5, 'energia', 'flash',
          5, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e3', 'Beneficios tributarios de la Ley 1715 de 2014 y la Ley 2099 de 2021, y cómo afectan la rentabilidad.', 't-roi', 68, '2026-01-10')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Los cuatro incentivos tributarios principales","Quién puede usarlos y qué requisitos exigen","Cómo cambian el payback y la TIR","Por qué siempre debe validarlos el contador"],"contexto":"Colombia tiene uno de los marcos de incentivos para energías renovables más completos de la región. La Ley 1715 de 2014 creó beneficios tributarios para las inversiones en fuentes no convencionales de energía, y la Ley 2099 de 2021 los amplió y extendió.\n\nEstos incentivos pueden mejorar de forma importante la rentabilidad de un proyecto, pero no son automáticos: requieren una certificación previa (hoy gestionada ante la UPME) y que la empresa tenga la capacidad tributaria para aprovecharlos. Como aliado, tu papel es mencionarlos siempre y recomendar que el contador del cliente los valide; nunca prometer un beneficio específico.","lecciones":[{"titulo":"Deducción especial en renta","texto":"Hasta el 50% del valor de la inversión, deducible en un periodo de hasta 15 años desde el año siguiente a la entrada en operación.\n\nLa deducción no puede superar el 50% de la renta líquida del contribuyente en cada año. Por eso, una empresa con utilidades estables la aprovecha en pocos años, mientras que una con pérdidas o baja renta puede tardar más o no aprovecharla del todo. Con una tarifa de renta del 35%, deducir el 50% de una inversión de $400 millones equivale a pagar hasta $70 millones menos de impuestos a lo largo del periodo."},{"titulo":"Exclusión de IVA","texto":"Los equipos, elementos, maquinaria y servicios destinados al proyecto pueden estar excluidos de IVA.\n\nCon la certificación correspondiente, la compra de módulos, inversores y otros elementos, así como ciertos servicios asociados, puede quedar excluida del IVA del 19%. Este beneficio reduce directamente el CAPEX y se materializa en la compra, no en la declaración de renta, por lo que es especialmente valioso para empresas que no pueden descontar el IVA."},{"titulo":"Exención arancelaria","texto":"Exención del pago de aranceles para equipos importados destinados al proyecto que no se produzcan en el país.\n\nComo la mayoría de módulos e inversores son importados, este beneficio reduce el costo de los equipos. Lo gestiona normalmente el proveedor o importador con la certificación del proyecto, y su efecto ya suele estar incorporado en el precio de la propuesta."},{"titulo":"Depreciación acelerada","texto":"Permite depreciar los activos del proyecto a una tasa anual de hasta 33,33%, lo que adelanta el beneficio fiscal.\n\nEn lugar de depreciar el sistema en 20 o más años, la empresa puede hacerlo en tres, lo que reduce la base gravable en los primeros años y mejora el valor presente del proyecto. La depreciación acelerada y la deducción especial pueden combinarse según las reglas de la norma, y es aquí donde el criterio del contador es imprescindible."}],"ejercicio":"Prepara una explicación de un minuto sobre los incentivos de la Ley 1715 para un gerente que no los conoce.","pasos":["Escribe los cuatro incentivos en una línea cada uno, en lenguaje simple.","Calcula un ejemplo: inversión de $300 millones, deducción del 50%, tarifa de renta del 35%.","Agrega la condición clave: requiere certificación previa y renta suficiente.","Cierra con la recomendación de validarlo con su contador.","Practica la explicación en voz alta en menos de un minuto."],"quiz":[{"pregunta":"¿Hasta qué porcentaje de la inversión puede deducirse en renta?","opciones":["10%","50%","100%"],"correcta":1},{"pregunta":"¿En qué plazo puede tomarse la deducción especial tras la Ley 2099?","opciones":["1 año","Hasta 15 años","Hasta 50 años"],"correcta":1},{"pregunta":"¿Qué incentivo reduce directamente el CAPEX en la compra?","opciones":["Exclusión de IVA","Depreciación acelerada","Deducción en renta"],"correcta":0},{"pregunta":"¿Quién debe validar la aplicación de los incentivos?","opciones":["El contador del cliente","Nadie","El instalador"],"correcta":0}],"accion":"Pregunta a un cliente si su contador conoce los incentivos de la Ley 1715 y ofrece conectarlo con GEENERA."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('inversion-solar-riesgo', 'Inversión solar · Riesgo', 191, true, 5, 'energia', 'flash',
          6, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e3', 'Los riesgos que afectan el retorno de un proyecto solar y cómo mostrarlos con un análisis de sensibilidad.', 't-roi', 66, '2026-02-17')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Riesgos técnicos, de mercado y de contraparte","Cómo se mitiga cada uno","Análisis de sensibilidad en tres escenarios","Cómo responder las preguntas difíciles del CFO"],"contexto":"Un buen análisis financiero no solo muestra el escenario esperado: muestra qué pasa si algo sale distinto. Eso es lo que da tranquilidad a un comité y lo que diferencia una propuesta comercial de un análisis serio.\n\nLos proyectos solares tienen un perfil de riesgo relativamente bajo frente a otras inversiones productivas: tecnología madura, sin combustible, pocas partes móviles y producción predecible con datos de irradiación de décadas. Aun así, hay variables que pueden mover el retorno, y reconocerlas abiertamente aumenta la confianza del cliente en el resto de las cifras.","lecciones":[{"titulo":"Riesgo de producción","texto":"Menos energía de la estimada por sombras no previstas, suciedad, fallas o una irradiación menor al promedio.\n\nSe mitiga con un buen diseño (estudio de sombras, datos de irradiación de fuentes como PVGIS o NASA POWER), equipos de calidad, monitoreo en línea que detecta caídas de producción en días y un plan de limpieza y mantenimiento. La variación anual de la irradiación en Colombia suele ser moderada, de unos pocos puntos porcentuales frente al promedio histórico."},{"titulo":"Riesgo de tarifa y regulación","texto":"Si la tarifa baja o cambian las reglas de excedentes, el ahorro cambia.\n\nHistóricamente, la tarifa de energía en Colombia ha tendido a subir en términos nominales, con periodos de alzas fuertes asociados a la inflación y a fenómenos climáticos como El Niño. Un escenario conservador asume una tarifa estable sin crecimiento real. El riesgo regulatorio sobre excedentes se reduce dimensionando el sistema para maximizar el autoconsumo, que depende solo de la tarifa del cliente."},{"titulo":"Riesgo del cliente y del sitio","texto":"Cambio de sede, cierre de una línea de producción o problemas de cubierta pueden afectar el proyecto.\n\nAntes de invertir conviene confirmar que la empresa permanecerá en la sede durante el periodo de recuperación, que la cubierta tiene vida útil suficiente (o repararla antes de instalar) y que el consumo diurno no caerá. En sedes arrendadas, un acuerdo con el propietario es indispensable."},{"titulo":"Análisis de sensibilidad","texto":"Muestra payback, TIR y VPN en escenarios pesimista, base y optimista, variando una cosa a la vez.\n\nLas variables que más mueven el resultado son la producción, la tarifa y el CAPEX. Una tabla sencilla —por ejemplo, producción −15%, tarifa sin crecimiento y CAPEX +10%— permite ver si el proyecto sigue siendo atractivo en el peor caso razonable. Cuando incluso el escenario pesimista supera el costo de capital, la conversación cambia de “¿y si sale mal?” a “¿cuándo empezamos?”."}],"ejercicio":"Diseña el escenario pesimista que le mostrarías a un cliente conservador y explica por qué es razonable.","pasos":["Toma un proyecto de ejemplo con payback de 4,5 años y TIR de 20%.","Define tres variables de riesgo: producción, tarifa y CAPEX.","Para cada una, propone un valor pesimista razonable (ej.: −15%, 0% de crecimiento, +10%).","Escribe cómo se mitiga cada riesgo en la práctica.","Redacta una frase para el comité que resuma el resultado del escenario pesimista."],"quiz":[{"pregunta":"¿Qué muestra un análisis de sensibilidad?","opciones":["Solo el mejor caso","Los resultados bajo distintos escenarios","El precio del panel"],"correcta":1},{"pregunta":"¿Qué riesgo se detecta y mitiga con monitoreo en línea?","opciones":["Caída de producción","Cambio de gerente","Inflación"],"correcta":0},{"pregunta":"¿Cómo se reduce el riesgo regulatorio sobre excedentes?","opciones":["Sobredimensionando el sistema","Maximizando el autoconsumo","Ignorándolo"],"correcta":1},{"pregunta":"¿Qué debe confirmarse en una sede arrendada?","opciones":["El color de la fachada","Un acuerdo con el propietario","Nada"],"correcta":1}],"accion":"Pide a tu consultora un escenario pesimista para el cliente más conservador de tu cartera."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('detectar-oportunidades-que-empresas-son-atractivas', 'Detectar oportunidades · Qué empresas son atractivas', 192, true, 5, 'energia', 'flash',
          5, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e4', 'Los sectores y perfiles con mayor potencial solar, y los que conviene evitar.', 't-solar', 64, '2026-03-24')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Sectores con mayor potencial en Colombia","Tamaño mínimo razonable de una oportunidad","Perfiles que conviene evitar","Cómo enfocarte mejora tu calidad de referidos"],"contexto":"No todas las empresas son buenas candidatas para un proyecto solar. Saber cuáles sí te ahorra tiempo, protege tu reputación como referidor y mejora tu Quality Score en el programa.\n\nUna buena candidata combina cuatro condiciones: consumo relevante, operación que coincide con las horas de sol, espacio disponible y capacidad de decisión sobre la sede. Hay sectores donde estas condiciones aparecen con mucha frecuencia y otros donde casi nunca se cumplen. Enfocar tu prospección en los primeros es la forma más rápida de aumentar la proporción de referidos que avanzan.","lecciones":[{"titulo":"Sectores con mayor potencial","texto":"Manufactura, alimentos, cadena de frío, comercio de gran superficie, hoteles, clínicas, colegios y agroindustria.\n\nLa manufactura con motores, compresores, hornos eléctricos o inyección de plásticos tiene consumos altos y operación diurna. La cadena de frío (frigoríficos, centros de distribución refrigerados, lácteos) consume todo el día y tiene grandes cubiertas. Supermercados y centros comerciales combinan refrigeración y climatización. Hoteles, clínicas y colegios tienen sede propia y consumo estable. La agroindustria con bombeo, riego o procesamiento suma terrenos disponibles."},{"titulo":"Tamaño mínimo","texto":"Como referencia, facturas desde $3 a $5 millones mensuales empiezan a justificar un proyecto empresarial.\n\nPor debajo de ese rango, el sistema resultante es pequeño y los costos fijos (ingeniería, trámites, logística) pesan más sobre la inversión, lo que alarga el payback. Esto no significa que una empresa más pequeña no pueda instalar, sino que suele ser una oportunidad de menor prioridad. Las facturas superiores a $15 millones al mes suelen ser oportunidades prioritarias."},{"titulo":"Perfiles a evitar","texto":"Oficinas pequeñas arrendadas, operación exclusivamente nocturna, empresas en crisis de caja o sedes que se trasladarán pronto.\n\nUna oficina en un piso de edificio rara vez controla la cubierta. Un negocio que opera solo de noche aprovecha poco la generación sin almacenamiento. Una empresa en dificultades financieras no aprobará una inversión ni calificará para financiación. Referir estos perfiles no suma Puntos Sol y puede restar calidad."},{"titulo":"El efecto en tu calidad","texto":"Enfocarte en sectores clave aumenta tus referidos calificados y tu Quality Score.\n\nEl Quality Score del programa pondera la calificación, el cumplimiento del Referido Perfecto y el avance a evaluación técnica. Un aliado que filtra antes de referir envía menos oportunidades, pero más avanzan, y eso se refleja en su nivel y en la confianza del equipo comercial. La regla práctica: si dudas, aplica el Opportunity Checker antes de registrar."}],"ejercicio":"Lista cinco empresas de tu red que pertenezcan a sectores de alto potencial y clasifícalas por prioridad.","pasos":["Escribe 10 empresas de tu red, sin filtrar.","Marca las que pertenecen a sectores de alto potencial.","Descarta las que tengan un perfil a evitar y anota el motivo.","Para las restantes, estima el rango de factura mensual.","Ordena las cinco mejores y elige una para referir esta semana."],"quiz":[{"pregunta":"¿Cuál es mejor candidata?","opciones":["Oficina arrendada pequeña","Planta de alimentos con sede propia","Bar de operación nocturna"],"correcta":1},{"pregunta":"¿Desde qué rango de factura mensual empieza a justificarse un proyecto empresarial?","opciones":["$300.000","$3 a $5 millones","$500 millones"],"correcta":1},{"pregunta":"¿Por qué una empresa en crisis de caja no es buena candidata?","opciones":["Porque no aprobará la inversión ni calificará para financiación","Porque consume poco","Sí es buena candidata"],"correcta":0},{"pregunta":"Enfocarte en sectores clave…","opciones":["Baja tu calidad","Mejora tu calidad de referidos","No cambia nada"],"correcta":1}],"accion":"Refiere esta semana una empresa de un sector de alto potencial, con los datos del Referido Perfecto."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('detectar-oportunidades-consumo', 'Detectar oportunidades · Consumo', 193, true, 5, 'energia', 'flash',
          6, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e4', 'Cómo estimar si el consumo de una empresa justifica un proyecto solar.', 't-factura', 62, '2026-04-04')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Señales visibles de consumo alto","Cómo preguntar por la factura sin incomodar","Rangos de referencia para priorizar","De consumo a tamaño aproximado del sistema"],"contexto":"El consumo es la primera señal de una oportunidad. Sin consumo relevante, no hay ahorro relevante, y sin ahorro relevante la inversión no se justifica.\n\nLa buena noticia es que el consumo suele ser fácil de detectar: se ve en los equipos, en la operación y, sobre todo, en la factura, una cifra que casi todos los gerentes conocen de memoria porque es uno de sus costos fijos más visibles. Con una pregunta bien hecha y una regla de conversión simple, puedes estimar en minutos si vale la pena profundizar.","lecciones":[{"titulo":"Señales visibles","texto":"Maquinaria, refrigeración, hornos eléctricos, aire acondicionado central, compresores o turnos largos.\n\nRecorre mentalmente la operación: ¿hay cuartos fríos, líneas de producción, bombas, extractores, iluminación de grandes áreas? En climas cálidos, la climatización puede representar más de la mitad del consumo de un hotel, una clínica o un centro comercial. En manufactura, los motores eléctricos concentran buena parte de la demanda. Cada uno de estos equipos es una pista de consumo alto."},{"titulo":"La pregunta","texto":"“¿Más o menos cuánto pagan de energía al mes?” Es directa, natural y casi todos saben responderla.\n\nFormúlala en contexto: después de hablar de costos, de crecimiento o de la operación. Si el gerente no sabe la cifra exacta, pide un rango. Si la respuesta es alta, la siguiente pregunta es “¿ha cambiado mucho en el último año?”, que abre la conversación sobre volatilidad y control del costo."},{"titulo":"Rangos de referencia","texto":"Menos de $3 millones: baja prioridad. De $3 a $15 millones: buena candidata. Más de $15 millones: prioritaria.\n\nEstos rangos son orientativos y cambian con la tarifa de cada región y el tipo de usuario. Lo importante es el orden de magnitud: una factura de $40 millones mensuales indica un consumo cercano a 50.000 kWh, suficiente para un sistema de cientos de kWp. Una de $1 millón probablemente no justifica una visita técnica empresarial."},{"titulo":"De la factura al tamaño","texto":"Divide el valor mensual entre el costo unitario para obtener los kWh, y esos kWh entre 120 para estimar los kWp.\n\nEjemplo: $12 millones ÷ $800/kWh = 15.000 kWh al mes. Si se quiere cubrir el 50% del consumo diurno, 7.500 kWh ÷ 120 ≈ 62 kWp. Con unos 6 m² por kWp, se necesitarían cerca de 370 m² de cubierta. Este cálculo exprés no reemplaza el diseño técnico, pero te permite hablar con números desde la primera conversación."}],"ejercicio":"Pregunta a tres contactos cuánto pagan de energía al mes y estima el tamaño aproximado del sistema para cada uno.","pasos":["Elige tres empresas de tu red con alguna señal visible de consumo.","Haz la pregunta de la factura en una conversación natural.","Convierte cada valor a kWh con un costo unitario de referencia de $800.","Estima los kWp para cubrir el 50% del consumo.","Clasifica cada empresa según los rangos de prioridad."],"quiz":[{"pregunta":"¿Qué pregunta revela el consumo más rápido?","opciones":["¿Cuántos empleados tienen?","¿Cuánto pagan de energía al mes?","¿De qué color es el techo?"],"correcta":1},{"pregunta":"¿Qué equipo indica consumo alto?","opciones":["Refrigeración industrial","Un teléfono","Una lámpara de escritorio"],"correcta":0},{"pregunta":"Una factura de $12 millones con costo de $800/kWh equivale a…","opciones":["1.500 kWh","15.000 kWh","150.000 kWh"],"correcta":1},{"pregunta":"¿Qué rango de factura indica una oportunidad prioritaria?","opciones":["Menos de $1 millón","Más de $15 millones","Cualquiera"],"correcta":1}],"accion":"Haz la pregunta del consumo en tu próxima conversación y anota el resultado en tu radar."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('detectar-oportunidades-operacion', 'Detectar oportunidades · Operación', 194, true, 5, 'energia', 'flash',
          7, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e4', 'Por qué el horario de operación define cuánto ahorra realmente un sistema solar.', 't-solar', 60, '2026-05-11')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["La relación entre perfil de consumo y producción solar","Qué operaciones aprovechan mejor la generación","Qué hacer con operaciones 24/7 o nocturnas","Cómo preguntar por el horario"],"contexto":"Un sistema solar produce energía entre las 6 a. m. y las 6 p. m., con un pico alrededor del mediodía. Cuanto más coincida el consumo de la empresa con esa curva, mayor es el autoconsumo y, por tanto, el ahorro.\n\nEsto importa porque, bajo la regulación colombiana, la energía que se consume en el momento evita el costo unitario completo, mientras que los excedentes que se entregan a la red se reconocen a un valor generalmente menor. Dos empresas con la misma factura pueden tener ahorros muy distintos según su horario.","lecciones":[{"titulo":"Operación diurna","texto":"Fábricas de un turno, colegios, oficinas, comercio y bodegas aprovechan casi toda la producción.\n\nCuando la operación arranca temprano y termina al final de la tarde, el sistema puede dimensionarse para que casi toda su energía se consuma en sitio. Un colegio que opera de 6 a. m. a 4 p. m. de lunes a viernes, por ejemplo, puede autoconsumir la gran mayoría de su producción en días hábiles; los fines de semana y vacaciones generan excedentes que deben considerarse en el diseño."},{"titulo":"Operación continua (24/7)","texto":"Clínicas, hoteles, frío y manufactura de tres turnos también son buenas candidatas: el sistema cubre la parte diurna.\n\nEn estas empresas el consumo diurno nunca baja de un mínimo (la carga base), así que toda la energía solar se autoconsume. El sistema cubre un porcentaje menor de la factura total, pero cada kWh generado se aprovecha. Para el cliente, el mensaje es: “el sistema reduce la parte diurna de su factura; la noche sigue igual”."},{"titulo":"Operación nocturna","texto":"Negocios que operan solo de noche aprovechan poco la generación, salvo con almacenamiento o excedentes.\n\nSin baterías, toda la energía de un negocio nocturno sería excedente. Las baterías han bajado de precio, pero todavía encarecen de forma importante la inversión y alargan el payback. Por eso, estas empresas suelen ser oportunidades de menor prioridad, salvo que tengan otra sede o un consumo diurno relevante (bodega, oficinas administrativas)."},{"titulo":"La pregunta y la curva","texto":"“¿En qué horario trabaja la planta?” y “¿cuándo están encendidos los equipos grandes?” revelan el perfil.\n\nLas empresas con medidores avanzados pueden descargar su curva de carga horaria del operador de red; es el dato más preciso para el diseño. Si no la tienen, basta conocer turnos, días de operación y los equipos principales. Anotar esta información en el referido ahorra una llamada al equipo técnico."}],"ejercicio":"Clasifica cinco empresas de tu red según su horario de operación y su aprovechamiento esperado.","pasos":["Lista cinco empresas de tu red.","Escribe el horario y los días de operación de cada una (pregunta si no lo sabes).","Clasifícalas: diurna, continua o nocturna.","Anota el aprovechamiento esperado: alto, medio o bajo.","Agrega el horario en los datos de tu próximo referido."],"quiz":[{"pregunta":"¿Qué operación aprovecha mejor la producción solar?","opciones":["Diurna","Nocturna","Solo fines de semana"],"correcta":0},{"pregunta":"En una clínica 24/7, el sistema solar…","opciones":["No sirve","Cubre la parte diurna y todo se autoconsume","Solo funciona con diésel"],"correcta":1},{"pregunta":"¿Por qué el autoconsumo vale más que los excedentes?","opciones":["Porque evita el costo unitario completo","Porque la energía es diferente","Valen igual"],"correcta":0},{"pregunta":"¿Qué dato es el más preciso para el diseño?","opciones":["La curva de carga horaria","El número de empleados","El sector"],"correcta":0}],"accion":"Pregunta el horario de operación a tu próximo contacto e inclúyelo en el referido."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('detectar-oportunidades-cubierta', 'Detectar oportunidades · Cubierta', 195, true, 5, 'energia', 'flash',
          5, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e4', 'Cómo estimar si hay espacio para instalar y qué tipo de cubierta conviene.', 't-solar', 58, '2026-06-18')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Área necesaria por kWp","Tipos de cubierta y su viabilidad","Cómo estimar el área con una imagen satelital","Alternativas cuando no hay techo"],"contexto":"Sin espacio no hay proyecto. Estimar el área disponible te permite saber, antes de referir, si la empresa podría instalar un sistema del tamaño que su consumo justifica.\n\nLa cubierta es también uno de los puntos que más dudas genera en el cliente: ¿aguanta el peso?, ¿se va a gotear?, ¿qué pasa si hay que repararla? Conocer lo básico te permite responder con tranquilidad y anticipar la información que el equipo técnico pedirá.","lecciones":[{"titulo":"Área de referencia","texto":"Del orden de 5 a 7 m² de cubierta útil por cada kWp instalado.\n\nLa cifra depende de la potencia de los módulos (los actuales superan los 550 W por unidad), de la inclinación y de los pasillos que se dejan para mantenimiento. Un sistema de 100 kWp necesita entre 500 y 700 m² útiles. Hay que descontar áreas con sombra de tanques, muros, equipos o edificios vecinos, y zonas con claraboyas o ductos."},{"titulo":"Tipos de cubierta","texto":"Teja metálica (termoacústica o trapezoidal), losa de concreto y fibrocemento son las más comunes; cada una requiere un tipo de estructura.\n\nLa teja metálica es la más sencilla: la estructura se fija a las correas con sistemas que preservan la impermeabilidad. La losa permite estructuras con lastre o ancladas y una inclinación óptima. El fibrocemento exige más cuidado porque es frágil, y a veces conviene reemplazarlo antes de instalar. En todos los casos, un estudio estructural confirma que la cubierta soporta la carga adicional, que suele estar entre 12 y 20 kg/m²."},{"titulo":"Estimar con imagen satelital","texto":"Herramientas de mapas permiten medir el área de una cubierta en un par de minutos.\n\nCon Google Earth o Google Maps puedes trazar el contorno de la cubierta y obtener su área aproximada. Descuenta un 30% por bordes, obstáculos y pasillos y divide entre 6 para estimar la potencia máxima. Si el resultado supera el tamaño que justifica el consumo, el espacio no será la restricción. Este dato, incluido en el referido, acelera la evaluación."},{"titulo":"Alternativas sin techo","texto":"Parqueaderos con estructura (carports), terrenos aledaños o cubiertas de otras sedes.\n\nLos carports convierten un parqueadero en un espacio de generación y además dan sombra a los vehículos; su estructura es más costosa que una instalación en cubierta. Los terrenos permiten sistemas sobre suelo con estructura fija o seguidores. Si la empresa tiene varias sedes en la misma zona del operador de red, conviene explorar las reglas de autogeneración remota o de comunidades energéticas con el equipo técnico."}],"ejercicio":"Estima con una imagen satelital el área de cubierta de una empresa de tu red y su potencia máxima.","pasos":["Busca la dirección de la empresa en Google Earth o Google Maps.","Traza el contorno de la cubierta principal y anota el área.","Descuenta 30% por obstáculos y pasillos.","Divide el área útil entre 6 para estimar los kWp máximos.","Compara con el tamaño que justifica su consumo y anota la conclusión."],"quiz":[{"pregunta":"¿Cuánta área ocupa aproximadamente 1 kWp?","opciones":["0,5 m²","5 a 7 m²","50 m²"],"correcta":1},{"pregunta":"¿Qué tipo de cubierta exige más cuidado por su fragilidad?","opciones":["Losa de concreto","Fibrocemento","Teja metálica"],"correcta":1},{"pregunta":"¿Qué confirma que la cubierta soporta la carga?","opciones":["Una foto","Un estudio estructural","La opinión del cliente"],"correcta":1},{"pregunta":"Si no hay techo disponible…","opciones":["No hay opción","Carports, terrenos u otras sedes","Paredes interiores"],"correcta":1}],"accion":"Estima el área de cubierta de una empresa antes de referirla e inclúyela en los datos."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('detectar-oportunidades-ubicacion', 'Detectar oportunidades · Ubicación', 196, true, 5, 'energia', 'flash',
          6, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e4', 'Cómo influyen la ciudad, la región y el operador de red en un proyecto solar.', 't-solar', 56, '2026-07-25')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Irradiación solar en Colombia","Regiones con mejor rendimiento","Por qué casi todo el país es viable","Qué cambia según el operador de red"],"contexto":"Colombia, por su ubicación cerca de la línea del Ecuador, recibe radiación solar relativamente constante durante todo el año. La ubicación cambia el rendimiento de un sistema, pero rara vez lo vuelve inviable.\n\nSegún el Atlas de Radiación Solar del IDEAM y la UPME, el promedio nacional de irradiación global horizontal está cerca de 4,5 kWh/m² por día, con valores superiores a 5,5 en zonas de La Guajira, el Caribe y algunas áreas de los Llanos y los Santanderes. Esta es una ventaja frente a muchos países donde la energía solar ya es masiva, con irradiaciones menores y estaciones marcadas.","lecciones":[{"titulo":"Irradiación","texto":"La cantidad de energía solar que llega a una superficie. En Colombia está, en general, entre 3,5 y 6 kWh/m² por día.\n\nLa irradiación determina cuánto produce cada kWp instalado. Una diferencia de 15% en la irradiación se traduce en una diferencia similar en la producción y en el ahorro. Los diseñadores usan bases de datos satelitales con promedios de muchos años para estimar la producción de cada sitio con buena precisión."},{"titulo":"Regiones con mejor rendimiento","texto":"Caribe, La Guajira, Cesar, Santanderes, Huila y los Llanos suelen tener los mejores rendimientos.\n\nEn estas zonas, un kWp puede producir más de 1.500 kWh al año. Además, en el Caribe y en ciudades cálidas el consumo por climatización es alto y coincide con las horas de mayor radiación, lo que combina buena producción con alto autoconsumo. Es una de las razones por las que la región ha concentrado buena parte de los nuevos proyectos solares del país."},{"titulo":"Ciudades nubladas","texto":"Bogotá y otras zonas andinas producen algo menos, pero con buena tarifa los proyectos siguen siendo rentables.\n\nUn mismo sistema puede producir entre 10% y 20% menos en Bogotá que en Valledupar. Si la tarifa del cliente es alta y la operación es diurna, el proyecto sigue siendo atractivo. Por eso, nunca descartes una empresa solo por la ciudad: la combinación de tarifa, consumo y autoconsumo pesa más que la irradiación."},{"titulo":"El operador de red","texto":"Cada región tiene un operador con su propia tarifa y sus tiempos de trámite de conexión.\n\nEl operador de red (Air-e, Afinia, EPM, Enel, Essa, Celsia, CENS, entre otros) define parte del costo unitario a través del componente de distribución y gestiona la solicitud de conexión del sistema. Conocer el operador del cliente ayuda a estimar la tarifa y anticipar los tiempos del trámite, por lo que es un dato útil en cualquier referido."}],"ejercicio":"Identifica en qué región y con qué operador de red están tus tres mejores contactos.","pasos":["Elige tus tres contactos con mayor potencial.","Anota la ciudad y el departamento de la sede principal.","Identifica el operador de red de cada uno.","Clasifica la irradiación de cada zona: alta, media o moderada.","Escribe qué argumento usarías en cada caso (rendimiento, tarifa o autoconsumo)."],"quiz":[{"pregunta":"¿Suele la ubicación volver inviable un proyecto en Colombia?","opciones":["Sí, casi siempre","Rara vez","Solo en el Caribe"],"correcta":1},{"pregunta":"¿Cuál es aproximadamente el promedio nacional de irradiación?","opciones":["1 kWh/m² día","4,5 kWh/m² día","12 kWh/m² día"],"correcta":1},{"pregunta":"¿Qué región suele tener alto rendimiento?","opciones":["Caribe y La Guajira","Ninguna","Solo Bogotá"],"correcta":0},{"pregunta":"¿Por qué importa el operador de red?","opciones":["Define parte de la tarifa y gestiona la conexión","Fabrica los paneles","No importa"],"correcta":0}],"accion":"No descartes una empresa solo por la ciudad: revisa su tarifa y su horario antes de decidir."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('detectar-oportunidades-factura', 'Detectar oportunidades · Factura', 197, true, 5, 'energia', 'flash',
          7, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e4', 'Las cifras de la factura que convierten una conversación en una oportunidad real.', 't-factura', 54, '2026-08-05')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las cifras clave de la factura","Cómo calcular el costo unitario real","Qué revela el histórico de consumo","Cómo pedir la factura como un beneficio"],"contexto":"La factura convierte una conversación en una oportunidad real. Con ella, el equipo técnico de GEENERA puede estimar el tamaño del sistema, el ahorro y el payback desde la primera llamada.\n\nEs el dato que más acelera el proceso comercial: un referido con factura adjunta se ubica en verde en el semáforo del Referido Perfecto y suele recibir un diagnóstico preliminar mucho antes que uno sin ella. Saber qué mirar en una factura, y cómo pedirla, es una de las habilidades más rentables para un aliado.","lecciones":[{"titulo":"Valor total y consumo","texto":"El valor total da la dimensión del costo; los kWh del periodo, la dimensión del sistema.\n\nEl valor total incluye energía, contribución y, a veces, cobros de terceros como alumbrado público o aseo. Para dimensionar se usa el consumo en kWh del periodo. Muchas facturas comerciales muestran por separado la energía activa y la reactiva; la activa es la que interesa para el sistema solar, y la reactiva puede indicar oportunidades de eficiencia adicionales."},{"titulo":"Costo unitario real","texto":"Valor de la energía ÷ kWh consumidos. Si paga contribución, el costo efectivo es 20% mayor.\n\nEl costo unitario aparece en la factura como “CU” o “valor kWh”. Para un comercio que paga contribución, el costo que realmente evita cada kWh autogenerado incluye ese recargo. Un costo unitario alto, combinado con operación diurna, es la mejor señal de un payback corto."},{"titulo":"El histórico","texto":"El gráfico de los últimos seis a doce meses revela estabilidad, estacionalidad y tendencia.\n\nUn consumo estable permite dimensionar con precisión. Picos en ciertos meses pueden explicarse por temporadas comerciales, cosechas o turnos adicionales. Un consumo creciente indica que la empresa está expandiéndose, lo que justifica dimensionar pensando en el futuro. Pregunta por cualquier variación grande: la respuesta suele revelar información útil sobre la operación."},{"titulo":"Cómo pedirla","texto":"Preséntala como la forma de recibir una cifra real, no como un trámite.\n\n“Para que te den una cifra real de ahorro, y no un estimado genérico, necesitan una factura reciente. ¿Me la compartes y se la hago llegar?” Así la factura deja de ser un requisito y se convierte en el primer beneficio para el cliente. Si duda, aclara que solo se usa para dimensionar y que no implica ningún compromiso."}],"ejercicio":"Pide la factura a un contacto usando el argumento de la cifra real y ubica sus cifras clave.","pasos":["Elige un contacto con quien ya hayas hablado de costos de energía.","Envíale el mensaje para pedir la factura con el argumento de la cifra real.","Cuando la recibas, ubica valor total, kWh, costo unitario y contribución.","Revisa el histórico y anota si el consumo es estable, estacional o creciente.","Adjunta la factura al registrar el referido en el Hub."],"quiz":[{"pregunta":"¿Para qué sirve el costo unitario?","opciones":["Estimar el ahorro por kWh autogenerado","Saber el horario","Medir el techo"],"correcta":0},{"pregunta":"¿Qué revela un consumo creciente en el histórico?","opciones":["Que la empresa se está expandiendo","Que el medidor está dañado","Nada"],"correcta":0},{"pregunta":"¿Cómo conviene pedir la factura?","opciones":["Como un requisito obligatorio","Como la forma de obtener una cifra real de ahorro","No pedirla"],"correcta":1},{"pregunta":"¿Qué color del semáforo tiene un referido con decisor, autorización y factura?","opciones":["Verde","Amarillo","Rojo"],"correcta":0}],"accion":"Adjunta la factura en tu próximo referido para que quede en verde."}'::jsonb from m
on conflict (modulo_id) do nothing;
with m as (
  insert into public.modulos (codigo, nombre, orden, activo, puntos, escuela, formato, minutos, nivel, aliados, acceso,
                              destacado, nuevo, popular, rapido, ruta, descripcion, herramienta, popularidad, publicado)
  values ('detectar-oportunidades-preguntas-de-diagnostico', 'Detectar oportunidades · Preguntas de diagnóstico', 198, true, 5, 'energia', 'flash',
          5, 'Intermedio', array['todos']::text[], 'aliado', false, false, false, false,
          'e4', 'Cinco preguntas para calificar una empresa en una conversación, sin sonar a vendedor.', 't-diag', 52, '2026-09-12')
  on conflict (codigo) do update set nombre = excluded.nombre
  returning id
)
insert into public.modulos_contenido (modulo_id, contenido)
select id, '{"aprenderas":["Las cinco preguntas clave","En qué orden hacerlas","Cómo interpretar las respuestas","Cómo cerrar con un siguiente paso"],"contexto":"Con cinco preguntas bien formuladas puedes saber, en una conversación de diez minutos, si una empresa es candidata a un proyecto solar. Y puedes hacerlo sin sonar a vendedor, porque son preguntas sobre el negocio del otro, no sobre tu producto.\n\nLa investigación sobre ventas consultivas, desde el trabajo de Neil Rackham con más de 35.000 llamadas comerciales que dio origen al método SPIN, muestra que las conversaciones exitosas en ventas complejas tienen más preguntas y menos presentación. Las preguntas correctas ayudan al cliente a descubrir por sí mismo el valor de la solución.","lecciones":[{"titulo":"Consumo y operación","texto":"“¿Más o menos cuánto pagan de energía al mes?” y “¿en qué horario opera la empresa?”.\n\nEstas dos preguntas confirman las dos señales más importantes: consumo relevante y coincidencia con las horas de sol. Hazlas cuando la conversación ya esté en temas de costos u operación, no como primera frase. Si la respuesta a la primera es baja, puedes cerrar el tema con amabilidad sin invertir más tiempo."},{"titulo":"Sede y espacio","texto":"“¿La sede es propia?” y “¿tienen techo amplio o algún terreno disponible?”.\n\nLa propiedad define quién decide sobre la cubierta y si la empresa permanecerá el tiempo necesario para recuperar la inversión. Si es arrendada, pregunta si el contrato es de largo plazo y si el propietario autorizaría obras. El espacio confirma que el sistema cabe; si el gerente no sabe el área, puedes estimarla después con una imagen satelital."},{"titulo":"Decisión","texto":"“Si apareciera una inversión que se paga sola en pocos años, ¿quién la aprobaría?”.\n\nEsta pregunta identifica al decisor sin preguntar directamente “¿usted decide?”, que puede incomodar. La respuesta te dice si hablas con quien firma, con quien influye o con quien solo opera. Si no es el decisor, pide una introducción: “¿Te parece si lo conversamos juntos con él?”."},{"titulo":"Interpretar y cerrar","texto":"Cuatro o cinco respuestas positivas: refiere esta semana. Tres: completa la información. Menos: deja en seguimiento.\n\nLa última pregunta de la conversación siempre debe proponer un siguiente paso concreto: “¿Te parecería útil que un especialista de GEENERA revise tu factura y te muestre una cifra real, sin compromiso?”. Si la respuesta es sí, confirma el contacto, pide la factura y registra el referido el mismo día, mientras la conversación está fresca."}],"ejercicio":"Escribe las cinco preguntas con tus propias palabras y practícalas en una conversación real.","pasos":["Escribe las cinco preguntas adaptadas a tu forma de hablar.","Define en qué momento de la conversación harías cada una.","Escribe la pregunta de cierre que propone un siguiente paso.","Usa las preguntas en una conversación esta semana.","Anota las respuestas y clasifica la empresa según el número de respuestas positivas."],"quiz":[{"pregunta":"¿Qué pregunta identifica al decisor sin incomodar?","opciones":["¿Usted decide?","¿Quién aprobaría una inversión que se paga sola?","¿Cuántos años tiene la empresa?"],"correcta":1},{"pregunta":"¿Qué hacer si la sede es arrendada?","opciones":["Descartar de inmediato","Preguntar por el plazo del contrato y la autorización del propietario","Ignorarlo"],"correcta":1},{"pregunta":"Con cuatro o cinco respuestas positivas…","opciones":["Esperar un año","Referir esta semana","Descartar"],"correcta":1},{"pregunta":"¿Con qué debe terminar la conversación?","opciones":["Con una presentación del producto","Con un siguiente paso concreto","Sin cierre"],"correcta":1}],"accion":"Usa las cinco preguntas en tu próxima reunión y registra el referido el mismo día."}'::jsonb from m
on conflict (modulo_id) do nothing;

